def persist_active_sport(sport: str) -> None:
    """Update analyzer routing state without triggering a query-string rerun."""
    sport = str(sport or "").strip().lower()
    if sport not in _VALID_SPORTS:
        return
    st.session_state.active_sport = sport


def persist_active_view(view: str) -> None:
    """Update product routing state without triggering a query-string rerun."""
    view = str(view or "").strip().lower()
    if view not in _VALID_VIEWS:
        return
    st.session_state.active_view = view


def sync_navigation_query() -> None:
    """Persist the completed route in one URL update after navigation."""
    try:
        sport = str(st.session_state.get("active_sport", "mlb")).lower()
        view = str(st.session_state.get("active_view", "analyze")).lower()
        if sport not in _VALID_SPORTS or view not in _VALID_VIEWS:
            return
        current_sport = st.query_params.get("sport", "")
        current_view = st.query_params.get("view", "")
        if isinstance(current_sport, list):
            current_sport = current_sport[0] if current_sport else ""
        if isinstance(current_view, list):
            current_view = current_view[0] if current_view else ""
        if (
            str(current_sport).strip().lower() == sport
            and str(current_view).strip().lower() == view
        ):
            return
        params = dict(st.query_params)
        params.update({"sport": sport, "view": view})
        st.query_params.from_dict(params)
    except Exception:
        pass


def record_debug_error(area: str, err) -> None:
    """Store compact runtime diagnostics without interrupting the app."""
    try:
        msg = str(err)
        st.session_state.runtime_debug_errors.append({
            "area": area,
            "message": msg[:500],
            "time": datetime.utcnow().isoformat() + "Z",
        })
        st.session_state.runtime_debug_errors = st.session_state.runtime_debug_errors[-20:]
    except Exception:
        pass


def add_to_pick_list(leg: dict) -> None:
    """Add/update a visible PrizePicks shortlist leg in session state."""
    if "parlay_legs" not in st.session_state:
        st.session_state.parlay_legs = []
    legs = st.session_state.parlay_legs
    player = str(leg.get("player", ""))
    sport = str(leg.get("sport", ""))
    prop = str(leg.get("prop", ""))
    side = str(leg.get("side", ""))
    try:
        line = float(leg.get("line", 0))
    except Exception:
        line = leg.get("line")

    for i, existing in enumerate(legs):
        try:
            same_line = abs(float(existing.get("line", 0)) - float(line)) < 0.1
        except Exception:
            same_line = str(existing.get("line", "")) == str(line)
        same_pick = (
            str(existing.get("player", "")) == player
            and str(existing.get("sport", "")) == sport
            and str(existing.get("prop", "")) == prop
            and str(existing.get("side", "")) == side
            and same_line
        )
        if same_pick:
            legs[i] = {**existing, **leg}
            st.session_state.parlay_notice = f"Updated {player} in your pick list."
            return

    if len(legs) >= 6:
        st.session_state.parlay_notice = "Pick list full. Remove one before adding another."
        return

    legs.append(leg)
    st.session_state.parlay_notice = f"Added {player} to your pick list."


def add_to_pick_list_and_tracker(leg: dict, entry: dict) -> None:
    """Add a shortlist pick and preserve its probability for calibration."""
    add_to_pick_list(leg)
    try:
        tracker = st.session_state.setdefault("tracker", [])
        player = str(entry.get("Player", ""))
        line = str(entry.get("Line", ""))
        matchup = str(entry.get("Matchup", ""))
        existing_idx = next(
            (
                i for i, old in enumerate(tracker)
                if str(old.get("Player", "")) == player
                and str(old.get("Line", "")) == line
                and str(old.get("Matchup", "")) == matchup
            ),
            None,
        )
        if existing_idx is not None:
            old_id = tracker[existing_idx].get("id")
            tracker[existing_idx] = {**entry, **({"id": old_id} if old_id else {})}
            if old_id:
                delete_from_supabase(old_id)
            new_id = save_to_supabase(st.session_state.session_id, entry)
            if new_id:
                tracker[existing_idx]["id"] = new_id
        else:
            new_id = save_to_supabase(st.session_state.session_id, entry)
            if new_id:
                entry = {**entry, "id": new_id}
            tracker.append(entry)
        st.session_state.parlay_notice = (
            f"Added {player} to your pick list and calibration tracker."
        )
    except Exception as err:
        record_debug_error("tracker.add_calibration", err)


@st.cache_data(ttl=3600, show_spinner=False)
def _sorted_player_choices(options: tuple) -> tuple:
    """Normalize a roster once instead of re-sorting it on every app rerun."""
    return tuple(sorted(
        {str(option).strip() for option in options if str(option).strip()},
        key=lambda name: normalize_name(name),
    ))


def player_typeahead(label: str, options: list, key: str,
                     prefill: Optional[str] = None,
                     aliases: Optional[dict] = None,
                     noun: str = "player",
                     sport: Optional[str] = None) -> Optional[str]:
    """Editable player search with native, client-side suggestions."""
    choices = _sorted_player_choices(tuple(options or ()))
    alias_map = {
        normalize_name(alias): full_name
        for alias, full_name in (aliases or {}).items()
    }
    canonical_prefill = alias_map.get(normalize_name(prefill or ""), prefill)
    index = choices.index(canonical_prefill) if canonical_prefill in choices else None

    def _commit_search_change() -> None:
        pinned_sport = str(
            sport or st.session_state.get("active_sport", "mlb")
        ).strip().lower()
        if pinned_sport not in _ANALYZER_SPORTS:
            pinned_sport = "mlb"
        previous = st.session_state.get(f"{key}__committed")
        selected = st.session_state.get(key)
        st.session_state.active_view = "analyze"
        st.session_state.active_sport = pinned_sport
        st.session_state.last_analyzer_sport = pinned_sport
        st.session_state[f"{key}__committed"] = selected
        if selected == previous:
            return
        if pinned_sport == "nba":
            st.session_state.logs = None
            st.session_state.ai_analysis = None

    raw = st.selectbox(
        label,
        options=choices,
        index=index,
        key=key,
        placeholder=f"Type a {noun} name...",
        accept_new_options=True,
        on_change=_commit_search_change,
        help=f"Start typing any part of the {noun}'s name; matching suggestions filter instantly.",
    )
    if raw:
        st.session_state[f"{key}__committed"] = raw
    else:
        raw = st.session_state.get(f"{key}__committed")
    if not raw:
        return None
    raw_text = str(raw).strip()
    normalized = normalize_name(raw_text)
    if normalized in alias_map:
        return alias_map[normalized]
    exact = next((name for name in choices if normalize_name(name) == normalized), None)
    if exact:
        return exact
    # If a partial name was submitted instead of tapping a suggestion, resolve
    # it only when the match is unambiguous.
    matches = [
        name for name in choices
        if normalized in normalize_name(name)
        or all(
            token in normalize_name(name)
            for token in normalized.split()
            if len(token) >= 2
        )
    ]
    if len(matches) == 1:
        return matches[0]

    # Resolve a clear typo only when one candidate is substantially closer
    # than every other option. This catches "Shohei Othani" without guessing
    # between genuinely ambiguous names.
    if len(normalized) >= 6:
        from difflib import SequenceMatcher
        ranked = sorted(
            (
                (SequenceMatcher(None, normalized, normalize_name(name)).ratio(), name)
                for name in choices
            ),
            reverse=True,
        )
        if ranked:
            best_score, best_name = ranked[0]
            next_score = ranked[1][0] if len(ranked) > 1 else 0.0
            if best_score >= 0.86 and best_score - next_score >= 0.04:
                return best_name
    return raw_text


def set_navigation_scroll_target(target: str) -> None:
    """Request a one-time scroll after switching analyzer views."""
    st.session_state["_navigation_scroll_target"] = target


def navigate_to_view(view: str, target: str = "workspace-top") -> None:
    """Switch product destinations while preserving analyzer and scanner state."""
    view = str(view or "").strip().lower()
    if view not in _VALID_VIEWS:
        return
    current_sport = str(st.session_state.get("active_sport", "mlb")).lower()
    if view == "analyze":
        analyzer_sport = str(st.session_state.get("last_analyzer_sport", "mlb")).lower()
        if analyzer_sport not in _ANALYZER_SPORTS:
            analyzer_sport = "mlb"
        st.session_state.active_sport = analyzer_sport
        if target == "workspace-top":
            target = f"{analyzer_sport}-analyzer-controls"
    elif view == "edge":
        if current_sport in _ANALYZER_SPORTS:
            st.session_state.last_analyzer_sport = current_sport
        st.session_state.active_sport = "edge"
        if target == "workspace-top":
            target = "edge-scanner-controls"
    st.session_state.active_view = view
    set_navigation_scroll_target(target)
    sync_navigation_query()


def navigate_to_sport(sport: str, target: str) -> None:
    """Single-pass navigation callback used by tabs and analyzer links."""
    sport = str(sport or "").strip().lower()
    if sport not in _ANALYZER_SPORTS:
        sport = "mlb"
        target = "mlb-analyzer-controls"
    st.session_state.last_analyzer_sport = sport
    st.session_state.active_view = "analyze"
    st.session_state.active_sport = sport
    st.session_state.active_tab = "player"
    set_navigation_scroll_target(target)
    sync_navigation_query()


def open_edge_analyzer(sport: str, player: str, line: float,
                       side: str, stat: str) -> None:
    """Open an Edge result in its analyzer without an extra rerun."""
    sport_key = str(sport or "").strip().lower()
    target = f"{sport_key}-analyzer-controls"
    st.session_state.edge_return_available = True
    viewed_key = f"{sport_key}|{normalize_name(player)}|{stat}|{side}|{line}"
    viewed = list(st.session_state.get("edge_viewed", []) or [])
    if viewed_key not in viewed:
        viewed.append(viewed_key)
        st.session_state.edge_viewed = viewed[-200:]
    if sport_key == "nba":
        st.session_state.edge_jump_player = player
        st.session_state.edge_jump_line = line
        st.session_state.edge_jump_side = side
    elif sport_key == "mlb":
        st.session_state.edge_jump_pitcher = player
        st.session_state.edge_jump_line = line
        st.session_state.edge_jump_side = side
        st.session_state.edge_jump_prop = stat
    else:
        return
    navigate_to_sport(sport_key, target)


def open_pick_list_analyzer(leg: dict) -> None:
    """Reopen a saved pick in the matching analyzer."""
    sport_key = str(leg.get("sport", "mlb") or "mlb").strip().lower()
    if sport_key not in _ANALYZER_SPORTS:
        sport_key = "mlb"
    player = str(leg.get("player", ""))
    side = str(leg.get("side", "Over") or "Over")
    line = leg.get("line", 0)
    prop = str(leg.get("prop", ""))
    stat = re.sub(r"\s+(Over|Under)\s*$", "", prop, flags=re.IGNORECASE).strip()
    if not stat:
        stat = "Strikeouts" if sport_key == "mlb" else "Points"
    st.session_state.edge_return_available = False
    if sport_key == "nba":
        st.session_state.edge_jump_player = player
        st.session_state.edge_jump_line = line
        st.session_state.edge_jump_side = side
    elif sport_key == "mlb":
        st.session_state.edge_jump_pitcher = player
        st.session_state.edge_jump_line = line
        st.session_state.edge_jump_side = side
        st.session_state.edge_jump_prop = stat
    navigate_to_sport(sport_key, f"{sport_key}-analyzer-controls")


