def render_navigation_scroll_target(target: str) -> None:
    """Scroll the parent Streamlit page to a freshly rendered analyzer."""
    if st.session_state.get("_navigation_scroll_target") != target:
        return
    st.session_state.pop("_navigation_scroll_target", None)
    try:
        import json as _json
        import streamlit.components.v1 as _components
        target_json = _json.dumps(target)
        _components.html(
            f"""
            <script>
            (() => {{
                const targetId = {target_json};
                const scrollToTarget = () => {{
                    const doc = window.parent.document;
                    const node = doc.getElementById(targetId);
                    if (node) {{
                        node.scrollIntoView({{behavior: "auto", block: "start"}});
                    }}
                }};
                window.parent.requestAnimationFrame(scrollToTarget);
                window.parent.setTimeout(scrollToTarget, 120);
            }})();
            </script>
            """,
            height=0,
            width=0,
        )
    except Exception as err:
        record_debug_error("ui.navigation_scroll", err)


def _parse_percent_value(value, default: Optional[float] = None) -> Optional[float]:
    """Return probability as 0-1 from values like '64.2%', 64.2, or 0.642."""
    try:
        if value is None or value == "":
            return default
        if isinstance(value, str):
            raw = value.strip().replace("%", "")
            if raw in ("", "—", "N/A"):
                return default
            num = float(raw)
            return num / 100.0 if num > 1 else num
        num = float(value)
        return num / 100.0 if num > 1 else num
    except Exception:
        return default


def _parse_numeric_value(value, default: Optional[float] = None) -> Optional[float]:
    try:
        if value is None or value == "":
            return default
        if isinstance(value, str):
            raw = value.strip().replace("%", "").replace("+", "")
            if raw in ("", "—", "N/A"):
                return default
            return float(raw)
        return float(value)
    except Exception:
        return default


MODEL_LEARNING_VERSION = "propiq-v8.6-mlb-k-season-lineup-1"
LEARNING_WNBA_STAT_COLUMNS = {
    "Points": "PTS", "Rebounds": "REB", "Assists": "AST",
    "3-Pointers Made": "3PM", "Pts + Reb + Ast": "PRA",
    "Points + Rebounds": "PR", "Points + Assists": "PA",
    "Rebounds + Assists": "RA",
}


def is_reduced_payout_line(result: dict) -> bool:
    """Return True when a prop is not a standard full-payout line."""
    odds_type = str(result.get("odds_type", "standard") or "standard").lower()
    line_source = str(result.get("line_source", "line_score") or "line_score").lower()
    return bool(
        result.get("is_reduced")
        or result.get("is_goblin")
        or result.get("is_demon")
        or result.get("is_promo")
        or odds_type != "standard"
        or line_source in (
            "flash_sale_line_score", "discounted_line_score", "promo_line_score"
        )
    )


def _learning_wnba_team(value: str) -> str:
    cleaned = re.sub(r"[^A-Z]", "", str(value or "").upper())
    aliases = {
        "LA": "LAS", "LOSANGELESSPARKS": "LAS",
        "NY": "NYL", "NEWYORKLIBERTY": "NYL",
        "LV": "LVA", "LASVEGASACES": "LVA",
        "GS": "GSV", "GSW": "GSV", "GOLDENSTATEVALKYRIES": "GSV",
        "WAS": "WAS", "WSH": "WAS", "WSN": "WAS",
        "WASHINGTONMYSTICS": "WAS", "PHO": "PHX", "PHOENIXMERCURY": "PHX",
    }
    return aliases.get(cleaned, cleaned)


def _learning_json_safe(value):
    """Convert model evidence into compact JSON-safe values."""
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {str(k): _learning_json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_learning_json_safe(v) for v in value]
    if hasattr(value, "isoformat"):
        try:
            return value.isoformat()
        except Exception:
            pass
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    return str(value)


def _learning_prediction_key(scan_id: str, result: dict) -> str:
    import hashlib
    raw = "|".join([
        str(scan_id), str(result.get("sport", "")),
        normalize_name(result.get("player", "")),
        str(result.get("stat", "")), str(result.get("side", "")),
        str(result.get("line", "")), str(result.get("odds_type", "standard")),
        str(result.get("game_id") or result.get("game_pk") or result.get("start_time") or ""),
    ])
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def build_model_prediction_rows(results: list, scan_id: str,
                                session_id: str = "",
                                source: str = "edge_scanner") -> list:
    """Freeze model decisions into durable, model-versioned rows."""
    now_iso = datetime.utcnow().isoformat() + "Z"
    rows = []
    for result in results or []:
        try:
            probability = float(result.get("adj", 0) or 0)
            if not 0 <= probability <= 100:
                continue
            line = float(result.get("line"))
        except (TypeError, ValueError):
            continue

        game_date = str(result.get("game_date") or result.get("pp_game_date") or "")[:10]
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", game_date):
            game_date = None
        game_datetime = result.get("game_datetime") or result.get("start_time") or None
        projected_edge = _parse_numeric_value(result.get("projection_gap"), None)
        projected_value = _parse_numeric_value(result.get("projection"), None)
        if projected_value is None and projected_edge is not None:
            projected_value = (
                line + projected_edge
                if str(result.get("side", "Over")) == "Over"
                else line - projected_edge
            )

        risk_flags = []
        for key in (
            "trap_reasons", "validation_reasons", "model_flags",
            "quality_gate_reasons", "entry_decision_reasons",
        ):
            risk_flags.extend(str(item) for item in (result.get(key) or []) if item)
        for label_key in ("trap_label", "validation_label"):
            label = str(result.get(label_key, "") or "")
            if label and label not in ("Clean", "Validated", "Validated Strong"):
                risk_flags.append(label)
        risk_flags = list(dict.fromkeys(risk_flags))[:12]

        signal_keys = (
            "raw_adj", "calibrated_base", "reliability", "avg", "l3", "samples",
            "edge_raw", "projection_gap", "projection_prob", "pc", "pc_expected",
            "verdict_edge", "quality_gate_blocked",
            "pc_ceiling", "expected_bf", "pitcher_kbf", "matchup_kbf", "opp_k",
            "recent_opp_k", "handed_opp_k", "avg_ip", "pa_avg", "expected_fs",
            "defense_label", "defense_allowed", "defense_games", "role_label",
            "position_group", "role_matchup_label", "injury_status", "rest_days",
            "stale_days", "freshness_factor", "confidence_parts", "market_signal",
            "market_move", "market_open_move", "sportsbook_note", "rank_score",
            "rank_penalty", "rank_penalties", "line_verification_required",
            "entry_decision_reasons",
            "starter_id_verified", "context_validation",
            "current_starts", "prior_starts", "effective_sample",
            "hand_verified", "count_distribution", "arsenal_shadow",
            "talent_source", "season_starts", "season_bf", "l10_k9",
            "lineup_k", "lineup_profile_coverage", "lineup_confirmed",
            "lineup_projected", "lineup_source", "lineup_source_date",
            "lineup_deep_checked",
        )
        signal_snapshot = {
            key: _learning_json_safe(result.get(key))
            for key in signal_keys if result.get(key) is not None
        }
        event_id = str(
            result.get("game_pk") or result.get("event_id")
            or result.get("game_id") or ""
        ) or None
        try:
            event_key = pp_event_key(result)
        except Exception:
            event_key = ""
        player_id = result.get("pitcher_id") or result.get("player_id")
        team = result.get("pp_team") or result.get("pitcher_team") or result.get("player_team")
        reduced = is_reduced_payout_line(result)
        rows.append({
            "prediction_key": _learning_prediction_key(scan_id, result),
            "scan_id": str(scan_id),
            "session_id": str(session_id or ""),
            "source": str(source or "edge_scanner"),
            "model_version": str(result.get("model_version") or MODEL_LEARNING_VERSION),
            "shadow_version": result.get("shadow_version"),
            "sport": str(result.get("sport", "")).upper(),
            "player": str(result.get("player", "")),
            "player_id": str(player_id) if player_id else None,
            "team": str(team or ""),
            "opponent": str(result.get("opp", "") or ""),
            "market": str(result.get("stat", "")),
            "line": line,
            "side": str(result.get("side", "Over")),
            "odds_type": str(result.get("odds_type", "standard")),
            "is_reduced": reduced,
            "event_id": event_id,
            "event_key": event_key or None,
            "game_date": game_date,
            "game_datetime": game_datetime,
            "probability": round(probability, 2),
            "evidence_quality": _parse_numeric_value(result.get("confidence"), None),
            "consistency": _parse_numeric_value(result.get("cons"), None),
            "reliability": _parse_numeric_value(result.get("reliability"), None),
            "entry_score": _parse_numeric_value(result.get("entry_score"), None),
            "action": str(result.get("entry_action", "PASS")),
            "verdict": str(result.get("tier", "")),
            "historical_average": _parse_numeric_value(result.get("avg"), None),
            "projected_value": projected_value,
            "projected_edge": projected_edge,
            "sportsbook_grade": str(result.get("sportsbook_grade", "Unavailable")),
            "sportsbook_line": _parse_numeric_value(result.get("sportsbook_consensus_line"), None),
            "sportsbook_probability": _parse_numeric_value(result.get("sportsbook_side_probability"), None),
            "sportsbook_books": int(result.get("sportsbook_book_count", 0) or 0),
            "shadow_probability": _parse_numeric_value(result.get("shadow_probability"), None),
            "line_verified": bool(
                not result.get("line_verification_required")
                and result.get("slate_source", "live") == "live"
            ),
            "slate_source": str(result.get("slate_source", "live")),
            "risk_flags": risk_flags,
            "signal_snapshot": signal_snapshot,
            "status": "Pending",
            "result": "Pending",
            "created_at": now_iso,
            "updated_at": now_iso,
        })
    return rows


def save_model_prediction_batch(results: list, scan_id: str,
                                session_id: str = "",
                                source: str = "edge_scanner") -> int:
    """Persist model decisions to Supabase and retain a session fallback."""
    rows = build_model_prediction_rows(results, scan_id, session_id, source)
    if not rows:
        return 0

    local = st.session_state.setdefault("model_predictions", [])
    known = {row.get("prediction_key") for row in local}
    local.extend(row for row in rows if row.get("prediction_key") not in known)

    try:
        sb = get_supabase_client()
        if not sb:
            set_runtime_metric(
                "model_learning", "warn",
                f"Session ledger only · {len(rows)} predictions · Supabase unavailable",
            )
            return len(rows)
        import requests as _req
        headers = {
            **sb.hdrs,
            "Prefer": "resolution=ignore-duplicates,return=minimal",
        }
        saved = 0
        for offset in range(0, len(rows), 250):
            chunk = rows[offset:offset + 250]
            response = _req.post(
                f"{sb.url}/rest/v1/model_predictions?on_conflict=prediction_key",
                headers=headers, json=chunk, timeout=12,
            )
            if not response.ok:
                detail = f"HTTP {response.status_code}: {response.text[:180]}"
                record_debug_error("model_learning.save", detail)
                set_runtime_metric(
                    "model_learning", "warn",
                    "Ledger table unavailable · run supabase_model_predictions.sql",
                )
                return len(rows)
            saved += len(chunk)
        set_runtime_metric(
            "model_learning", "ok",
            f"Saved {saved} model decisions · model {MODEL_LEARNING_VERSION}",
            fetched_at=datetime.utcnow().isoformat() + "Z",
        )
        return saved
    except Exception as err:
        record_debug_error("model_learning.save", err)
        set_runtime_metric("model_learning", "warn", "Session ledger active · durable save failed")
        return len(rows)


def load_model_predictions(limit: int = 2500, force: bool = False) -> list:
    """Load the shared model ledger and merge any unsaved session snapshots."""
    if not force and st.session_state.get("model_predictions_loaded"):
        return st.session_state.get("model_predictions", []) or []
    server_rows = []
    try:
        sb = get_supabase_client()
        if sb:
            import requests as _req
            response = _req.get(
                f"{sb.url}/rest/v1/model_predictions"
                f"?select=*&order=created_at.desc&limit={max(1, min(int(limit), 5000))}",
                headers=sb.hdrs, timeout=12,
            )
            if response.ok and isinstance(response.json(), list):
                server_rows = response.json()
            elif response.status_code not in (404, 400):
                record_debug_error(
                    "model_learning.load",
                    f"HTTP {response.status_code}: {response.text[:180]}",
                )
    except Exception as err:
        record_debug_error("model_learning.load", err)

    merged = {}
    for row in (st.session_state.get("model_predictions", []) or []) + server_rows:
        key = row.get("prediction_key")
        if key and key not in merged:
            merged[key] = row
        elif key:
            current = merged[key]
            current_updated = str(current.get("updated_at", ""))
            row_updated = str(row.get("updated_at", ""))
            merged[key] = (
                {**current, **row}
                if row_updated >= current_updated else
                {**row, **current}
            )
    rows = sorted(
        merged.values(), key=lambda row: str(row.get("created_at", "")), reverse=True
    )
    st.session_state.model_predictions = rows
    st.session_state.model_predictions_loaded = True
    return rows


def update_model_prediction_row(row: dict, updates: dict) -> bool:
    """Update one local prediction and its durable row when configured."""
    row.update(updates)
    row["updated_at"] = datetime.utcnow().isoformat() + "Z"
    try:
        sb = get_supabase_client()
        if not sb:
            return False
        import requests as _req
        from urllib.parse import quote as _quote
        if row.get("id"):
            selector = f"id=eq.{_quote(str(row['id']), safe='')}"
        else:
            selector = f"prediction_key=eq.{_quote(str(row.get('prediction_key', '')), safe='')}"
        payload = {**updates, "updated_at": row["updated_at"]}
        response = _req.patch(
            f"{sb.url}/rest/v1/model_predictions?{selector}",
            headers={**sb.hdrs, "Prefer": "return=minimal"},
            json=payload, timeout=8,
        )
        return response.ok
    except Exception as err:
        record_debug_error("model_learning.update", err)
        return False


@st.cache_data(ttl=21600, show_spinner=False)
def _learning_find_mlb_player_id(player_name: str) -> Optional[str]:
    try:
        response = requests.get(
            "https://statsapi.mlb.com/api/v1/people/search",
            params={"names": player_name, "sportIds": 1}, timeout=10,
        )
        if not response.ok:
            return None
        candidates = response.json().get("people", []) or []
        target = normalize_name(player_name)
        exact = next(
            (p for p in candidates if normalize_name(p.get("fullName", "")) == target),
            None,
        )
        best = exact or (candidates[0] if len(candidates) == 1 else None)
        return str(best.get("id")) if best and best.get("id") else None
    except Exception:
        return None


def _learning_hitter_fantasy_score(stats: dict) -> float:
    hits = float(stats.get("hits", 0) or 0)
    doubles = float(stats.get("doubles", 0) or 0)
    triples = float(stats.get("triples", 0) or 0)
    homers = float(stats.get("homeRuns", 0) or 0)
    singles = max(0.0, hits - doubles - triples - homers)
    return (
        singles * 3 + doubles * 5 + triples * 8 + homers * 10
        + float(stats.get("runs", 0) or 0) * 2
        + float(stats.get("rbi", stats.get("runsBattedIn", 0)) or 0) * 2
        + float(stats.get("baseOnBalls", 0) or 0) * 2
        + float(stats.get("hitByPitch", 0) or 0) * 2
        + float(stats.get("stolenBases", 0) or 0) * 5
    )


@st.cache_data(ttl=900, show_spinner=False)
def _learning_mlb_event_final(event_id: str) -> bool:
    if not event_id:
        return False
    try:
        response = requests.get(
            f"https://statsapi.mlb.com/api/v1.1/game/{event_id}/feed/live",
            timeout=10,
        )
        if not response.ok:
            return False
        status = (response.json().get("gameData", {}) or {}).get("status", {}) or {}
        state = " ".join(str(status.get(key, "")) for key in (
            "abstractGameState", "detailedState", "statusCode",
        )).lower()
        return "final" in state or "game over" in state or "completed" in state
    except Exception:
        return False


@st.cache_data(ttl=900, show_spinner=False)
def _learning_wnba_event_final(event_id: str) -> bool:
    if not event_id:
        return False
    try:
        response = requests.get(
            "https://site.api.espn.com/apis/site/v2/sports/basketball/wnba/summary",
            params={"event": event_id}, headers=ESPN_HEADERS, timeout=10,
        )
        if not response.ok:
            return False
        data = response.json()
        competition = ((data.get("header", {}) or {}).get("competitions") or [{}])[0]
        status_type = ((competition.get("status", {}) or {}).get("type", {}) or {})
        status_name = str(status_type.get("name", "")).lower()
        return bool(status_type.get("completed")) or "final" in status_name
    except Exception:
        return False


@st.cache_data(ttl=1800, show_spinner=False)
def _learning_mlb_actual(player_id: str, player_name: str, market: str,
                         game_date: str, event_id: str = "") -> Optional[float]:
    """Return an MLB result only when the expected game can be matched safely."""
    pid = str(player_id or "") or str(_learning_find_mlb_player_id(player_name) or "")
    if not pid or not game_date or not event_id:
        return None
    if not _learning_mlb_event_final(str(event_id)):
        return None
    group = "hitting" if market == "Hitter Fantasy Score" else "pitching"
    try:
        season = int(str(game_date)[:4])
        response = requests.get(
            f"https://statsapi.mlb.com/api/v1/people/{pid}/stats",
            params={"stats": "gameLog", "group": group, "season": season, "gameType": "R"},
            timeout=12,
        )
        if not response.ok:
            return None
        matches = []
        for block in response.json().get("stats", []) or []:
            for split in block.get("splits", []) or []:
                if str(split.get("date", ""))[:10] != str(game_date)[:10]:
                    continue
                game = split.get("game", {}) or {}
                game_pk = str(game.get("gamePk") or split.get("gamePk") or "")
                matches.append((game_pk, split.get("stat", {}) or {}))
        if event_id:
            exact = [stats for game_pk, stats in matches if game_pk == str(event_id)]
            if len(exact) != 1:
                return None
            matches = [(str(event_id), exact[0])]
        if len(matches) != 1:
            return None
        stats = matches[0][1]
        if market == "Hitter Fantasy Score":
            return float(_learning_hitter_fantasy_score(stats))
        return float(stats.get("strikeOuts", 0) or 0)
    except Exception as err:
        record_debug_error("model_learning.mlb_settle", err)
        return None


@st.cache_data(ttl=1800, show_spinner=False)
def _learning_wnba_actual(player_id: str, market: str, game_date: str,
                          event_id: str = "", opponent: str = "") -> Optional[float]:
    """Return a WNBA box-score value for the exact scheduled game."""
    column = LEARNING_WNBA_STAT_COLUMNS.get(market)
    if not player_id or not column or not game_date or not event_id:
        return None
    if not _learning_wnba_event_final(str(event_id)):
        return None
    try:
        response = requests.get(
            "https://site.web.api.espn.com/apis/common/v3/sports/basketball/wnba/"
            f"athletes/{player_id}/gamelog",
            params={"season": int(str(game_date)[:4])},
            headers=ESPN_HEADERS, timeout=12,
        )
        if not response.ok:
            return None
        data = response.json()
        names = data.get("names", []) or []
        positions = {str(name): i for i, name in enumerate(names)}
        event_meta = data.get("events", {}) or {}
        matches = []

        def value(stats, name, default=0.0):
            try:
                return float(str(stats[positions[name]]).split("-")[0])
            except Exception:
                return default

        for season_type in data.get("seasonTypes", []) or []:
            for category in season_type.get("categories", []) or []:
                for event in category.get("events", []) or []:
                    eid = str(event.get("eventId", "") or "")
                    meta = event_meta.get(eid, {}) if isinstance(event_meta, dict) else {}
                    game_stamp = pd.to_datetime(
                        meta.get("gameDate", ""), utc=True, errors="coerce"
                    )
                    if pd.isna(game_stamp):
                        continue
                    try:
                        game_day = game_stamp.tz_convert(
                            "America/New_York"
                        ).date().isoformat()
                    except Exception:
                        game_day = game_stamp.date().isoformat()
                    if game_day != str(game_date)[:10]:
                        continue
                    opp = str((meta.get("opponent") or {}).get("abbreviation", "")).upper()
                    if opponent and opp and _learning_wnba_team(opp) != _learning_wnba_team(opponent):
                        continue
                    stats = event.get("stats", []) or []
                    pts = value(stats, "points")
                    reb = value(stats, "totalRebounds")
                    ast = value(stats, "assists")
                    values = {
                        "PTS": pts, "REB": reb, "AST": ast,
                        "3PM": value(stats, "threePointFieldGoalsMade-threePointFieldGoalsAttempted"),
                        "PRA": pts + reb + ast, "PR": pts + reb,
                        "PA": pts + ast, "RA": reb + ast,
                    }
                    matches.append((eid, values[column]))
        if event_id:
            exact = [actual for eid, actual in matches if eid == str(event_id)]
            if len(exact) == 1:
                return float(exact[0])
            return None
        return float(matches[0][1]) if len(matches) == 1 else None
    except Exception as err:
        record_debug_error("model_learning.wnba_settle", err)
        return None


def _learning_pick_result(actual: float, line: float, side: str) -> str:
    if abs(float(actual) - float(line)) < 1e-9:
        return "Push"
    if str(side).lower() == "under":
        return "Hit" if float(actual) < float(line) else "Miss"
    return "Hit" if float(actual) > float(line) else "Miss"


def _learning_closing_line(row: dict) -> Tuple[Optional[float], Optional[str], Optional[str]]:
    """Use the last matching pregame PrizePicks snapshot as the closing line."""
    try:
        rows = get_pp_line_history_from_supabase(
            row.get("player", ""), row.get("market", ""), limit=100,
            sport=row.get("sport", "MLB"),
        )
        if not rows:
            return None, None, None
        event_key = str(row.get("event_key") or "")
        if not event_key:
            return None, None, None
        odds_type = str(row.get("odds_type") or "standard").lower()
        game_time = pd.to_datetime(row.get("game_datetime"), utc=True, errors="coerce")
        eligible = []
        for item in rows:
            item_odds = str(item.get("odds_type") or "standard").lower()
            if item_odds != odds_type:
                continue
            source = str(item.get("source") or "")
            if not source.endswith(f"|{event_key}"):
                continue
            stamp = pd.to_datetime(item.get("snapshot_at"), utc=True, errors="coerce")
            if pd.isna(stamp) or (pd.notna(game_time) and stamp > game_time):
                continue
            eligible.append((stamp, item))
        if not eligible:
            return None, None, None
        _, latest = max(eligible, key=lambda pair: pair[0])
        return (
            float(latest.get("line")),
            str(latest.get("source") or "prizepicks"),
            str(latest.get("snapshot_at") or ""),
        )
    except Exception:
        return None, None, None


def settle_model_predictions(predictions: list, max_events: int = 40) -> dict:
    """Settle pending prediction groups against their exact scheduled game."""
    try:
        import pytz
        today = datetime.now(pytz.timezone("America/New_York")).date()
    except Exception:
        today = datetime.now().date()
    groups = {}
    for row in predictions or []:
        if str(row.get("status", "Pending")) != "Pending":
            continue
        game_stamp = pd.to_datetime(row.get("game_date"), errors="coerce")
        if pd.isna(game_stamp):
            continue
        game_day = game_stamp.date()
        if game_day > today or (today - game_day).days > 45:
            continue
        key = (
            row.get("sport"), row.get("player_id"), row.get("player"),
            row.get("game_date"), row.get("event_id"), row.get("market"),
            row.get("opponent"),
        )
        groups.setdefault(key, []).append(row)

    updated = 0
    unresolved = 0
    pushes = 0
    # Prefer completed current-model slates, but rotate unresolved groups to the
    # back of their priority tier so a permanently unmatchable event cannot
    # occupy every refresh batch.
    attempts = st.session_state.setdefault("model_learning_settle_attempts", {})

    def _settlement_attempt_key(group_key):
        return "|".join(str(part or "") for part in group_key)

    def _settlement_sort_key(item):
        group_key, rows = item
        sample = rows[0]
        stamp = pd.to_datetime(item[1][0].get("game_date"), errors="coerce")
        game_day = stamp.date() if pd.notna(stamp) else today
        return (
            0 if game_day < today else 1,
            0 if str(sample.get("model_version", "")) == MODEL_LEARNING_VERSION else 1,
            float(attempts.get(_settlement_attempt_key(group_key), 0.0) or 0.0),
            game_day,
            str(group_key),
        )

    ordered_groups = sorted(groups.items(), key=_settlement_sort_key)
    checked_current = 0
    updated_current = 0
    for index, (group_key, rows) in enumerate(ordered_groups):
        if index >= max_events:
            break
        sample = rows[0]
        attempts[_settlement_attempt_key(group_key)] = time.time()
        is_current_model = (
            str(sample.get("model_version", "")) == MODEL_LEARNING_VERSION
        )
        if is_current_model:
            checked_current += 1
        sport = str(sample.get("sport", "")).upper()
        if sport == "MLB":
            actual = _learning_mlb_actual(
                sample.get("player_id", ""), sample.get("player", ""),
                sample.get("market", ""), sample.get("game_date", ""),
                sample.get("event_id", ""),
            )
        elif sport == "WNBA":
            actual = _learning_wnba_actual(
                sample.get("player_id", ""), sample.get("market", ""),
                sample.get("game_date", ""), sample.get("event_id", ""),
                sample.get("opponent", ""),
            )
        else:
            actual = None
        if actual is None:
            unresolved += len(rows)
            continue

        for row in rows:
            result = _learning_pick_result(actual, float(row.get("line", 0)), row.get("side", "Over"))
            probability = float(row.get("probability", 50) or 50) / 100.0
            outcome = 1.0 if result == "Hit" else 0.0 if result == "Miss" else None
            closing_line, closing_source, closing_at = _learning_closing_line(row)
            updates = {
                "status": "Settled",
                "result": result,
                "actual_value": round(float(actual), 3),
                "brier_score": round((probability - outcome) ** 2, 6) if outcome is not None else None,
                "settled_at": datetime.utcnow().isoformat() + "Z",
                "closing_line": closing_line,
                "closing_line_source": closing_source,
                "closing_line_captured_at": closing_at,
            }
            update_model_prediction_row(row, updates)
            updated += 1
            if is_current_model:
                updated_current += 1
            if result == "Push":
                pushes += 1
    active_attempt_keys = {
        _settlement_attempt_key(group_key) for group_key in groups
    }
    st.session_state.model_learning_settle_attempts = {
        key: value for key, value in attempts.items() if key in active_attempt_keys
    }
    set_runtime_metric(
        "model_learning", "ok" if updated or not groups else "info",
        f"Settlement checked {min(len(ordered_groups), max_events)} decisions · "
        f"{updated} rows settled · {unresolved} unresolved · "
        f"current model {updated_current}/{checked_current} settled",
        fetched_at=datetime.utcnow().isoformat() + "Z",
    )
    return {
        "events_checked": min(len(ordered_groups), max_events),
        "updated": updated, "unresolved": unresolved, "pushes": pushes,
        "current_checked": checked_current,
        "current_updated": updated_current,
    }


def _learning_decision_key(item: dict) -> tuple:
    """Identity for one independently gradable prop decision across rescans."""
    item = item or {}
    event_identity = str(
        item.get("event_id") or item.get("event_key") or ""
    ).strip()
    if not event_identity:
        game_date = str(item.get("game_date") or "")[:10]
        team = str(item.get("team") or "").strip().upper()
        opponent = str(item.get("opponent") or "").strip().upper()
        matchup = "-".join(sorted(value for value in (team, opponent) if value))
        event_identity = f"{game_date}|{matchup}" if game_date or matchup else ""
    if not event_identity:
        # Rows without any game identity cannot be safely collapsed.
        event_identity = str(item.get("prediction_key") or item.get("scan_id") or id(item))

    line = _parse_numeric_value(item.get("line"), None)
    line_key = f"{line:.3f}" if line is not None else str(item.get("line", ""))
    return (
        str(item.get("model_version", "Unknown")),
        str(item.get("sport", "")).upper(),
        event_identity,
        str(item.get("player_id") or normalize_name(item.get("player", ""))),
        str(item.get("market", "")),
        line_key,
        str(item.get("side", "Over")).lower(),
        str(item.get("odds_type", "standard")).lower(),
    )


def _learning_unique_prediction_rows(predictions: list) -> list:
    """Keep the final valid pregame snapshot for each unique prop decision."""
    grouped = {}
    for item in predictions or []:
        created = pd.to_datetime(item.get("created_at"), utc=True, errors="coerce")
        game_time_raw = str(item.get("game_datetime") or "").strip()
        game_time = pd.to_datetime(game_time_raw, utc=True, errors="coerce")
        has_explicit_time = bool(
            re.search(r"T\d{1,2}:\d{2}|\s\d{1,2}:\d{2}", game_time_raw)
        )
        if (
            has_explicit_time and pd.notna(created)
            and pd.notna(game_time) and created > game_time
        ):
            # A post-start refresh is useful operational history, but it is not
            # an honest pregame forecast and must not enter calibration.
            continue
        grouped.setdefault(_learning_decision_key(item), []).append(item)

    unique = []
    outcome_fields = (
        "status", "result", "actual_value", "settled_at", "brier_score",
        "closing_line", "closing_line_source", "closing_line_captured_at",
    )
    for rows in grouped.values():
        def created_rank(row: dict) -> int:
            stamp = pd.to_datetime(row.get("created_at"), utc=True, errors="coerce")
            return int(stamp.value) if pd.notna(stamp) else 0

        selected = dict(max(rows, key=created_rank))
        settled_rows = [
            row for row in rows
            if str(row.get("result", row.get("status", ""))) in ("Hit", "Miss", "Push")
        ]
        if settled_rows:
            outcome_source = max(settled_rows, key=created_rank)
            for field in outcome_fields:
                if outcome_source.get(field) is not None:
                    selected[field] = outcome_source.get(field)
        unique.append(selected)

    return sorted(
        unique,
        key=lambda row: str(row.get("created_at", "")),
        reverse=True,
    )


def _learning_evaluation_rows(predictions: list) -> list:
    """Normalize settled ledger rows for calibration and closing-line analysis."""
    rows = []
    for item in predictions or []:
        result = str(item.get("result", item.get("status", "Pending")))
        if result not in ("Hit", "Miss"):
            continue
        probability = _parse_numeric_value(item.get("probability"), None)
        if probability is None or not 0 <= probability <= 100:
            continue
        probability /= 100.0
        line = _parse_numeric_value(item.get("line"), None)
        closing = _parse_numeric_value(item.get("closing_line"), None)
        side = str(item.get("side", "Over"))
        clv = None
        if line is not None and closing is not None:
            clv = (closing - line) * (-1.0 if side.lower() == "under" else 1.0)
        actual = 1.0 if result == "Hit" else 0.0
        signal_snapshot = item.get("signal_snapshot", {}) or {}
        risk_flags = item.get("risk_flags", []) or []
        if not isinstance(signal_snapshot, dict):
            signal_snapshot = {}
        if not isinstance(risk_flags, list):
            risk_flags = [str(risk_flags)]
        decision_reasons = signal_snapshot.get("entry_decision_reasons", []) or []
        if not isinstance(decision_reasons, list):
            decision_reasons = [str(decision_reasons)]
        source = str(item.get("source", "edge_scanner") or "edge_scanner")
        odds_type = str(item.get("odds_type", "standard") or "standard").lower()
        is_reduced = bool(item.get("is_reduced")) or odds_type != "standard"
        line_verified = bool(item.get("line_verified"))
        line_type = (
            "Manual / unverified"
            if source == "individual_analyzer" and not line_verified
            else "Reduced payout" if is_reduced else "Standard payout"
        )
        rows.append({
            "player": str(item.get("player", "")),
            "sport": str(item.get("sport", "Unknown") or "Unknown").upper(),
            "market": str(item.get("market", "Unknown") or "Unknown"),
            "side": side,
            "action": str(item.get("action", "PASS") or "PASS").upper(),
            "model_version": str(item.get("model_version", "Unknown") or "Unknown"),
            "source": source,
            "sportsbook_grade": str(item.get("sportsbook_grade", "Unavailable") or "Unavailable"),
            "odds_type": odds_type,
            "line_type": line_type,
            "is_reduced": is_reduced,
            "risk_flags": [str(flag) for flag in risk_flags if flag],
            "rank_penalties": [
                str(flag) for flag in (signal_snapshot.get("rank_penalties", []) or [])
                if flag
            ],
            "decision_reasons": [str(reason) for reason in decision_reasons if reason],
            "prob": probability,
            "actual": actual,
            "result": result,
            "brier": (probability - actual) ** 2,
            "evidence": _parse_numeric_value(item.get("evidence_quality"), None),
            "entry_score": _parse_numeric_value(item.get("entry_score"), None),
            "shadow_probability": _parse_numeric_value(
                item.get("shadow_probability"), None
            ),
            "line": line,
            "closing_line": closing,
            "clv": clv,
            "game_date": str(item.get("game_date", "") or ""),
            "created_at": str(item.get("created_at", "") or ""),
        })
    return rows


def _learning_wilson_interval(hits: float, n: int,
                              z: float = 1.96) -> Tuple[float, float]:
    """95% Wilson interval for a binary hit rate without extra dependencies."""
    if n <= 0:
        return 0.0, 1.0
    proportion = max(0.0, min(1.0, float(hits) / n))
    denominator = 1.0 + ((z ** 2) / n)
    center = (proportion + ((z ** 2) / (2.0 * n))) / denominator
    margin = (
        z * (
            ((proportion * (1.0 - proportion) / n) + ((z ** 2) / (4.0 * n ** 2)))
            ** 0.5
        ) / denominator
    )
    return max(0.0, center - margin), min(1.0, center + margin)


def _learning_group_summary(rows: list, label: str) -> Optional[dict]:
    if not rows:
        return None
    n = len(rows)
    predicted = sum(row["prob"] for row in rows) / n
    hits = sum(row["actual"] for row in rows)
    actual = hits / n
    interval_low, interval_high = _learning_wilson_interval(hits, n)
    return {
        "Segment": label,
        "N": n,
        "Sample": "Usable" if n >= 40 else "Provisional" if n >= 15 else "Thin",
        "Predicted": f"{predicted:.1%}",
        "Actual": f"{actual:.1%}",
        "Actual 95% range": f"{interval_low:.1%}–{interval_high:.1%}",
        "Gap": f"{actual - predicted:+.1%}",
        "Brier": f"{sum(row['brier'] for row in rows) / n:.3f}",
    }


LEARNING_SHADOW_CALIBRATOR_VERSION = "rolling-beta-v1"


def _learning_row_day(row: dict) -> str:
    """Stable day key used to prevent same-day outcomes leaking into calibration."""
    for value in (row.get("game_date"), row.get("created_at")):
        stamp = pd.to_datetime(value, utc=True, errors="coerce")
        if pd.notna(stamp):
            return stamp.strftime("%Y-%m-%d")
    return "9999-12-31"


def _learning_rolling_shadow_calibration(rows: list) -> list:
    """Out-of-sample beta-bin calibration using only earlier game days."""
    chronological = sorted(
        (dict(row) for row in (rows or [])),
        key=lambda row: (_learning_row_day(row), row.get("created_at", "")),
    )
    by_day = {}
    for row in chronological:
        by_day.setdefault(_learning_row_day(row), []).append(row)

    history = []
    evaluated = []
    for day in sorted(by_day):
        day_rows = by_day[day]
        for row in day_rows:
            if len(history) < 40:
                continue

            same_sport_market = [
                prior for prior in history
                if prior["sport"] == row["sport"]
                and prior["market"] == row["market"]
                and prior["line_type"] == row["line_type"]
            ]
            same_sport = [
                prior for prior in history
                if prior["sport"] == row["sport"]
                and prior["line_type"] == row["line_type"]
            ]
            same_line_type = [
                prior for prior in history
                if prior["line_type"] == row["line_type"]
            ]
            if len(same_sport_market) >= 25:
                cohort = same_sport_market
                scope = f"{row['sport']} · {row['market']} · {row['line_type']}"
            elif len(same_sport) >= 35:
                cohort = same_sport
                scope = f"{row['sport']} · {row['line_type']}"
            elif len(same_line_type) >= 35:
                cohort = same_line_type
                scope = row["line_type"]
            else:
                # Standard and reduced-payout lines have different selection
                # profiles and must never calibrate one another.
                continue

            neighborhood = [
                prior for prior in cohort
                if abs(float(prior["prob"]) - float(row["prob"])) <= 0.10
            ]
            training = neighborhood if len(neighborhood) >= 15 else cohort
            if len(training) < 30:
                continue

            prior_strength = 20.0
            hits = sum(float(prior["actual"]) for prior in training)
            probability = float(row["prob"])
            calibrated = (hits + (prior_strength * probability)) / (
                len(training) + prior_strength
            )
            calibrated = max(
                0.35,
                min(0.95, max(probability - 0.12, min(probability + 0.12, calibrated))),
            )
            evaluated.append({
                **row,
                "shadow_prob": calibrated,
                "shadow_brier": (calibrated - float(row["actual"])) ** 2,
                "shadow_train_n": len(training),
                "shadow_scope": scope,
            })
        # Outcomes from one date become eligible only after every forecast on
        # that date has been scored, preventing same-day lookahead.
        history.extend(day_rows)
    return evaluated


def _learning_normalize_gate_reason(reason: str) -> str:
    text = str(reason or "").strip().lower()
    if not text:
        return ""
    if "reduced payout" in text or "goblin" in text or "promo" in text:
        return "Reduced-payout penalty"
    if "line verification" in text or "verify line" in text:
        return "Line verification gate"
    if "evidence quality" in text or "confidence" in text:
        return "Evidence-quality floor"
    if "model verdict" in text:
        return "Underlying model verdict Pass"
    if "hard risk" in text or "trap" in text or "do not force" in text:
        return "Trap / hard-risk gate"
    if "small k cushion" in text or "thin k cushion" in text:
        return "Strikeout cushion gate"
    if "starter" in text:
        return "Starter-verification gate"
    if "short leash" in text or "pitch count" in text or "workload" in text:
        return "Role / workload gate"
    if "independent market" in text or "sportsbook" in text:
        return "Independent-market gate"
    if "validation" in text or "context" in text or "roster" in text:
        return "Context-validation gate"
    if "model chance" in text or "probability" in text:
        return "Model-chance floor"
    if "entry score" in text or "ranking penalty" in text:
        return "Entry-score / ranking gate"
    return "Other recorded risk"


def _learning_pass_gate_reasons(row: dict) -> list:
    """Recover exact new gate reasons and sensible categories for legacy rows."""
    reasons = []
    for reason in row.get("decision_reasons", []) or []:
        normalized = _learning_normalize_gate_reason(reason)
        if normalized:
            reasons.append(normalized)
    for reason in row.get("rank_penalties", []) or []:
        normalized = _learning_normalize_gate_reason(f"Ranking penalty: {reason}")
        if normalized:
            reasons.append(normalized)
    for reason in row.get("risk_flags", []) or []:
        normalized = _learning_normalize_gate_reason(reason)
        if normalized and normalized != "Other recorded risk":
            reasons.append(normalized)

    evidence = row.get("evidence")
    entry_score = row.get("entry_score")
    if evidence is not None and float(evidence) < 55:
        reasons.append("Evidence-quality floor")
    if float(row.get("prob", 0) or 0) < 0.55:
        reasons.append("Model-chance floor")
    if not reasons and entry_score is not None and float(entry_score) < 65:
        reasons.append("Entry-score / ranking gate")
    if not reasons:
        reasons.append("Unclassified legacy gate")
    return list(dict.fromkeys(reasons))


def _learning_pass_reason_rows(rows: list) -> list:
    pass_rows = [row for row in (rows or []) if row.get("action") == "PASS"]
    grouped = {}
    for row in pass_rows:
        for reason in _learning_pass_gate_reasons(row):
            grouped.setdefault(reason, []).append(row)
    summaries = []
    for reason, reason_rows in grouped.items():
        summary = _learning_group_summary(reason_rows, reason)
        if summary:
            summary["PASS share"] = f"{len(reason_rows) / len(pass_rows):.0%}" if pass_rows else "—"
            summaries.append(summary)
    return sorted(summaries, key=lambda row: (-int(row["N"]), row["Segment"]))


def _learning_pair_rows(rows: list, first_field: str, first_label: str,
                        second_field: str, second_label: str) -> list:
    """Summarize two dimensions together so mixed cohorts cannot hide drift."""
    grouped = {}
    for row in rows or []:
        first = str(row.get(first_field, "Unknown") or "Unknown")
        second = str(row.get(second_field, "Unknown") or "Unknown")
        grouped.setdefault((first, second), []).append(row)
    summaries = []
    for (first, second), group_rows in grouped.items():
        summary = _learning_group_summary(
            group_rows,
            f"{first_label}: {first} × {second_label}: {second}",
        )
        if summary:
            summaries.append(summary)
    return sorted(summaries, key=lambda row: (-int(row["N"]), row["Segment"]))


def _learning_line_type_gate_rows(rows: list) -> list:
    """Split overlapping PASS-gate outcomes by payout type."""
    pass_rows = [row for row in (rows or []) if row.get("action") == "PASS"]
    line_type_totals = {}
    grouped = {}
    for row in pass_rows:
        line_type = str(row.get("line_type", "Unknown") or "Unknown")
        line_type_totals[line_type] = line_type_totals.get(line_type, 0) + 1
        for reason in _learning_pass_gate_reasons(row):
            grouped.setdefault((line_type, reason), []).append(row)

    summaries = []
    for (line_type, reason), group_rows in grouped.items():
        summary = _learning_group_summary(
            group_rows,
            f"{line_type} × {reason}",
        )
        if summary:
            denominator = line_type_totals.get(line_type, 0)
            summary["PASS share"] = (
                f"{len(group_rows) / denominator:.0%}" if denominator else "—"
            )
            summaries.append(summary)
    return sorted(summaries, key=lambda row: (-int(row["N"]), row["Segment"]))


def render_model_learning_dashboard(predictions: list) -> None:
    """Show selection coverage, calibration, CLV, and segment performance."""
    predictions = [
        row for row in (predictions or [])
        if str(row.get("sport", "")).upper() != "WNBA"
    ]
    st.markdown(
        "<div class='section-header'>Model Learning Loop</div>",
        unsafe_allow_html=True,
    )
    if not predictions:
        st.markdown(
            "<div class='pick-list-empty'><strong style='color:var(--text);'>"
            "No scanner decisions recorded yet</strong><br>Run an Edge scan to begin "
            "capturing every PLAY, WATCH, and PASS. Durable history requires the "
            "model_predictions Supabase table.</div>",
            unsafe_allow_html=True,
        )
        return

    versions = sorted({str(row.get("model_version", "Unknown")) for row in predictions}, reverse=True)
    sports = sorted({str(row.get("sport", "Unknown")).upper() for row in predictions})
    sources = sorted({str(row.get("source", "edge_scanner") or "edge_scanner") for row in predictions})
    source_labels = {
        "edge_scanner": "Edge scanner",
        "individual_analyzer": "Individual analyzer",
    }
    source_options = ["All sources"] + sources
    default_source_index = (
        source_options.index("edge_scanner")
        if "edge_scanner" in source_options else 0
    )
    filter_a, filter_b, filter_c = st.columns(3)
    with filter_a:
        sport_filter = st.selectbox(
            "Learning sport", ["All sports"] + sports, key="learning_sport_filter"
        )
    with filter_b:
        version_filter = st.selectbox(
            "Model version", versions, key="learning_model_version_filter"
        )
    with filter_c:
        source_filter = st.selectbox(
            "Decision source", source_options,
            index=default_source_index,
            format_func=lambda value: source_labels.get(value, value.replace("_", " ").title()),
            key="learning_source_filter",
        )

    filtered = [
        row for row in predictions
        if str(row.get("model_version", "Unknown")) == version_filter
        and (
            source_filter == "All sources"
            or str(row.get("source", "edge_scanner") or "edge_scanner") == source_filter
        )
        and (
            sport_filter == "All sports"
            or str(row.get("sport", "Unknown")).upper() == sport_filter
        )
    ]
    unique_filtered = _learning_unique_prediction_rows(filtered)
    snapshot_graded = _learning_evaluation_rows(filtered)
    graded = _learning_evaluation_rows(unique_filtered)
    repeated_snapshots = max(0, len(filtered) - len(unique_filtered))
    pending = sum(
        1 for row in unique_filtered
        if str(row.get("status", "Pending")) == "Pending"
    )
    pushes = sum(1 for row in unique_filtered if str(row.get("result", "")) == "Push")
    action_counts = {
        action: sum(
            1 for row in unique_filtered
            if str(row.get("action", "PASS")).upper() == action
        )
        for action in ("PLAY", "WATCH", "PASS")
    }

    if graded:
        predicted = sum(row["prob"] for row in graded) / len(graded)
        actual = sum(row["actual"] for row in graded) / len(graded)
        gap = actual - predicted
        brier = sum(row["brier"] for row in graded) / len(graded)
        baseline_brier = actual * (1.0 - actual)
        brier_skill = (
            1.0 - (brier / baseline_brier)
            if baseline_brier > 0 else None
        )
    else:
        predicted = actual = gap = brier = baseline_brier = brier_skill = None

    rolling_shadow = _learning_rolling_shadow_calibration(graded)
    if rolling_shadow:
        shadow_active_brier = sum(row["brier"] for row in rolling_shadow) / len(rolling_shadow)
        shadow_brier = sum(row["shadow_brier"] for row in rolling_shadow) / len(rolling_shadow)
        shadow_delta = shadow_active_brier - shadow_brier
    else:
        shadow_active_brier = shadow_brier = shadow_delta = None

    st.markdown(
        f"<div class='workspace-summary-grid'>"
        f"<div class='workspace-summary-item'><span>Captured snapshots</span><strong>{len(filtered)}</strong></div>"
        f"<div class='workspace-summary-item'><span>Unique decisions</span><strong>{len(unique_filtered)}</strong></div>"
        f"<div class='workspace-summary-item'><span>Settled unique</span><strong>{len(graded)}</strong></div>"
        f"<div class='workspace-summary-item'><span>Actual hit</span><strong>{f'{actual:.1%}' if actual is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Model average</span><strong>{f'{predicted:.1%}' if predicted is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Calibration gap</span><strong>{f'{gap:+.1%}' if gap is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Brier score</span><strong>{f'{brier:.3f}' if brier is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Brier skill</span><strong>{f'{brier_skill:+.1%}' if brier_skill is not None else '—'}</strong></div>"
        f"</div>",
        unsafe_allow_html=True,
    )
    st.caption(
        f"Unique-decision coverage: {action_counts['PLAY']} PLAY · {action_counts['WATCH']} WATCH · "
        f"{action_counts['PASS']} PASS · {pending} pending · {pushes} push. "
        f"{repeated_snapshots} repeated scan snapshots are retained for history but excluded from headline calibration; "
        f"{len(snapshot_graded)} settled snapshots collapse to {len(graded)} unique settled decisions. "
        "The latest valid pregame snapshot represents each unique prop."
    )

    if not graded:
        st.info(
            f"Captured {len(unique_filtered)} unique {version_filter} decisions, with "
            f"{pending} still pending and 0 settled. After the games are final, tap "
            "Refresh model outcomes above. Each refresh checks up to 40 event groups; "
            "repeat it while the pending count is falling, then use Reload ledger if needed."
        )
        return

    if len(graded) < 40:
        st.warning(
            f"Only {len(graded)} unique graded decisions are available. Treat the headline as provisional until at least 40 are settled, and do not retune an individual segment before it has 30."
        )
    elif len(graded) < 100:
        st.info(
            f"{len(graded)} unique decisions are enough for monitoring, but not a durable probability retune. "
            "Wait for at least 100 unique outcomes overall and 30 within the affected segment before changing model weights."
        )
    if baseline_brier is not None:
        st.caption(
            f"Brier benchmark: {baseline_brier:.3f} from always predicting this sample's "
            f"{actual:.1%} base hit rate · model skill {brier_skill:+.1%}. Higher skill is better; "
            "a negative value means the probability model did not beat the constant-rate baseline."
        )

    st.markdown("**Out-of-Sample Rolling Calibrator**")
    st.markdown(
        f"<div class='workspace-summary-grid'>"
        f"<div class='workspace-summary-item'><span>Shadow coverage</span><strong>{len(rolling_shadow)}</strong></div>"
        f"<div class='workspace-summary-item'><span>Active Brier</span><strong>{f'{shadow_active_brier:.3f}' if shadow_active_brier is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Shadow Brier</span><strong>{f'{shadow_brier:.3f}' if shadow_brier is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Improvement</span><strong style='color:{'var(--green)' if shadow_delta is not None and shadow_delta > 0 else 'var(--red)'};'>{f'{shadow_delta:+.3f}' if shadow_delta is not None else '—'}</strong></div>"
        f"</div>",
        unsafe_allow_html=True,
    )
    if rolling_shadow:
        st.caption(
            f"{LEARNING_SHADOW_CALIBRATOR_VERSION} grades each decision using only outcomes from earlier game days. "
            f"Positive improvement means the shadow probability beat the live probability on the same {len(rolling_shadow)} outcomes. "
            "It remains report-only until it has at least 100 out-of-sample decisions and a lower Brier score."
        )
    else:
        st.caption(
            "The shadow calibrator begins after 40 earlier settled decisions are available. "
            "It never changes live scanner probabilities automatically."
        )

    band_specs = [
        ("Below 50%", 0.00, 0.50), ("50–59%", 0.50, 0.60),
        ("60–69%", 0.60, 0.70),
        ("70–79%", 0.70, 0.80), ("80–89%", 0.80, 0.90),
        ("90%+", 0.90, 1.01),
    ]
    calibration_rows = [
        summary for label, low, high in band_specs
        if (summary := _learning_group_summary(
            [row for row in graded if low <= row["prob"] < high], label
        ))
    ]
    st.markdown("**Calibration By Hit Chance**")
    st.dataframe(pd.DataFrame(calibration_rows), use_container_width=True, hide_index=True)

    segment_rows = []
    segment_specs = []
    for field, prefix in (
        ("sport", "Sport"), ("market", "Market"), ("side", "Side"),
        ("action", "Action"), ("line_type", "Line type"),
        ("sportsbook_grade", "Market check"),
    ):
        for value in sorted({row[field] for row in graded}):
            segment_specs.append((f"{prefix}: {value}", field, value))
    for label, field, value in segment_specs:
        summary = _learning_group_summary(
            [row for row in graded if row[field] == value], label
        )
        if summary:
            segment_rows.append(summary)
    st.markdown("**Performance By Segment**")
    st.dataframe(pd.DataFrame(segment_rows), use_container_width=True, hide_index=True)

    action_groups = {
        action: [row for row in graded if row["action"] == action]
        for action in ("PLAY", "WATCH", "PASS")
    }
    play_rows = action_groups["PLAY"]
    watch_rows = action_groups["WATCH"]
    pass_rows = action_groups["PASS"]
    recommended_rows = play_rows + watch_rows
    recommendation_rows = [
        summary for summary in (
            _learning_group_summary(recommended_rows, "Recommended: PLAY + WATCH"),
            _learning_group_summary(pass_rows, "Not recommended: PASS"),
        ) if summary
    ]
    st.markdown("**Recommendation Separation**")
    st.dataframe(
        pd.DataFrame(recommendation_rows), use_container_width=True, hide_index=True
    )

    line_action_rows = _learning_pair_rows(
        graded, "line_type", "Line type", "action", "Action"
    )
    line_sport_rows = _learning_pair_rows(
        graded, "line_type", "Line type", "sport", "Sport"
    )
    line_gate_rows = _learning_line_type_gate_rows(graded)
    st.markdown("**Economic Separation Audit**")
    st.caption(
        "Standard and adjusted-payout lines are evaluated separately. Hit rate alone does not "
        "measure value when the payout changes, so only standard lines can receive a scanner "
        "PLAY or WATCH without an exact payout check."
    )
    st.dataframe(
        pd.DataFrame(line_action_rows), use_container_width=True, hide_index=True
    )
    with st.expander("Line type by sport and PASS gate", expanded=False):
        st.markdown("**Line Type × Sport**")
        st.dataframe(
            pd.DataFrame(line_sport_rows), use_container_width=True, hide_index=True
        )
        st.markdown("**Line Type × PASS Gate**")
        if line_gate_rows:
            line_gate_columns = [
                "Segment", "N", "PASS share", "Sample", "Predicted", "Actual",
                "Actual 95% range", "Gap", "Brier",
            ]
            st.dataframe(
                pd.DataFrame(line_gate_rows)[line_gate_columns],
                use_container_width=True,
                hide_index=True,
            )
        else:
            st.caption("No settled PASS decisions are available by line type.")

    pass_reason_rows = _learning_pass_reason_rows(graded)
    st.markdown("**PASS Gate Audit**")
    if pass_reason_rows:
        pass_columns = [
            "Segment", "N", "PASS share", "Sample", "Predicted", "Actual",
            "Actual 95% range", "Gap", "Brier",
        ]
        st.dataframe(
            pd.DataFrame(pass_reason_rows)[pass_columns],
            use_container_width=True,
            hide_index=True,
        )
        st.caption(
            "A PASS can carry more than one gate reason, so rows overlap. New scans store exact gate reasons; "
            "older decisions are reconstructed from their saved evidence, rank penalties, and risk flags."
        )
        with st.expander("Inspect settled PASS decisions", expanded=False):
            pass_detail_rows = [
                {
                    "Date": row.get("game_date", ""),
                    "Sport": row.get("sport", ""),
                    "Player": row.get("player", ""),
                    "Market": row.get("market", ""),
                    "Line type": row.get("line_type", ""),
                    "Model chance": f"{float(row.get('prob', 0)):.1%}",
                    "Evidence": (
                        f"{float(row['evidence']):.0f}"
                        if row.get("evidence") is not None else "—"
                    ),
                    "Entry score": (
                        f"{float(row['entry_score']):.0f}"
                        if row.get("entry_score") is not None else "—"
                    ),
                    "Gate reasons": " | ".join(_learning_pass_gate_reasons(row)),
                    "Result": row.get("result", ""),
                }
                for row in sorted(
                    pass_rows,
                    key=lambda item: (item.get("game_date", ""), item.get("player", "")),
                    reverse=True,
                )
            ]
            st.dataframe(
                pd.DataFrame(pass_detail_rows),
                use_container_width=True,
                hide_index=True,
            )
    else:
        st.caption("No settled PASS decisions are available for gate analysis.")
    if play_rows and len(play_rows) < 20:
        st.info(
            f"PLAY is promising, but only {len(play_rows)} unique settled decisions are available. "
            "Keep the current gate until this reaches at least 20; do not loosen it from an early winning streak."
        )
    if len(watch_rows) >= 15 and len(pass_rows) >= 15:
        watch_actual = sum(row["actual"] for row in watch_rows) / len(watch_rows)
        pass_actual = sum(row["actual"] for row in pass_rows) / len(pass_rows)
        watch_predicted = sum(row["prob"] for row in watch_rows) / len(watch_rows)
        if watch_actual + 0.05 < pass_actual or watch_predicted - watch_actual >= 0.08:
            st.warning(
                f"Action-order audit: WATCH hit {watch_actual:.1%} versus PASS {pass_actual:.1%}, "
                f"and WATCH was predicted at {watch_predicted:.1%}. The ranking gate needs more "
                "unique outcomes before it should drive entry construction."
            )

    def report_table(title: str, rows: list) -> list:
        lines = [title]
        if not rows:
            return lines + ["No settled rows available."]
        columns = [
            "Segment", "N", "Sample", "Predicted", "Actual",
            "Actual 95% range", "Gap", "Brier",
        ]
        lines.append(" | ".join(columns))
        for row in rows:
            lines.append(" | ".join(str(row.get(column, "")) for column in columns))
        return lines

    report_lines = [
        "PROPIQ MODEL LEARNING REPORT",
        "",
        "FILTERS",
        f"Sport: {sport_filter}",
        f"Decision source: {source_labels.get(source_filter, source_filter)}",
        f"Model version: {version_filter}",
        "Evaluation unit: latest valid pregame snapshot per unique prop",
        "",
        "COVERAGE",
        f"Captured snapshots: {len(filtered)}",
        f"Unique decisions: {len(unique_filtered)}",
        f"Settled snapshots: {len(snapshot_graded)}",
        f"Settled unique decisions: {len(graded)}",
        f"Repeated snapshots excluded: {repeated_snapshots}",
        f"Pending unique decisions: {pending}",
        f"Pushes: {pushes}",
        "",
        "HEADLINE",
        f"Actual hit rate: {actual:.1%}" if actual is not None else "Actual hit rate: N/A",
        f"Model average: {predicted:.1%}" if predicted is not None else "Model average: N/A",
        f"Calibration gap: {gap:+.1%}" if gap is not None else "Calibration gap: N/A",
        f"Brier score: {brier:.3f}" if brier is not None else "Brier score: N/A",
        f"Constant-rate Brier baseline: {baseline_brier:.3f}" if baseline_brier is not None else "Constant-rate Brier baseline: N/A",
        f"Brier skill vs baseline: {brier_skill:+.1%}" if brier_skill is not None else "Brier skill vs baseline: N/A",
        f"Rolling shadow version: {LEARNING_SHADOW_CALIBRATOR_VERSION}",
        f"Rolling shadow shared outcomes: {len(rolling_shadow)}",
        f"Rolling shadow active Brier: {shadow_active_brier:.3f}" if shadow_active_brier is not None else "Rolling shadow active Brier: N/A",
        f"Rolling shadow Brier: {shadow_brier:.3f}" if shadow_brier is not None else "Rolling shadow Brier: N/A",
        f"Rolling shadow improvement: {shadow_delta:+.3f}" if shadow_delta is not None else "Rolling shadow improvement: N/A",
        "",
    ]
    report_lines.extend(report_table("CALIBRATION BY HIT CHANCE", calibration_rows))
    report_lines.append("")
    report_lines.extend(report_table("PERFORMANCE BY SEGMENT", segment_rows))
    report_lines.append("")
    report_lines.extend(report_table("RECOMMENDATION SEPARATION", recommendation_rows))
    report_lines.append("")
    report_lines.extend(report_table("LINE TYPE BY ACTION", line_action_rows))
    report_lines.append("")
    report_lines.extend(report_table("LINE TYPE BY SPORT", line_sport_rows))
    report_lines.append("")
    report_lines.append("LINE TYPE BY PASS GATE")
    if line_gate_rows:
        line_gate_columns = [
            "Segment", "N", "PASS share", "Sample", "Predicted", "Actual",
            "Actual 95% range", "Gap", "Brier",
        ]
        report_lines.append(" | ".join(line_gate_columns))
        for row in line_gate_rows:
            report_lines.append(
                " | ".join(str(row.get(column, "")) for column in line_gate_columns)
            )
    else:
        report_lines.append("No settled PASS decisions available by line type.")
    report_lines.append("")
    report_lines.append("PASS GATE AUDIT")
    if pass_reason_rows:
        pass_columns = [
            "Segment", "N", "PASS share", "Sample", "Predicted", "Actual",
            "Actual 95% range", "Gap", "Brier",
        ]
        report_lines.append(" | ".join(pass_columns))
        for row in pass_reason_rows:
            report_lines.append(" | ".join(str(row.get(column, "")) for column in pass_columns))
    else:
        report_lines.append("No settled PASS decisions available.")
    report_text = "\n".join(report_lines)

    with st.expander("Copy scanner performance report", expanded=False):
        st.caption(
            "Tap the copy icon in the report below, then paste the complete text into this chat."
        )
        st.code(report_text, language=None)
        st.download_button(
            "Download report as text",
            data=report_text,
            file_name=(
                f"propiq-scanner-report-{str(sport_filter).lower().replace(' ', '-')}-"
                f"{_cache_date()}.txt"
            ),
            mime="text/plain",
            key="download_scanner_learning_report",
            use_container_width=True,
        )

    clv_rows = [row for row in graded if row["clv"] is not None]
    if clv_rows:
        average_clv = sum(row["clv"] for row in clv_rows) / len(clv_rows)
        favorable = sum(1 for row in clv_rows if row["clv"] > 0) / len(clv_rows)
        st.caption(
            f"Closing-line capture: {len(clv_rows)} matched lines · average directional movement "
            f"{average_clv:+.2f} · favorable {favorable:.0%}. Positive means the scanned line was better than the last pregame line."
        )
    else:
        st.caption(
            "Closing-line capture is waiting for matching pregame PrizePicks line-history snapshots."
        )

    shadow_rows = [
        (row, row["shadow_probability"] / 100.0)
        for row in graded if row.get("shadow_probability") is not None
    ]
    if shadow_rows:
        active_brier = sum(row["brier"] for row, _ in shadow_rows) / len(shadow_rows)
        shadow_brier = sum((prob - row["actual"]) ** 2 for row, prob in shadow_rows) / len(shadow_rows)
        st.caption(
            f"Shadow model: {len(shadow_rows)} shared outcomes · active Brier {active_brier:.3f} · "
            f"shadow Brier {shadow_brier:.3f}. Lower is better."
        )


def _mlb_backtest_rows(tracker_entries: list) -> list:
    """Normalize settled MLB tracker entries into rows for calibration/backtest."""
    rows = []
    for entry in tracker_entries:
        sport = str(entry.get("Sport", "")).upper()
        prop = str(entry.get("Matchup", ""))
        if sport != "MLB" and prop not in ("Strikeouts", "Hitter Fantasy Score"):
            continue
        result = str(entry.get("Result", "Pending"))
        if result not in ("Hit", "Miss"):
            continue

        prob = _parse_percent_value(entry.get("Adjusted"))
        if prob is None or not (0.0 <= prob <= 1.0):
            continue

        confidence = _parse_numeric_value(
            entry.get("Confidence", entry.get("confidence")),
            default=None,
        )
        if confidence is None:
            confidence = round(prob * 100)

        edge = _parse_numeric_value(entry.get("Edge", entry.get("edge")), default=None)
        sample = _parse_numeric_value(entry.get("Sample", entry.get("samples")), default=None)
        consistency = _parse_percent_value(entry.get("Consistency"), default=None)
        verdict = str(entry.get("Verdict", ""))
        risk_text = " | ".join(
            str(entry.get(k, ""))
            for k in ("Risk Flags", "Trap", "Notes", "Venue")
            if entry.get(k)
        )
        risk_lower = risk_text.lower()
        rows.append({
            "player": entry.get("Player", ""),
            "prop": prop or "MLB",
            "prob": prob,
            "confidence": float(confidence),
            "edge": edge,
            "sample": sample,
            "consistency": consistency,
            "verdict": verdict or "Unlabeled",
            "actual": 1.0 if result == "Hit" else 0.0,
            "result": result,
            "projected_lineup": "projected" in risk_lower,
            "low_pitch_count": ("low pitch" in risk_lower or "~7" in risk_lower or "limit" in risk_lower),
            "watchlist": ("watchlist" in risk_lower or "trap" in risk_lower),
            "small_sample": (
                sample is not None and sample < 6
            ) or "small sample" in risk_lower or "only " in risk_lower,
        })
    return rows


def _mlb_backtest_group(rows: list, label: str, predicate) -> Optional[dict]:
    group = [r for r in rows if predicate(r)]
    if not group:
        return None
    n = len(group)
    pred = sum(r["prob"] for r in group) / n
    actual = sum(r["actual"] for r in group) / n
    brier = sum((r["prob"] - r["actual"]) ** 2 for r in group) / n
    conf = sum(r["confidence"] for r in group) / n
    gap = actual - pred
    return {
        "label": label,
        "n": n,
        "pred": pred,
        "actual": actual,
        "gap": gap,
        "brier": brier,
        "conf": conf,
    }


def _render_mlb_backtest_dashboard(tracker_entries: list) -> None:
    rows = _mlb_backtest_rows(tracker_entries)
    st.markdown("<div class='section-header'>MLB Backtest Dashboard</div>", unsafe_allow_html=True)
    if not rows:
        st.markdown(
            "<div style='background:#0f172a;border:1px dashed #1e293b;border-radius:12px;"
            "padding:1rem 1.1rem;color:#6b7f96;font-family:JetBrains Mono,monospace;"
            "font-size:0.68rem;line-height:1.7;'>"
            "No settled MLB picks yet. Add MLB picks to the tracker and mark them Hit/Miss; "
            "this dashboard will bucket performance by confidence, verdict, prop, and risk flags."
            "</div>",
            unsafe_allow_html=True,
        )
        return

    n = len(rows)
    pred = sum(r["prob"] for r in rows) / n
    actual = sum(r["actual"] for r in rows) / n
    brier = sum((r["prob"] - r["actual"]) ** 2 for r in rows) / n
    roi_units = sum(1 if r["actual"] else -1 for r in rows)
    gap = actual - pred
    sample_label = "Provisional" if n < 20 else ("Developing" if n < 50 else "Established")
    gap_color = "#00e896" if abs(gap) <= 0.05 else ("#ffc107" if abs(gap) <= 0.12 else "#ff3d5c")
    edge_color = "#00e896" if roi_units > 0 else ("#ff3d5c" if roi_units < 0 else "#ffc107")

    st.markdown(
        f"<div style='background:rgba(0,196,204,0.05);border:1px solid rgba(0,196,204,0.16);"
        f"border-radius:10px;padding:0.85rem 1rem;margin-bottom:0.75rem;"
        f"display:flex;gap:18px;flex-wrap:wrap;font-family:JetBrains Mono,monospace;'>"
        f"<div><div style='font-size:0.52rem;color:#6b7f96;'>SAMPLE</div>"
        f"<div style='font-size:0.9rem;color:#f0f4f8;font-weight:800;'>{n} · {sample_label}</div></div>"
        f"<div><div style='font-size:0.52rem;color:#6b7f96;'>MODEL AVG</div>"
        f"<div style='font-size:0.9rem;color:#f0f4f8;font-weight:800;'>{pred:.1%}</div></div>"
        f"<div><div style='font-size:0.52rem;color:#6b7f96;'>ACTUAL HIT</div>"
        f"<div style='font-size:0.9rem;color:#f0f4f8;font-weight:800;'>{actual:.1%}</div></div>"
        f"<div><div style='font-size:0.52rem;color:#6b7f96;'>CALIBRATION</div>"
        f"<div style='font-size:0.9rem;color:{gap_color};font-weight:800;'>{gap:+.1%}</div></div>"
        f"<div><div style='font-size:0.52rem;color:#6b7f96;'>FLAT UNITS</div>"
        f"<div style='font-size:0.9rem;color:{edge_color};font-weight:800;'>{roi_units:+.0f}</div></div>"
        f"<div><div style='font-size:0.52rem;color:#6b7f96;'>BRIER</div>"
        f"<div style='font-size:0.9rem;color:#f0f4f8;font-weight:800;'>{brier:.3f}</div></div>"
        f"</div>",
        unsafe_allow_html=True,
    )

    groups = []
    group_specs = [
        ("Confidence 80+", lambda r: r["confidence"] >= 80),
        ("Confidence 65-79", lambda r: 65 <= r["confidence"] < 80),
        ("Confidence 55-64", lambda r: 55 <= r["confidence"] < 65),
        ("Confidence <55", lambda r: r["confidence"] < 55),
        ("Strong Picks", lambda r: "Strong" in r["verdict"]),
        ("Lean Picks", lambda r: "Lean" in r["verdict"]),
        ("Strikeouts", lambda r: r["prop"] == "Strikeouts"),
        ("Hitter FS", lambda r: r["prop"] == "Hitter Fantasy Score"),
        ("Projected Lineup", lambda r: r["projected_lineup"]),
        ("Low Pitch Count", lambda r: r["low_pitch_count"]),
        ("Small Sample", lambda r: r["small_sample"]),
        ("Watchlist/Trap", lambda r: r["watchlist"]),
    ]
    for label, pred_fn in group_specs:
        item = _mlb_backtest_group(rows, label, pred_fn)
        if item:
            groups.append(item)

    row_html = ""
    for g in groups:
        gap_col = "#00e896" if abs(g["gap"]) <= 0.08 else ("#ffc107" if abs(g["gap"]) <= 0.15 else "#ff3d5c")
        row_html += (
            "<tr style='border-bottom:1px solid rgba(255,255,255,0.05);'>"
            f"<td style='padding:6px 8px;color:#f0f4f8;font-weight:800;'>{g['label']}</td>"
            f"<td style='padding:6px 8px;color:#9aaec4;'>{g['n']}</td>"
            f"<td style='padding:6px 8px;color:#9aaec4;'>{g['conf']:.0f}</td>"
            f"<td style='padding:6px 8px;color:#9aaec4;'>{g['pred']:.1%}</td>"
            f"<td style='padding:6px 8px;color:#9aaec4;'>{g['actual']:.1%}</td>"
            f"<td style='padding:6px 8px;color:{gap_col};font-weight:800;'>{g['gap']:+.1%}</td>"
            f"<td style='padding:6px 8px;color:#9aaec4;'>{g['brier']:.3f}</td>"
            "</tr>"
        )
    if row_html:
        st.markdown(
            "<table style='width:100%;border-collapse:collapse;font-family:JetBrains Mono,monospace;"
            "font-size:0.66rem;margin-bottom:0.8rem;'>"
            "<thead><tr style='color:#6b7f96;border-bottom:1px solid rgba(255,255,255,0.1);'>"
            "<th style='padding:4px 8px;text-align:left;'>SEGMENT</th>"
            "<th style='padding:4px 8px;text-align:left;'>N</th>"
            "<th style='padding:4px 8px;text-align:left;'>CONF</th>"
            "<th style='padding:4px 8px;text-align:left;'>PRED</th>"
            "<th style='padding:4px 8px;text-align:left;'>ACTUAL</th>"
            "<th style='padding:4px 8px;text-align:left;'>GAP</th>"
            "<th style='padding:4px 8px;text-align:left;'>BRIER</th>"
            f"</tr></thead><tbody>{row_html}</tbody></table>",
            unsafe_allow_html=True,
        )

    if n < 20:
        st.caption("Backtest is provisional until at least 20 MLB picks settle; 50+ is much more informative.")


def render_pick_list() -> None:
    """Visible main-page shortlist for props the user is considering."""
    legs = st.session_state.get("parlay_legs", [])
    notice = st.session_state.pop("parlay_notice", None)
    if notice:
        if "full" in notice.lower():
            st.warning(notice)
        else:
            st.success(notice)

    with st.expander(f"🎯 PrizePicks Pick List ({len(legs)}/6)", expanded=bool(legs)):
        if not legs:
            st.markdown(
                "<div style='font-family:JetBrains Mono,monospace;font-size:0.68rem;"
                "color:#73869a;line-height:1.7;'>"
                "Add picks from the Edge Scanner or player analyzers. This is your shortlist "
                "for props you are thinking about entering in PrizePicks.</div>",
                unsafe_allow_html=True,
            )
            return

        remove_idx = None
        for i, leg in enumerate(legs):
            verdict = str(leg.get("verdict", ""))
            color = {
                "Strong Over": "#18f3a2", "Lean Over": "#ffd166",
                "Strong Under": "#ff4768", "Lean Under": "#ff8a4c",
            }.get(verdict, "#a8b9ca")
            icon = {
                "Strong Over": "🟢", "Lean Over": "🟡",
                "Strong Under": "🔴", "Lean Under": "🟠",
            }.get(verdict, "⚪")
            c1, c2 = st.columns([10, 1])
            with c1:
                st.markdown(
                    f"<div class='parlay-leg' style='border:1px solid rgba(255,255,255,0.08);"
                    f"border-radius:12px;margin-bottom:0.4rem;background:rgba(255,255,255,0.035);'>"
                    f"<div style='min-width:0;'>"
                    f"<div class='parlay-leg-name'>{leg.get('player','')}</div>"
                    f"<div style='display:flex;gap:6px;flex-wrap:wrap;margin-top:5px;'>"
                    f"<span class='parlay-leg-pick'>{icon} {leg.get('side','')} {leg.get('line','')}</span>"
                    f"<span class='edge-pill-v55 accent'>{leg.get('prop','')}</span>"
                    f"<span class='edge-pill-v55'>{leg.get('sport','')}</span>"
                    f"<span class='parlay-leg-conf' style='color:{color};'>"
                    f"Conf {leg.get('confidence', leg.get('adj', '—'))}</span>"
                    f"</div></div></div>",
                    unsafe_allow_html=True,
                )
            with c2:
                if st.button("✕", key=f"pick_list_remove_{i}", help="Remove"):
                    remove_idx = i

        if remove_idx is not None:
            st.session_state.parlay_legs.pop(remove_idx)
            st.rerun()

        share_lines = ["PropIQ Pick List"] + [
            f"{leg.get('player','')} - {leg.get('prop','')} {leg.get('side','')} {leg.get('line','')} ({leg.get('sport','')})"
            for leg in legs
        ]
        st.code("\n".join(share_lines), language=None)
        if st.button("Clear Pick List", key="main_clear_pick_list", use_container_width=True):
            st.session_state.parlay_legs = []
            st.rerun()


def render_sticky_pick_tray() -> None:
    """Fixed bottom shortlist status for mobile pick-board workflow."""
    legs = st.session_state.get("parlay_legs", []) or []
    count = len(legs)
    confidences = []
    for leg in legs:
        try:
            confidences.append(float(leg.get("confidence", leg.get("adj", 0)) or 0))
        except Exception:
            pass
    avg_conf = round(sum(confidences) / len(confidences)) if confidences else 0
    weak = sum(1 for c in confidences if c < 65)
    watch = sum(
        1 for leg in legs
        if "watch" in str(leg.get("verdict", "")).lower()
        or "trap" in str(leg.get("verdict", "")).lower()
    )
    if count == 0:
        risk_label, risk_class = "Ready", ""
        sub = "Add candidates from Edge or an analyzer"
    elif weak or watch:
        risk_label, risk_class = "High", "high"
        sub = f"{count}/6 selected · review weak legs"
    elif avg_conf >= 80 and count <= 4:
        risk_label, risk_class = "Low", ""
        sub = f"{count}/6 selected · shortlist looks clean"
    else:
        risk_label, risk_class = "Med", "medium"
        sub = f"{count}/6 selected · keep it selective"

    st.markdown(
        f"<div class='pick-tray-v63'>"
        f"<div class='pick-tray-v63-inner'>"
        f"<div>"
        f"<div class='pick-tray-title-v63'>Pick List</div>"
        f"<div class='pick-tray-sub-v63'>{sub}</div>"
        f"</div>"
        f"<div class='pick-tray-stat-v63'><span>Picks</span><strong>{count}/6</strong></div>"
        f"<div class='pick-tray-stat-v63 pick-tray-risk-v63 {risk_class}'>"
        f"<span>Risk</span><strong>{risk_label}</strong></div>"
        f"</div></div>",
        unsafe_allow_html=True,
    )


def _move_pick_list_leg(index: int, direction: int) -> None:
    legs = st.session_state.get("parlay_legs", []) or []
    new_index = index + direction
    if 0 <= index < len(legs) and 0 <= new_index < len(legs):
        legs[index], legs[new_index] = legs[new_index], legs[index]


def _remove_pick_list_leg(index: int) -> None:
    legs = st.session_state.get("parlay_legs", []) or []
    if 0 <= index < len(legs):
        removed = legs.pop(index)
        st.session_state.parlay_notice = f"Removed {removed.get('player', 'pick')}."


def _set_tracker_result(index: int, result: str) -> None:
    tracker = st.session_state.get("tracker", []) or []
    if not (0 <= index < len(tracker)):
        return
    tracker[index]["Result"] = result
    row_id = tracker[index].get("id")
    if row_id:
        update_result_in_supabase(row_id, result)


def _remove_tracker_entry(index: int) -> None:
    tracker = st.session_state.get("tracker", []) or []
    if not (0 <= index < len(tracker)):
        return
    removed = tracker.pop(index)
    if removed.get("id"):
        delete_from_supabase(removed["id"])


def render_pick_list_page() -> None:
    """First-class shortlist workspace with ordering and analyzer return paths."""
    import html as _html

    legs = st.session_state.get("parlay_legs", []) or []
    notice = st.session_state.pop("parlay_notice", None)
    if notice:
        st.toast(notice)

    confidences = []
    probabilities = []
    watch_count = 0
    for leg in legs:
        try:
            confidences.append(float(leg.get("confidence", leg.get("adj", 0)) or 0))
        except Exception:
            pass
        try:
            probabilities.append(float(leg.get("adj", 0) or 0))
        except Exception:
            pass
        if "watch" in str(leg.get("verdict", "")).lower() or "lean" in str(leg.get("verdict", "")).lower():
            watch_count += 1

    avg_conf = round(sum(confidences) / len(confidences)) if confidences else 0
    avg_prob = round(sum(probabilities) / len(probabilities)) if probabilities else 0
    avg_entry = round(0.7 * avg_prob + 0.3 * avg_conf) if legs else 0
    readiness = (
        "Ready to review" if legs and avg_entry >= 80 and watch_count == 0 else
        "Needs review" if legs else "Empty"
    )

    st.markdown(
        "<div id='workspace-top' class='workspace-page-head'><div>"
        "<h1>Pick List</h1>"
        "<p>Your working shortlist. Reorder candidates, reopen the full analysis, and remove weak legs before building an entry.</p>"
        "</div></div>",
        unsafe_allow_html=True,
    )
    st.markdown(
        f"<div class='workspace-summary-grid'>"
        f"<div class='workspace-summary-item'><span>Selected</span><strong>{len(legs)} / 6</strong></div>"
        f"<div class='workspace-summary-item'><span>Avg hit chance</span><strong>{avg_prob or '—'}{'%' if avg_prob else ''}</strong></div>"
        f"<div class='workspace-summary-item'><span>Avg evidence</span><strong>{avg_conf or '—'}{' / 100' if avg_conf else ''}</strong></div>"
        f"<div class='workspace-summary-item'><span>Status</span><strong>{readiness}</strong></div>"
        f"</div>",
        unsafe_allow_html=True,
    )

    if not legs:
        st.markdown(
            "<div class='pick-list-empty'><strong style='color:var(--text);'>No picks saved yet</strong><br>"
            "Add candidates from an analyzer or the Edge Scanner. They will remain here while you move around the app.</div>",
            unsafe_allow_html=True,
        )
        st.button(
            "Open Edge Scanner", key="empty_pick_list_edge", use_container_width=True,
            on_click=navigate_to_view, args=("edge", "edge-scanner-controls"),
        )
        return

    if watch_count:
        st.warning(f"{watch_count} pick{'s' if watch_count != 1 else ''} still carry a Lean or Watch-level verdict. Reopen those analyses before entering.")

    for i, leg in enumerate(list(legs)):
        verdict = str(leg.get("verdict", "Unrated"))
        verdict_color = (
            "#36d399" if "Strong" in verdict else
            "#f4c95d" if "Lean" in verdict or "Watch" in verdict else "#aeb9c7"
        )
        player = _html.escape(str(leg.get("player", "Unknown player")))
        prop = _html.escape(str(leg.get("prop", "Prop")))
        sport = _html.escape(str(leg.get("sport", "")))
        side = _html.escape(str(leg.get("side", "")))
        line = _html.escape(str(leg.get("line", "—")))
        st.markdown(
            f"<div class='pick-list-card'>"
            f"<div style='display:flex;justify-content:space-between;gap:12px;align-items:flex-start;'>"
            f"<div><strong>{i + 1}. {player}</strong>"
            f"<div class='pick-list-card-meta'>"
            f"<span class='edge-pill-v55 accent'>{sport}</span>"
            f"<span class='edge-pill-v55'>{prop}</span>"
            f"<span class='edge-pill-v55'>{side} {line}</span>"
            f"</div></div>"
            f"<div style='text-align:right;font-family:var(--font-mono);'>"
            f"<div style='color:{verdict_color};font-size:0.64rem;font-weight:800;'>{_html.escape(verdict)}</div>"
            f"<div style='color:var(--text3);font-size:0.54rem;margin-top:4px;'>"
            f"Hit {leg.get('adj', '—')}% · Evidence {leg.get('confidence', '—')}</div>"
            f"</div></div></div>",
            unsafe_allow_html=True,
        )
        up_col, down_col, analyze_col, remove_col = st.columns([1, 1, 4, 1])
        with up_col:
            st.button("↑", key=f"pick_up_{i}", help="Move up", disabled=i == 0,
                      use_container_width=True, on_click=_move_pick_list_leg, args=(i, -1))
        with down_col:
            st.button("↓", key=f"pick_down_{i}", help="Move down", disabled=i == len(legs) - 1,
                      use_container_width=True, on_click=_move_pick_list_leg, args=(i, 1))
        with analyze_col:
            st.button("Analyze", key=f"pick_analyze_{i}", use_container_width=True,
                      on_click=open_pick_list_analyzer, args=(dict(leg),))
        with remove_col:
            st.button("✕", key=f"pick_remove_page_{i}", help="Remove", use_container_width=True,
                      on_click=_remove_pick_list_leg, args=(i,))

    share_lines = ["PropIQ Pick List"] + [
        f"{i + 1}. {leg.get('player', '')} | {leg.get('prop', '')} | {leg.get('side', '')} {leg.get('line', '')} | {leg.get('sport', '')}"
        for i, leg in enumerate(legs)
    ]
    with st.expander("Shareable list", expanded=False):
        st.code("\n".join(share_lines), language=None)

    if not st.session_state.get("confirm_clear_pick_list"):
        if st.button("Clear Pick List", key="pick_page_clear", use_container_width=True):
            st.session_state.confirm_clear_pick_list = True
            st.rerun()
    else:
        st.warning("Clear every saved pick?")
        clear_yes, clear_no = st.columns(2)
        with clear_yes:
            if st.button("Yes, clear all", key="pick_page_clear_yes", use_container_width=True):
                st.session_state.parlay_legs = []
                st.session_state.confirm_clear_pick_list = False
                st.rerun()
        with clear_no:
            if st.button("Cancel", key="pick_page_clear_no", use_container_width=True):
                st.session_state.confirm_clear_pick_list = False
                st.rerun()


def render_entry_roi_dashboard(entries: list) -> None:
    """Show normalized realized returns for exact entries the user marked entered."""
    import html as _html

    entries = [
        entry for entry in (entries or [])
        if str(entry.get("sport", "")).upper() != "WNBA"
        and not any(
            str(leg.get("sport", "")).upper() == "WNBA"
            for leg in (entry.get("legs", []) or [])
        )
    ]
    settled_entries = [entry for entry in entries if entry.get("status") == "Settled"]
    pending_entries = [entry for entry in entries if entry.get("status") == "Pending"]
    review_entries = [entry for entry in entries if entry.get("status") == "Needs review"]
    total_stake = sum(float(entry.get("stake", 1) or 1) for entry in settled_entries)
    total_return = sum(float(entry.get("realized_return", 0) or 0) for entry in settled_entries)
    total_profit = total_return - total_stake
    roi = (total_profit / total_stake) if total_stake else None
    positive = sum(
        1 for entry in settled_entries if float(entry.get("realized_profit", 0) or 0) > 0
    )
    positive_rate = positive / len(settled_entries) if settled_entries else None

    st.markdown(
        "<div class='section-header'>Entered-Slip ROI</div>",
        unsafe_allow_html=True,
    )
    st.markdown(
        f"<div class='workspace-summary-grid'>"
        f"<div class='workspace-summary-item'><span>Realized ROI</span><strong style='color:{'var(--green)' if roi is not None and roi >= 0 else 'var(--red)'};'>{f'{roi:+.1%}' if roi is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Profit</span><strong>{total_profit:+.2f}u</strong></div>"
        f"<div class='workspace-summary-item'><span>Positive return</span><strong>{f'{positive_rate:.0%}' if positive_rate is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Tracked</span><strong>{len(entries)}</strong></div>"
        f"</div>",
        unsafe_allow_html=True,
    )
    st.caption(
        "Returns are normalized to a 1-unit stake using the exact payout entered in the builder. "
        f"{len(settled_entries)} settled · {len(pending_entries)} pending · {len(review_entries)} push review."
    )

    if not entries:
        st.markdown(
            "<div class='pick-list-empty'><strong style='color:var(--text);'>No exact entries tracked yet</strong><br>"
            "Enter the displayed payout in Edge, then use Track as Entered after submitting that exact slip.</div>",
            unsafe_allow_html=True,
        )
        return

    table_rows = []
    report_lines = [
        "PROPIQ ENTERED-SLIP ROI REPORT",
        "",
        f"Tracked entries: {len(entries)}",
        f"Settled entries: {len(settled_entries)}",
        f"Pending entries: {len(pending_entries)}",
        f"Push review: {len(review_entries)}",
        f"Settled stake: {total_stake:.2f}u",
        f"Settled return: {total_return:.2f}u",
        f"Realized profit: {total_profit:+.2f}u",
        f"Realized ROI: {roi:+.1%}" if roi is not None else "Realized ROI: N/A",
        "",
        "ENTRY HISTORY",
    ]
    for entry in entries[:100]:
        legs = entry.get("legs", []) or []
        leg_label = " + ".join(
            f"{leg.get('player', '')} {leg.get('side', '')} {leg.get('line', '')}"
            for leg in legs
        )
        expected_profit = _parse_numeric_value(entry.get("expected_profit"), None)
        actual_profit = _parse_numeric_value(entry.get("realized_profit"), None)
        table_rows.append({
            "Date": str(entry.get("created_at", ""))[:10],
            "Sport": entry.get("sport", ""),
            "Entry": leg_label,
            "Payout": f"{float(entry.get('displayed_full_payout', 0) or 0):.2f}x",
            "Expected": f"{expected_profit:+.1%}" if expected_profit is not None else "—",
            "Actual": f"{actual_profit:+.2f}u" if actual_profit is not None else "—",
            "Status": entry.get("result", entry.get("status", "Pending")),
        })
        report_lines.append(
            f"{str(entry.get('created_at', ''))[:10]} | {entry.get('sport', '')} | "
            f"{leg_label} | payout {float(entry.get('displayed_full_payout', 0) or 0):.2f}x | "
            f"expected {expected_profit:+.1%} | " if expected_profit is not None else
            f"{str(entry.get('created_at', ''))[:10]} | {entry.get('sport', '')} | "
            f"{leg_label} | payout {float(entry.get('displayed_full_payout', 0) or 0):.2f}x | expected N/A | "
        )
        report_lines[-1] += (
            f"actual {actual_profit:+.2f}u | {entry.get('result', entry.get('status', 'Pending'))}"
            if actual_profit is not None else
            f"actual pending | {entry.get('result', entry.get('status', 'Pending'))}"
        )

    with st.expander("Entered-slip history", expanded=False):
        st.dataframe(pd.DataFrame(table_rows), use_container_width=True, hide_index=True)
        report_text = "\n".join(report_lines)
        st.code(report_text, language=None)
        st.download_button(
            "Download ROI report",
            data=report_text,
            file_name=f"propiq-entry-roi-{_cache_date()}.txt",
            mime="text/plain",
            key="download_entry_roi_report",
            use_container_width=True,
        )


def render_results_page() -> None:
    """Tracked-pick outcomes and calibration live outside the analyzers."""
    import html as _html

    st.markdown(
        "<div id='workspace-top' class='workspace-page-head'><div>"
        "<h1>Results</h1>"
        "<p>Measure every scanner decision against official outcomes, then inspect your manually tracked picks.</p>"
        "</div></div>",
        unsafe_allow_html=True,
    )

    tracker_store = st.session_state.get("tracker", []) or []
    tracker_pairs = [
        (index, entry) for index, entry in enumerate(tracker_store)
        if str(entry.get("Sport", entry.get("sport", ""))).upper() != "WNBA"
    ]
    tracker = [entry for _, entry in tracker_pairs]
    with st.spinner("Loading results history..."):
        predictions = [
            row for row in load_model_predictions()
            if str(row.get("sport", "")).upper() != "WNBA"
        ]
        entered_slips = [
            entry for entry in load_entry_ledger()
            if str(entry.get("sport", "")).upper() != "WNBA"
            and not any(
                str(leg.get("sport", "")).upper() == "WNBA"
                for leg in (entry.get("legs", []) or [])
            )
        ]
    # Outcome settlement is intentionally user-triggered. Performing dozens of
    # external API checks before rendering made this destination appear frozen.
    try:
        settle_entry_ledger(entered_slips, predictions)
    except Exception as err:
        record_debug_error("results.entry_settle", err)
    hits = sum(1 for entry in tracker if entry.get("Result") == "Hit")
    misses = sum(1 for entry in tracker if entry.get("Result") == "Miss")
    pending = sum(1 for entry in tracker if entry.get("Result", "Pending") == "Pending")
    pushes = sum(1 for entry in tracker if entry.get("Result") == "Push")
    settled = hits + misses
    win_rate = hits / settled if settled else None

    learning_a, learning_b = st.columns([2, 1])
    with learning_a:
        if st.button(
            "Refresh model outcomes", key="learning_refresh_outcomes",
            use_container_width=True,
        ):
            with st.spinner("Checking the oldest unresolved MLB decisions..."):
                outcome_stats = settle_model_predictions(predictions, max_events=40)
                entry_stats = settle_entry_ledger(entered_slips, predictions)
            st.toast(
                f"Settled {outcome_stats['updated']} prediction rows · "
                f"{entry_stats['settled']} entries · {outcome_stats['unresolved']} still pending"
            )
            st.rerun()
    with learning_b:
        if st.button(
            "Reload ledger", key="learning_reload_ledger", use_container_width=True
        ):
            load_model_predictions(force=True)
            load_entry_ledger(force=True)
            st.rerun()

    pending_predictions = sum(
        1 for row in _learning_unique_prediction_rows(predictions)
        if str(row.get("status", "Pending")) == "Pending"
    )
    st.caption(
        f"Loaded {len(predictions)} prediction snapshots and {len(entered_slips)} entered slips · "
        f"{pending_predictions} unique decisions await settlement. Outcome checks run only when you tap Refresh."
    )

    try:
        render_entry_roi_dashboard(entered_slips)
    except Exception as err:
        record_debug_error("results.roi_dashboard", err)
        st.error("Entered-slip history could not be rendered. Reload the ledger and retry.")
    try:
        render_model_learning_dashboard(predictions)
    except Exception as err:
        record_debug_error("results.learning_dashboard", err)
        st.error("The model-learning report could not be rendered. Reload the ledger and retry.")

    st.markdown(
        "<div class='section-header'>Manually Tracked Picks</div>",
        unsafe_allow_html=True,
    )
    st.markdown(
        f"<div class='workspace-summary-grid'>"
        f"<div class='workspace-summary-item'><span>Tracked win rate</span><strong>{f'{win_rate:.0%}' if win_rate is not None else '—'}</strong></div>"
        f"<div class='workspace-summary-item'><span>Hit</span><strong style='color:var(--green);'>{hits}</strong></div>"
        f"<div class='workspace-summary-item'><span>Miss</span><strong style='color:var(--red);'>{misses}</strong></div>"
        f"<div class='workspace-summary-item'><span>Pending</span><strong>{pending}</strong></div>"
        f"<div class='workspace-summary-item'><span>Push</span><strong>{pushes}</strong></div>"
        f"</div>",
        unsafe_allow_html=True,
    )

    if not tracker:
        st.markdown(
            "<div class='pick-list-empty'><strong style='color:var(--text);'>No tracked picks yet</strong><br>"
            "Use Add & Track from an analyzer or Edge result. The learning ledger above still records every scanner decision automatically.</div>",
            unsafe_allow_html=True,
        )
        return

    controls_a, controls_b = st.columns([2, 1])
    sports = sorted({str(entry.get("Sport", "Unknown") or "Unknown") for entry in tracker})
    with controls_a:
        sport_filter = st.selectbox("Sport", ["All sports"] + sports, key="results_sport_filter")
    with controls_b:
        if st.button("Refresh outcomes", key="results_refresh", use_container_width=True):
            updated = 0
            with st.spinner("Checking pending outcomes..."):
                for tracker_index, entry in tracker_pairs:
                    if entry.get("Result", "Pending") != "Pending":
                        continue
                    detected = auto_detect_result(entry)
                    if detected:
                        _set_tracker_result(tracker_index, detected)
                        tracker_store[tracker_index]["auto_detected"] = True
                        updated += 1
            st.toast(f"Updated {updated} outcome{'s' if updated != 1 else ''}.")
            if updated:
                st.rerun()

    visible_entries = [
        (i, entry) for i, entry in tracker_pairs
        if sport_filter == "All sports" or str(entry.get("Sport", "Unknown") or "Unknown") == sport_filter
    ]
    for i, entry in visible_entries:
        result = str(entry.get("Result", "Pending"))
        result_color = {
            "Hit": "#36d399", "Miss": "#f05d75", "Push": "#40d9e0",
            "Pending": "#748294",
        }.get(result, "#748294")
        player = _html.escape(str(entry.get("Player", "Unknown player")))
        line = _html.escape(str(entry.get("Line", "—")))
        matchup = _html.escape(str(entry.get("Matchup", "Prop")))
        opponent = _html.escape(str(entry.get("Opponent", "—")))
        verdict = _html.escape(str(entry.get("Verdict", "Unrated")))
        st.markdown(
            f"<div class='pick-list-card' style='border-left-color:{result_color};'>"
            f"<div style='display:flex;justify-content:space-between;gap:12px;align-items:flex-start;'>"
            f"<div><strong>{player}</strong><div class='pick-list-card-meta'>"
            f"<span class='edge-pill-v55 accent'>{matchup}</span>"
            f"<span class='edge-pill-v55'>{line}</span>"
            f"<span class='edge-pill-v55'>vs {opponent}</span></div></div>"
            f"<div style='text-align:right;font-family:var(--font-mono);'>"
            f"<div style='color:{result_color};font-weight:900;font-size:0.72rem;'>{result}</div>"
            f"<div style='color:var(--text3);font-size:0.52rem;margin-top:4px;'>{verdict}</div>"
            f"</div></div></div>",
            unsafe_allow_html=True,
        )
        hit_col, miss_col, push_col, pending_col, remove_col = st.columns([2, 2, 2, 2, 1])
        with hit_col:
            st.button("Hit", key=f"results_hit_{i}", use_container_width=True,
                      on_click=_set_tracker_result, args=(i, "Hit"))
        with miss_col:
            st.button("Miss", key=f"results_miss_{i}", use_container_width=True,
                      on_click=_set_tracker_result, args=(i, "Miss"))
        with push_col:
            st.button("Push", key=f"results_push_{i}", use_container_width=True,
                      on_click=_set_tracker_result, args=(i, "Push"))
        with pending_col:
            st.button("Pending", key=f"results_pending_{i}", use_container_width=True,
                      on_click=_set_tracker_result, args=(i, "Pending"))
        with remove_col:
            st.button("✕", key=f"results_remove_{i}", help="Remove", use_container_width=True,
                      on_click=_remove_tracker_entry, args=(i,))

    if sport_filter in ("All sports", "MLB"):
        with st.expander("MLB calibration dashboard", expanded=False):
            _render_mlb_backtest_dashboard(tracker)


def set_runtime_metric(key: str, status: str, detail: str = "", **extra) -> None:
    """Record lightweight app health/freshness metadata for diagnostics."""
    try:
        payload = {
            "status": status,
            "detail": str(detail)[:500],
            "time": datetime.utcnow().isoformat() + "Z",
        }
        payload.update(extra)
        st.session_state.runtime_metrics[key] = payload
    except Exception:
        pass


