def season_str_to_season(season_str: str) -> str:
    """Return season string as-is for nba_api e.g. '2025-26'."""
    return season_str.strip()

# ── H2H vs opponent ───────────────────────────

@st.cache_data(ttl=43200, show_spinner=False)
def get_h2h_logs(player_id: int, opp_abbr: str, season: str, _date: str = None) -> pd.DataFrame:
    """
    Fetch H2H logs vs opponent — regular season + playoff games.
    - Fetches last 3 regular seasons in parallel
    - In playoffs, also fetches current season playoff logs separately and merges
    - Lenient abbreviation matching (NYK/NY, BKN/BK, etc.)
    """
    empty = pd.DataFrame(columns=["GAME_DATE","MATCHUP","MIN","PTS","FGA","FTA","FG3A"])
    if not opp_abbr:
        return empty

    # Build list of abbreviation variants to match
    # NBA Stats uses 3-letter codes in MATCHUP field (e.g. "NYK vs. ATL")
    _ABBR_MAP = {
        "NY": "NYK", "BK": "BKN", "NO": "NOP", "SA": "SAS",
        "GS": "GSW", "OKC": "OKC", "PHX": "PHX", "UTA": "UTA",
    }
    opp_clean = _ABBR_MAP.get(opp_abbr.upper(), opp_abbr.upper())
    # Match either the 2-letter or 3-letter version
    def _matches(matchup_str):
        m = str(matchup_str).upper()
        return opp_clean in m or opp_abbr.upper() in m

    try:
        start_year = int(season.split("-")[0])
    except Exception:
        start_year = 2025

    import concurrent.futures
    all_rows = []
    _COLS = ["GAME_DATE","MATCHUP","MIN","PTS","FGA","FTA","FG3A"]

    def _fetch_season(yr, season_type="Regular Season"):
        season_str = f"{yr}-{str(yr+1)[-2:]}"
        try:
            df = playergamelog.PlayerGameLog(
                player_id=player_id,
                season=season_str,
                season_type_all_star=season_type,
                timeout=14,
            ).get_data_frames()[0]
        except Exception:
            # Fallback without season_type param
            try:
                df = playergamelog.PlayerGameLog(
                    player_id=player_id,
                    season=season_str,
                    timeout=14,
                ).get_data_frames()[0]
            except Exception:
                return pd.DataFrame(columns=_COLS)

        if df.empty:
            return pd.DataFrame(columns=_COLS)

        df["GAME_DATE"] = pd.to_datetime(df["GAME_DATE"], errors="coerce")
        for c in _COLS:
            if c not in df.columns:
                df[c] = None
        mask = df["MATCHUP"].apply(_matches)
        result = df[mask][_COLS].copy()
        return result

    # Fetch last 3 regular seasons in parallel
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as ex:
        reg_futures = {ex.submit(_fetch_season, yr, "Regular Season"): yr
                       for yr in [start_year, start_year - 1, start_year - 2]}

        # In playoffs, also fetch current season playoff logs
        po_future = None
        import datetime as _dt2
        _td2 = _dt2.date.today()
        _in_po = ((_td2.month == 4 and _td2.day >= 14) or _td2.month == 5 or
                  (_td2.month == 6 and _td2.day <= 25))
        if _in_po:
            po_future = ex.submit(_fetch_season, start_year, "Playoffs")

        for future in concurrent.futures.as_completed(reg_futures, timeout=25):
            try:
                df = future.result(timeout=15)
                if not df.empty:
                    all_rows.append(df)
            except Exception:
                pass

        # Get playoff results
        if po_future:
            try:
                po_df = po_future.result(timeout=15)
                if not po_df.empty:
                    all_rows.append(po_df)
            except Exception:
                pass

    if not all_rows:
        return empty

    combined = pd.concat(all_rows, ignore_index=True)
    combined["GAME_DATE"] = pd.to_datetime(combined["GAME_DATE"], errors="coerce")
    combined = combined.sort_values("GAME_DATE", ascending=False).reset_index(drop=True)
    # Deduplicate (in case any game appears in both regular + playoff fetch)
    combined = combined.drop_duplicates(subset=["GAME_DATE","PTS"]).reset_index(drop=True)
    return combined


def h2h_signal(h2h_df: pd.DataFrame, line: float, side: str) -> Tuple[str, Optional[float], int]:
    """
    Returns (signal, avg_pts, games_count).
    signal: 'Strong', 'Okay', or 'Risk'
    Requires 1+ game in playoffs, 2+ games in regular season.
    """
    if h2h_df is None or h2h_df.empty:
        return "Neutral", None, 0

    pts = pd.to_numeric(h2h_df["PTS"], errors="coerce").dropna()
    import datetime as _dtm_h2h
    _today_h = _dtm_h2h.date.today()
    _in_playoffs = ((_today_h.month == 4 and _today_h.day >= 14) or
                    _today_h.month == 5 or
                    (_today_h.month == 6 and _today_h.day <= 25))
    min_games = 1 if _in_playoffs else 2
    if len(pts) < min_games:
        return "Neutral", None, len(pts)

    avg = float(pts.mean())
    hit = float((pts > line).sum() / len(pts)) if side == "Over" else float((pts < line).sum() / len(pts))

    if hit >= 0.65 and avg > line:
        return "Strong", avg, len(pts)
    if hit <= 0.35 or avg < line - 3:
        return "Risk", avg, len(pts)
    return "Neutral", avg, len(pts)


def series_coverage_signal(
    logs: pd.DataFrame,
    opp_abbr: Optional[str],
    line: float,
    side: str,
    season_avg: Optional[float],
) -> Tuple[str, Optional[float], int]:
    """
    How has this specific defense guarded this player IN THIS SERIES?
    Returns (signal, this_series_avg, games_count).
    Only activates in playoffs — looks at games vs opp_abbr in last 30 days.

    signal:
      "Strong"   — player has outperformed season avg vs this defense
      "Risk"     — player has underperformed vs this defense
      "Neutral"  — performance in line or insufficient data
    """
    if not _IS_PLAYOFFS or not opp_abbr or logs is None or logs.empty:
        return "Neutral", None, 0
    if "MATCHUP" not in logs.columns or "GAME_DATE" not in logs.columns:
        return "Neutral", None, 0

    try:
        opp_up   = opp_abbr.upper()
        df       = logs.copy().reset_index(drop=True)
        df["GD"] = pd.to_datetime(df["GAME_DATE"], errors="coerce")
        today    = pd.Timestamp.now().normalize()
        # Filter to games vs this opponent — in playoffs use stricter date filter
        # Only count games from playoff start (April 14) to avoid regular season contamination
        mask = df["GD"].notna() & df["MATCHUP"].astype(str).str.upper().str.contains(opp_up, na=False)
        recent_opp = df[mask].copy()
        import datetime as _dtm3
        _td3 = _dtm3.date.today()
        _in_po3 = ((_td3.month == 4 and _td3.day >= 14) or _td3.month == 5 or
                   (_td3.month == 6 and _td3.day <= 25))
        if _in_po3:
            # Only this year's playoff games vs this opponent (after April 13)
            _playoff_start = pd.Timestamp("2026-04-14").normalize()
            recent_opp = recent_opp[recent_opp["GD"].dt.normalize() >= _playoff_start]
        else:
            recent_opp = recent_opp[(today - recent_opp["GD"].dt.normalize()).dt.days <= 30]
        if recent_opp.empty:
            return "Neutral", None, 0

        pts = pd.to_numeric(recent_opp["PTS"], errors="coerce").dropna()
        if len(pts) == 0:
            return "Neutral", None, 0

        series_avg = float(pts.mean())
        n = len(pts)

        # Compare to season avg if available, otherwise to line
        benchmark = season_avg if season_avg else line

        if side == "Over":
            if series_avg > benchmark + 2 and series_avg > line:
                return "Strong", series_avg, n
            if series_avg < benchmark - 2 or series_avg < line - 2:
                return "Risk", series_avg, n
        else:  # Under
            if series_avg < benchmark - 2 and series_avg < line:
                return "Strong", series_avg, n
            if series_avg > benchmark + 2 or series_avg > line + 2:
                return "Risk", series_avg, n
        return "Neutral", series_avg, n
    except Exception:
        return "Neutral", None, 0


# ── Back-to-back detection ────────────────────

def detect_b2b(logs: pd.DataFrame, game_date: Optional[str]) -> str:
    """
    Returns 'B2B' if tonight's game is the day after a logged game, else 'Normal'.
    Uses game_date (next game date string) + logs to check.
    """
    if game_date is None or logs is None or logs.empty:
        return "Normal"

    try:
        tonight   = pd.to_datetime(game_date)
        log_dates = pd.to_datetime(logs["GAME_DATE"], errors="coerce").dropna()
        yesterday = tonight - pd.Timedelta(days=1)
        if any(abs((d - yesterday).days) == 0 for d in log_dates):
            return "B2B"
        return "Normal"
    except Exception:
        return "Normal"


def detect_rest_days(logs: pd.DataFrame, game_date: Optional[str]) -> str:
    """
    Returns rest days signal based on days since last game.
    - 'B2B'      → 0 days rest (handled by detect_b2b)
    - 'Short'    → 1 day rest (played 2 days ago)
    - 'Normal'   → 2 days rest
    - 'Rested'   → 3+ days rest → small scoring boost

    Research shows players score ~2-3 pts more with 3+ days rest.
    """
    if game_date is None or logs is None or logs.empty:
        return "Normal"

    try:
        tonight   = pd.to_datetime(game_date)
        log_dates = pd.to_datetime(logs["GAME_DATE"], errors="coerce").dropna()
        if log_dates.empty:
            return "Normal"

        last_game  = log_dates.max()
        days_since = (tonight - last_game).days

        if days_since <= 1:
            return "B2B"      # handled by b2b signal
        elif days_since == 2:
            return "Short"    # 1 full day rest — slightly tired
        elif days_since == 3:
            return "Normal"   # 2 days rest — standard
        else:
            return "Rested"   # 3+ days rest — fresh legs
    except Exception:
        return "Normal"


def minutes_adjusted_scoring(
    avg_pts: float,
    season_avg_min: Optional[float],
    recent_avg_min: float,
    line: float,
    side: str,
) -> str:
    """
    Adjusts the matchup/role signal based on minutes restriction.

    If a player is playing significantly fewer minutes than their season average,
    their expected scoring should scale down proportionally.

    Returns an override signal: "Risk", "Okay", or None (no override needed).
    """
    if season_avg_min is None or season_avg_min < 10 or recent_avg_min < 5:
        return None

    minutes_ratio = recent_avg_min / season_avg_min

    # Significant restriction: playing ≥20% fewer minutes than season avg
    if minutes_ratio <= 0.80:
        # Scale expected points by minutes ratio
        expected_pts = avg_pts * minutes_ratio
        edge_with_restriction = expected_pts - line

        # If restriction pushes expected pts below line → Risk signal for Over
        if side == "Over" and edge_with_restriction < -1.0:
            return "Risk"
        # If restriction pushes expected pts well below line → boost Under
        elif side == "Under" and edge_with_restriction < -3.0:
            return "Strong"
    return None

def season_str_to_int(season_str: str) -> int:
    """Convert '2025-26' -> 2025 for ESPN year param."""
    try:
        return int(season_str.split("-")[0])
    except Exception:
        return 2025

# ── Season average fetch + divergence signal ─────────────────────

@st.cache_data(ttl=86400, show_spinner=False)
def nba_get_full_season_logs_cached(player_id: int, season: str, _date: str = None) -> Optional[pd.DataFrame]:
    """
    Fetch full season game log via direct REST API. Cached 24hrs.
    Used for season avg pts and avg min calculations.
    """
    _URL = "https://stats.nba.com/stats/playergamelog"
    _HEADERS = {
        "Host": "stats.nba.com",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
        "Accept": "application/json, text/plain, */*",
        "Accept-Language": "en-US,en;q=0.9",
        "Accept-Encoding": "gzip, deflate, br",
        "x-nba-stats-origin": "stats",
        "x-nba-stats-token": "true",
        "Referer": "https://www.nba.com/",
        "Origin": "https://www.nba.com",
        "Connection": "keep-alive",
    }
    import requests as _req
    for attempt in range(2):
        try:
            r = _req.get(_URL, headers=_HEADERS, params={
                "PlayerID": player_id,
                "Season": season,
                "SeasonType": "Regular Season",
                "LeagueID": "00",
            }, timeout=12)
            r.raise_for_status()
            data    = r.json()
            headers = data["resultSets"][0]["headers"]
            rows    = data["resultSets"][0]["rowSet"]
            if rows:
                return pd.DataFrame(rows, columns=headers)
        except Exception:
            if attempt == 0:
                time.sleep(1)
    return None


def nba_get_season_avg(player_id: int, season: str, logs_l10: pd.DataFrame = None) -> Optional[float]:
    """
    Get season avg pts. Uses cached full season log.
    Falls back to L10 sample if API is slow — still useful for form divergence.
    """
    # Fast path: use already-fetched L10 as approximation if full season unavailable
    df = nba_get_full_season_logs_cached(player_id, season)
    if df is not None:
        pts = pd.to_numeric(df["PTS"], errors="coerce").dropna()
        if len(pts) >= 5:
            return round(float(pts.mean()), 1)
    # Fallback to L10 sample
    if logs_l10 is not None and not logs_l10.empty:
        pts = pd.to_numeric(logs_l10["PTS"], errors="coerce").dropna()
        if len(pts) >= 3:
            return round(float(pts.mean()), 1)
    return None


def nba_get_season_avg_min(player_id: int, season: str, logs_l10: pd.DataFrame = None) -> Optional[float]:
    """
    Get season avg minutes. Uses cached full season log.
    Falls back to L10 sample if API is slow.
    """
    df = nba_get_full_season_logs_cached(player_id, season)
    if df is not None:
        mins = pd.to_numeric(df["MIN"], errors="coerce").dropna()
        if len(mins) >= 5:
            return round(float(mins.mean()), 1)
    # Fallback to L10 sample
    if logs_l10 is not None and not logs_l10.empty:
        mins = pd.to_numeric(logs_l10["MIN"], errors="coerce").dropna()
        if len(mins) >= 3:
            return round(float(mins.mean()), 1)
    return None


def minutes_restriction_alert(
    recent_avg_min: float,
    season_avg_min: Optional[float],
    last_3_mins: Optional[list],
) -> str:
    """
    Detect if a player's minutes have dropped significantly recently,
    which may indicate injury recovery, load management, or a role change.
    Returns an HTML alert string or empty string if no concern.
    """
    # In playoffs nobody rests — suppress load management warning
    if _IS_PLAYOFFS:
        return ""

    if season_avg_min is None or season_avg_min < 10:
        return ""

    # Check L3 average vs season average
    if last_3_mins and len(last_3_mins) >= 2:
        l3_avg = sum(last_3_mins) / len(last_3_mins)
        drop = season_avg_min - l3_avg

        if drop >= 7:
            severity = "significant"
            bg, border, color = "#1c1005", "#854d0e", "#f97316"
            icon = "⚠️"
        elif drop >= 4:
            severity = "moderate"
            bg, border, color = "#0c1018", "#243044", "#60a5fa"
            icon = "📉"
        else:
            return ""

        return (
            f"<div style='background:{bg};border:1px solid {border};border-radius:10px;"
            f"padding:0.65rem 1rem;margin-bottom:0.5rem;display:flex;align-items:center;gap:10px;'>"
            f"<span style='font-size:1.1rem;'>{icon}</span>"
            f"<div style='font-family:DM Mono;font-size:0.7rem;'>"
            f"<span style='color:{color};font-weight:800;text-transform:uppercase;letter-spacing:0.08em;'>"
            f"Minutes restriction detected</span>"
            f"<span style='color:#6b7f96;'> · L3 avg {l3_avg:.1f} min vs season avg {season_avg_min:.1f} min "
            f"({drop:+.1f}) — possible injury or load management</span>"
            f"</div>"
            f"</div>"
        )
    return ""


def form_divergence_signal(
    recent_avg: float,
    season_avg: Optional[float],
    line: float,
    side: str,
) -> Tuple[str, Optional[float]]:
    """
    Compare L5/L10 average to season average.
    Returns (signal, divergence_pts) where:
      'Hot'    — recent avg is 3+ pts above season avg (riding a hot streak)
      'Cold'   — recent avg is 3+ pts below season avg (in a slump)
      'Neutral' — within 3 pts either way
    The signal then interacts with the line direction:
      Hot + Over  = boost | Hot + Under = slight penalty
      Cold + Under = boost | Cold + Over = penalty
    We encode this as a single verdict-ready key.
    """
    if season_avg is None or season_avg == 0:
        return "Neutral", None

    diff = recent_avg - season_avg  # positive = running hot, negative = running cold

    if diff >= 3.0:
        streak = "Hot"
    elif diff <= -3.0:
        streak = "Cold"
    else:
        return "Neutral", round(diff, 1)

    # Align streak direction with bet side for final signal
    if streak == "Hot" and side == "Over":
        return "Boost", round(diff, 1)
    if streak == "Hot" and side == "Under":
        return "Penalty", round(diff, 1)
    if streak == "Cold" and side == "Under":
        return "Boost", round(diff, 1)
    if streak == "Cold" and side == "Over":
        return "Penalty", round(diff, 1)
    return "Neutral", round(diff, 1)


# ── Next game / schedule ──────────────────────

@st.cache_data(ttl=1800, show_spinner=False)
@st.cache_data(ttl=3600, show_spinner=False)
def espn_get_player_news(player_name: str) -> list:
    """
    Fetch latest news headlines for a player from ESPN.
    Returns list of {headline, description, date} dicts.
    No API key needed.
    """
    try:
        import requests as _req
        # Search ESPN for the player
        r = _req.get(
            "https://site.api.espn.com/apis/site/v2/sports/basketball/nba/news",
            params={"limit": 50},
            timeout=6
        )
        if not r.ok:
            return []
        articles = r.json().get("articles", [])
        # Filter for articles mentioning this player
        name_parts = player_name.lower().split()
        last_name  = name_parts[-1] if name_parts else ""
        first_name = name_parts[0]  if name_parts else ""
        results = []
        for a in articles:
            headline = a.get("headline", "")
            desc     = a.get("description", "") or a.get("summary", "")
            text     = (headline + " " + desc).lower()
            if last_name in text and (len(last_name) > 4 or first_name in text):
                # Parse date
                date_str = a.get("published", "")[:10]
                results.append({
                    "headline":    headline,
                    "description": desc,
                    "date":        date_str,
                    "link":        a.get("links", {}).get("web", {}).get("href", ""),
                })
            if len(results) >= 3:
                break
        return results
    except Exception:
        return []


@st.cache_data(ttl=3600, show_spinner=False)
def espn_get_player_role(player_name: str, team_abbr: str) -> dict:
    """
    Detect if a player is a starter or bench player.
    Strategy (in order):
    1. Tonight's game summary — confirmed starter if game is active/scheduled
    2. Last game boxscore — was he a starter last game?
    3. Depth chart position — where does ESPN rank him on the roster?

    Returns dict:
    {
        "role":      "Starter" | "Bench" | "Unknown",
        "source":    "tonight" | "last_game" | "depth_chart",
        "game_info": "vs NYK · Apr 20" or similar,
        "starter_confirmed": True/False,
        "depth_pos": 1-5 = starter, 6+ = bench
    }
    """
    empty = {"role": "Unknown", "source": None, "game_info": "", "starter_confirmed": False, "depth_pos": None}
    if not player_name or not team_abbr:
        return empty

    # ── Known franchise starters — always override API data ───────────────
    # These players are categorically starters regardless of what the API returns
    _KNOWN_STARTERS = {
        # All-Stars / franchise players who never come off the bench
        "nikola jokic", "lebron james", "stephen curry", "kevin durant",
        "giannis antetokounmpo", "luka doncic", "jayson tatum", "jaylen brown",
        "tyrese haliburton", "shai gilgeous-alexander", "donovan mitchell",
        "devin booker", "anthony davis", "kawhi leonard", "paul george",
        "damian lillard", "joel embiid", "james harden", "trae young",
        "zion williamson", "ja morant", "bam adebayo", "pascal siakam",
        "darius garland", "evan mobley", "jarrett allen", "jalen brunson",
        "karl-anthony towns", "julius randle", "anthony edwards",
        "rudy gobert", "mike conley", "andrew wiggins", "klay thompson",
        "draymond green", "chris paul", "demar derozan", "zach lavine",
        "lauri markkanen", "walker kessler", "collin sexton", "victor wembanyama",
        "chet holmgren", "jalen williams", "luguentz dort", "scottie barnes",
        "RJ barrett", "immanuel quickley", "josh hart", "og anunoby",
    }
    _norm_check = player_name.lower().strip()
    if any(_norm_check == s or _norm_check.split()[-1] == s.split()[-1]
           and _norm_check.split()[0][0] == s.split()[0][0]
           for s in _KNOWN_STARTERS):
        return {"role": "Starter", "source": "known_starter",
                "game_info": "", "starter_confirmed": True, "depth_pos": 1}

    try:
        import pytz, requests as _req
        et    = pytz.timezone("America/New_York")
        today = datetime.now(et).date()
        _HDRS = {"User-Agent": "Mozilla/5.0"}

        # ── Step 1: Find ESPN team ID ─────────────────────────
        _ESPN_TEAM_IDS = {
            "ATL":1,"BOS":2,"BKN":17,"CHA":30,"CHI":4,"CLE":5,"DAL":6,
            "DEN":7,"DET":8,"GSW":9,"HOU":10,"IND":11,"LAC":12,"LAL":13,
            "MEM":29,"MIA":14,"MIL":15,"MIN":16,"NOP":3,"NYK":18,"OKC":25,
            "ORL":19,"PHI":20,"PHX":21,"POR":22,"SAC":23,"SAS":24,"TOR":28,
            "UTA":26,"WAS":27,
        }
        team_id = _ESPN_TEAM_IDS.get(team_abbr.upper())
        if not team_id:
            return empty

        # Normalize player name for matching
        def _norm(n): return n.lower().strip()
        pname_norm = _norm(player_name)
        pparts     = pname_norm.split()
        plast      = pparts[-1] if pparts else ""
        pfirst     = pparts[0]  if pparts else ""

        def _name_matches(n):
            n = _norm(n)
            return (pname_norm in n or n in pname_norm or
                    (plast in n and pfirst in n) or
                    (plast in n and len(plast) > 4))

        # ── Step 2: Tonight's game / last game via scoreboard ─
        for offset in range(0, 5):  # check today + next 4 days for tonight's game
            check    = today + timedelta(days=offset) if offset <= 1 else today - timedelta(days=offset-1)
            date_str = check.strftime("%Y%m%d")
            try:
                sb   = espn_get(f"{ESPN_SITE}/scoreboard", params={"dates": date_str})
                evts = sb.get("events", [])
                for ev in evts:
                    comp   = ev.get("competitions", [{}])[0]
                    comps  = comp.get("competitors", [])
                    status = ev.get("status", {}).get("type", {}).get("name", "")

                    # Find the team in this game
                    my_comp = next(
                        (c for c in comps
                         if _norm_team_abbr(c.get("team",{}).get("abbreviation","")) == team_abbr.upper()),
                        None
                    )
                    if not my_comp:
                        continue

                    opp_comp   = next((c for c in comps if c != my_comp), {})
                    opp_name   = opp_comp.get("team", {}).get("abbreviation", "")
                    game_label = f"vs {opp_name} · {check.strftime('%b %d')}"
                    is_tonight = (offset == 0)
                    is_final   = "final" in status.lower() or "complete" in status.lower()
                    is_active  = "in" in status.lower() or "progress" in status.lower()

                    # Get lineup from this game's roster
                    lineup = my_comp.get("roster", []) or []

                    # If no roster in scoreboard, try the game summary
                    if not lineup:
                        evt_id = ev.get("id", "")
                        if evt_id:
                            try:
                                summary = _req.get(
                                    f"https://site.web.api.espn.com/apis/site/v2/sports/basketball/nba/summary",
                                    params={"event": evt_id},
                                    headers=_HDRS, timeout=6
                                ).json()
                                for team_data in summary.get("boxscore", {}).get("players", []):
                                    ta = team_data.get("team", {}).get("abbreviation", "")
                                    if _norm_team_abbr(ta) != team_abbr.upper():
                                        continue
                                    for pg in team_data.get("statistics", []):
                                        for athlete in pg.get("athletes", []):
                                            aname   = athlete.get("athlete", {}).get("displayName", "")
                                            started = athlete.get("starter", False)
                                            dnp     = athlete.get("didNotPlay", False)
                                            if _name_matches(aname):
                                                src = "tonight" if is_tonight else "last_game"
                                                role = "Starter" if started else ("Bench" if not dnp else "DNP")
                                                return {
                                                    "role":              role,
                                                    "source":            src,
                                                    "game_info":         game_label,
                                                    "starter_confirmed": True,
                                                    "depth_pos":         1 if started else 6,
                                                }
                            except Exception:
                                pass

                    # Check roster in scoreboard itself
                    for p in lineup:
                        aname   = p.get("athlete", {}).get("displayName", "")
                        started = p.get("starter", False)
                        if _name_matches(aname):
                            src  = "tonight" if is_tonight else "last_game"
                            role = "Starter" if started else "Bench"
                            return {
                                "role":              role,
                                "source":            src,
                                "game_info":         game_label,
                                "starter_confirmed": is_final or is_active,
                                "depth_pos":         1 if started else 6,
                            }
            except Exception:
                continue

        # ── Step 3: Depth chart fallback ──────────────────────
        try:
            dc   = espn_get(f"{ESPN_SITE}/teams/{team_id}/depthcharts")
            pos_groups = dc.get("positionGroups", []) or dc.get("items", [])
            pos_rank = 99
            for grp in pos_groups:
                for pos in grp.get("positions", {}).values() if isinstance(grp.get("positions"), dict) else []:
                    athletes = pos.get("athletes", [])
                    for rank, ath in enumerate(athletes, start=1):
                        aname = ath.get("athlete", {}).get("displayName", "")
                        if _name_matches(aname):
                            pos_rank = rank
                            break
            if pos_rank <= 5:
                return {"role": "Starter", "source": "depth_chart", "game_info": "",
                        "starter_confirmed": False, "depth_pos": pos_rank}
            elif pos_rank <= 99:
                return {"role": "Bench", "source": "depth_chart", "game_info": "",
                        "starter_confirmed": False, "depth_pos": pos_rank}
        except Exception:
            pass

    except Exception:
        pass

    return empty


@st.cache_data(ttl=900, show_spinner=False)
def espn_get_last_game_date(team_abbr: str) -> Optional[str]:
    """
    Returns the date of the team's most recent completed game from ESPN.
    Much more reliable than game logs for rest detection — updates immediately.
    Returns date string 'YYYY-MM-DD' or None.
    """
    if not team_abbr:
        return None
    try:
        import pytz
        et    = pytz.timezone("America/New_York")
        today = datetime.now(et).date()
    except Exception:
        today = datetime.today().date()

    _ESPN_REVERSE = {
        "GSW":"GS","SAS":"SA","NYK":"NY","NOP":"NO",
        "UTA":"UTAH","PHX":"PHX","MEM":"MEM","OKC":"OKC",
    }
    _candidates = {team_abbr, _ESPN_REVERSE.get(team_abbr, team_abbr)}

    def _team_matches(abbr: str) -> bool:
        return abbr == team_abbr or _norm_team_abbr(abbr) == team_abbr or abbr in _candidates

    # Look back up to 10 days for most recent completed game
    for offset in range(1, 11):
        check    = today - timedelta(days=offset)
        date_str = check.strftime("%Y%m%d")
        try:
            data   = espn_get(f"{ESPN_SITE}/scoreboard", params={"dates": date_str})
            events = data.get("events", [])
            for ev in events:
                status = ev.get("status", {}).get("type", {}).get("name", "")
                if "final" not in status.lower() and "complete" not in status.lower():
                    continue
                comps       = ev.get("competitions", [{}])[0]
                competitors = comps.get("competitors", [])
                my_comp = next(
                    (c for c in competitors
                     if _team_matches(c.get("team", {}).get("abbreviation", ""))),
                    None
                )
                if my_comp:
                    return check.strftime("%Y-%m-%d")
        except Exception:
            continue
    return None


def espn_get_next_game(team_abbr: str) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    """
    Find next upcoming game for a team using ESPN scoreboard.
    Returns (opp_abbr, game_date_str, venue).
    Skips completed games. Handles ESPN abbreviation mismatches.
    """
    if not team_abbr:
        return None, None, None

    try:
        import pytz
        et    = pytz.timezone("America/New_York")
        today = datetime.now(et).date()
    except Exception:
        today = datetime.today().date()

    # ESPN uses different abbreviations — build reverse lookup
    # so GSW→GS, SAS→SA, NYK→NY, etc.
    _ESPN_REVERSE = {
        "GSW": "GS", "SAS": "SA", "NYK": "NY", "NOP": "NO",
        "UTA": "UTAH", "PHX": "PHX", "MEM": "MEM", "OKC": "OKC",
    }
    # Candidates to match against — try normalized and ESPN variants
    _candidates = {team_abbr, _ESPN_REVERSE.get(team_abbr, team_abbr)}

    def _team_matches(abbr: str) -> bool:
        return (abbr == team_abbr or
                _norm_team_abbr(abbr) == team_abbr or
                abbr in _candidates)

    for offset in range(10):
        check    = today + timedelta(days=offset)
        date_str = check.strftime("%Y%m%d")
        try:
            data   = espn_get(f"{ESPN_SITE}/scoreboard", params={"dates": date_str})
            events = data.get("events", [])
            for ev in events:
                comps       = ev.get("competitions", [{}])[0]
                competitors = comps.get("competitors", [])

                # Skip if final/completed
                status = ev.get("status", {}).get("type", {}).get("name", "")
                if "final" in status.lower() or "complete" in status.lower():
                    continue

                # Find our team using fuzzy abbreviation match
                my_comp = next(
                    (c for c in competitors
                     if _team_matches(c.get("team", {}).get("abbreviation", ""))),
                    None
                )
                if not my_comp:
                    continue

                # Find opponent
                opp_comp = next(
                    (c for c in competitors if c is not my_comp), None
                )
                if not opp_comp:
                    continue

                opp_abbr_raw   = opp_comp.get("team", {}).get("abbreviation", "")
                opp_abbr_found = _norm_team_abbr(opp_abbr_raw)
                home_away      = "Home" if my_comp.get("homeAway", "") == "home" else "Away"
                game_date_str  = check.strftime("%b %d, %Y")

                return opp_abbr_found, game_date_str, home_away
        except Exception:
            continue

    return None, None, None

# ── Opponent defense rating ───────────────────

@st.cache_data(ttl=21600, show_spinner=False)
def espn_get_opp_pts_allowed(opp_abbr: str, _date: str = None) -> Optional[float]:
    """
    Calculate pts allowed per game. Tries NBA Stats API first (most reliable),
    falls back to ESPN scoreboard scrape.
    """
    # Method 1: NBA Stats leaguedashteamstats — direct pts allowed
    _NBA_ABBR_TO_ID = {
        "ATL":1610612737,"BOS":1610612738,"BKN":1610612751,"CHA":1610612766,
        "CHI":1610612741,"CLE":1610612739,"DAL":1610612742,"DEN":1610612743,
        "DET":1610612765,"GSW":1610612744,"HOU":1610612745,"IND":1610612754,
        "LAC":1610612746,"LAL":1610612747,"MEM":1610612763,"MIA":1610612748,
        "MIL":1610612749,"MIN":1610612750,"NOP":1610612740,"NYK":1610612752,
        "OKC":1610612760,"ORL":1610612753,"PHI":1610612755,"PHX":1610612756,
        "POR":1610612757,"SAC":1610612758,"SAS":1610612759,"TOR":1610612761,
        "UTA":1610612762,"WAS":1610612764,
    }
    try:
        import requests as _req
        _hdrs = {"User-Agent":"Mozilla/5.0","Referer":"https://www.nba.com/",
                 "x-nba-stats-origin":"stats","x-nba-stats-token":"true","Accept":"application/json"}
        r = _req.get(
            "https://stats.nba.com/stats/leaguedashteamstats",
            params={"Season":"2025-26",
                    "SeasonType":"Playoffs" if _IS_PLAYOFFS else "Regular Season",
                    "PerMode":"PerGame","MeasureType":"Base","LeagueID":"00"},
            headers=_hdrs, timeout=8
        )
        if r.ok:
            rs = r.json().get("resultSets",[{}])[0]
            hs = rs.get("headers",[])
            rows = rs.get("rowSet",[])
            if hs and rows:
                abbr_i = hs.index("TEAM_ABBREVIATION") if "TEAM_ABBREVIATION" in hs else -1
                opp_i  = hs.index("OPP_PTS") if "OPP_PTS" in hs else -1
                if abbr_i >= 0 and opp_i >= 0:
                    for row in rows:
                        if str(row[abbr_i]).upper() == opp_abbr.upper():
                            val = float(row[opp_i])
                            if val > 80:
                                return round(val, 1)
    except Exception:
        pass
    # Method 2: ESPN scoreboard scrape (original method)
    try:
        import pytz
        et    = pytz.timezone("America/New_York")
        today = datetime.now(et).date()
    except Exception:
        today = datetime.today().date()

    try:
        pts_allowed_list = []
        _opp_norm = _norm_team_abbr(opp_abbr)
        _ESPN_REVERSE = {
            "GSW":"GS", "SAS":"SA", "NYK":"NY", "NOP":"NO", "WAS":"WSH",
            "BKN":"BK", "UTA":"UTAH",
        }
        _candidates = {_opp_norm, opp_abbr.upper(), _ESPN_REVERSE.get(_opp_norm, _opp_norm)}

        def _team_matches(_abbr: str) -> bool:
            _a = str(_abbr or "").upper()
            return _a in _candidates or _norm_team_abbr(_a) == _opp_norm

        # Look back up to 30 days to find 15 completed games
        for offset in range(1, 35):
            if len(pts_allowed_list) >= 15:
                break
            check    = today - timedelta(days=offset)
            date_str = check.strftime("%Y%m%d")
            try:
                data   = espn_get(f"{ESPN_SITE}/scoreboard", params={"dates": date_str})
                events = data.get("events", [])
                for ev in events:
                    comp        = ev.get("competitions", [{}])[0]
                    competitors = comp.get("competitors", [])
                    # Find this team
                    team_comp = next(
                        (c for c in competitors
                         if _team_matches(c.get("team", {}).get("abbreviation", ""))),
                        None
                    )
                    if not team_comp:
                        continue
                    # Only completed games
                    status = ev.get("status", {}).get("type", {}).get("name", "")
                    if "final" not in status.lower() and "complete" not in status.lower():
                        continue
                    # Opponent score = the other team's score
                    opp_comp = next(
                        (c for c in competitors
                         if not _team_matches(c.get("team", {}).get("abbreviation", ""))),
                        None
                    )
                    if opp_comp:
                        score = opp_comp.get("score", "")
                        try:
                            pts_allowed_list.append(float(score))
                        except Exception:
                            continue
            except Exception:
                continue

        if len(pts_allowed_list) >= 5:
            return round(sum(pts_allowed_list) / len(pts_allowed_list), 1)
        return None
    except Exception:
        return None

@st.cache_data(ttl=3600, show_spinner=False)
def get_opp_recent_defensive_form(opp_abbr: str) -> dict:
    """
    Compare opponent's last 5 games pts allowed vs their L15 season avg.
    Returns dict with:
      - recent_avg: pts allowed in last 5 games
      - season_avg: pts allowed in last 15 games
      - trend: "Tightening" | "Neutral" | "Softening"
      - diff: recent_avg - season_avg (positive = allowing more = worse defense)
    """
    empty = {"recent_avg": None, "season_avg": None, "trend": "Neutral", "diff": 0}
    if not opp_abbr:
        return empty
    try:
        import pytz
        et    = pytz.timezone("America/New_York")
        today = datetime.now(et).date()

        pts_by_game = []   # (date, pts_allowed) newest first
        for offset in range(1, 40):
            if len(pts_by_game) >= 15:
                break
            check    = today - timedelta(days=offset)
            date_str = check.strftime("%Y%m%d")
            try:
                data   = espn_get(f"{ESPN_SITE}/scoreboard", params={"dates": date_str})
                events = data.get("events", [])
                for ev in events:
                    comp        = ev.get("competitions", [{}])[0]
                    competitors = comp.get("competitors", [])
                    team_comp   = next(
                        (c for c in competitors
                         if c.get("team", {}).get("abbreviation", "") == opp_abbr),
                        None
                    )
                    if not team_comp:
                        continue
                    status = ev.get("status", {}).get("type", {}).get("name", "")
                    if "final" not in status.lower() and "complete" not in status.lower():
                        continue
                    opp_comp = next(
                        (c for c in competitors
                         if c.get("team", {}).get("abbreviation", "") != opp_abbr),
                        None
                    )
                    if opp_comp:
                        try:
                            pts_by_game.append(float(opp_comp.get("score", 0)))
                        except Exception:
                            pass
            except Exception:
                continue

        if len(pts_by_game) < 5:
            return empty

        recent_5  = pts_by_game[:5]
        season_15 = pts_by_game[:15]
        recent_avg = sum(recent_5) / len(recent_5)
        season_avg = sum(season_15) / len(season_15)
        diff = recent_avg - season_avg

        # Tightening = allowing fewer pts recently = better defense
        # Softening  = allowing more pts recently = worse defense
        if diff <= -3.0:
            trend = "Tightening"   # defense locking in — harder to score
        elif diff >= 3.0:
            trend = "Softening"    # defense breaking down — easier to score
        else:
            trend = "Neutral"

        return {
            "recent_avg": round(recent_avg, 1),
            "season_avg": round(season_avg, 1),
            "trend":      trend,
            "diff":       round(diff, 1),
        }
    except Exception:
        return empty


# ── Game number in series adjustment ────────────────────────────────
def get_series_game_number(series_wins: int, series_losses: int) -> int:
    """Returns the current game number in the series (1-7)."""
    return series_wins + series_losses + 1

def game_number_adjustment(game_num: int, side: str) -> Tuple[str, float]:
    """
    Apply scoring adjustment based on game number in playoff series.
    Returns (label, adjustment) where adjustment is additive pp.

    Game 1: conservative, feeling-out period → lower scoring
    Games 2-5: normal playoff intensity
    Game 6-7: pressure reduces scoring, starters may be fatigued
    """
    if not _IS_PLAYOFFS:
        return "N/A", 0.0

    _flip = 1.0 if side == "Over" else -1.0

    if game_num == 1:
        return "Game 1 (feeling out)", -0.03 * _flip
    elif game_num in (2, 3, 4, 5):
        return f"Game {game_num} (normal)", 0.0
    elif game_num == 6:
        return "Game 6 (pressure)", -0.02 * _flip
    elif game_num >= 7:
        return "Game 7 (max pressure)", -0.03 * _flip
    return "Normal", 0.0


# ── Playoff usage spike detector ────────────────────────────────────
@st.cache_data(ttl=3600, show_spinner=False)
def get_playoff_game_logs(player_id: int, season: str) -> pd.DataFrame:
    """
    Fetch playoff game logs for a player.
    Uses NBA Stats API with SeasonType=Playoffs.
    """
    _URL = "https://stats.nba.com/stats/playergamelog"
    _HEADERS = {
        "Host": "stats.nba.com",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
        "Accept": "application/json, text/plain, */*",
        "x-nba-stats-origin": "stats",
        "x-nba-stats-token": "true",
        "Referer": "https://www.nba.com/",
        "Origin": "https://www.nba.com",
    }
    try:
        import requests as _req
        r = _req.get(_URL, headers=_HEADERS, params={
            "PlayerID":   player_id,
            "Season":     season,
            "SeasonType": "Playoffs",
            "LeagueID":   "00",
        }, timeout=10)
        if not r.ok:
            return pd.DataFrame()
        rs = r.json().get("resultSets", [{}])[0]
        headers = rs.get("headers", [])
        rows    = rs.get("rowSet", [])
        if not rows:
            return pd.DataFrame()
        return pd.DataFrame(rows, columns=headers)
    except Exception:
        return pd.DataFrame()


def playoff_usage_spike_signal(
    player_id: int,
    season: str,
    reg_avg_pts: float,
    reg_avg_min: float,
    line: float,
    side: str,
) -> Tuple[str, Optional[float], Optional[float]]:
    """
    Compare player's current playoff stats (this postseason) vs regular season.
    Returns (signal, playoff_avg_pts, playoff_avg_min).

    signal:
      "Spike"   — scoring/minutes significantly up in playoffs → boost Over
      "Drop"    — scoring/minutes down in playoffs → penalize Over
      "Neutral" — consistent with regular season
    """
    if not _IS_PLAYOFFS:
        return "Neutral", None, None

    try:
        logs = get_playoff_game_logs(player_id, season)
        if logs.empty or "PTS" not in logs.columns:
            return "Neutral", None, None

        pts = pd.to_numeric(logs["PTS"], errors="coerce").dropna()
        mins = pd.to_numeric(logs["MIN"], errors="coerce").dropna()

        if len(pts) < 2:
            return "Neutral", None, None

        playoff_avg_pts = float(pts.mean())
        playoff_avg_min = float(mins.mean()) if len(mins) >= 2 else None

        pts_diff = playoff_avg_pts - reg_avg_pts
        min_diff = (playoff_avg_min - reg_avg_min) if playoff_avg_min and reg_avg_min else 0

        _flip = 1.0 if side == "Over" else -1.0

        # Spike: scoring AND minutes both up significantly
        if pts_diff >= 3.0 and min_diff >= 2.0:
            return "Spike", playoff_avg_pts, playoff_avg_min
        # Partial spike: just scoring up (usage increase, not minutes)
        if pts_diff >= 3.0:
            return "Spike", playoff_avg_pts, playoff_avg_min
        # Drop: scoring down — coach tightened rotation or player struggling
        if pts_diff <= -3.0:
            return "Drop", playoff_avg_pts, playoff_avg_min

        return "Neutral", playoff_avg_pts, playoff_avg_min
    except Exception:
        return "Neutral", None, None


# ── Supabase ──────────────────────────────────────────────────

def get_config_value(*names: str) -> str:
    """Read config from Railway/env first, then Streamlit secrets if available."""
    for name in names:
        val = os.environ.get(name, "")
        if val:
            return str(val).strip()
    for name in names:
        try:
            val = st.secrets.get(name, "")
            if val:
                return str(val).strip()
        except Exception:
            continue
    return ""


def get_supabase_client():
    """Get Supabase client using credentials from Railway env vars or Streamlit secrets."""
    try:
        url = get_config_value(
            "SUPABASE_URL",
            "SUPABASE_PROJECT_URL",
            "NEXT_PUBLIC_SUPABASE_URL",
        )
        key = get_config_value(
            "SUPABASE_SERVICE_ROLE_KEY",
            "SUPABASE_SERVICE_KEY",
            "SUPABASE_KEY",
            "SUPABASE_ANON_KEY",
            "NEXT_PUBLIC_SUPABASE_ANON_KEY",
        )
        if not url or not key:
            env_seen = [name for name in [
                "SUPABASE_URL", "SUPABASE_PROJECT_URL", "NEXT_PUBLIC_SUPABASE_URL",
                "SUPABASE_SERVICE_ROLE_KEY", "SUPABASE_SERVICE_KEY", "SUPABASE_KEY",
                "SUPABASE_ANON_KEY", "NEXT_PUBLIC_SUPABASE_ANON_KEY",
            ] if os.environ.get(name)]
            record_debug_error(
                "supabase.config",
                f"Missing Supabase URL/key. Env vars detected: {', '.join(env_seen) or 'none'}"
            )
            return None
        import requests as _req

        class _SupabaseClient:
            def __init__(self, url, key):
                self.url  = url.rstrip("/")
                self.key  = key
                self.hdrs = {
                    "apikey":        key,
                    "Authorization": f"Bearer {key}",
                    "Content-Type":  "application/json",
                    "Prefer":        "return=representation",
                }

            def select(self, table, filters=None):
                url = f"{self.url}/rest/v1/{table}?order=created_at.desc"
                if filters:
                    for k, v in filters.items():
                        url += f"&{k}=eq.{v}"
                r = _req.get(url, headers=self.hdrs, timeout=10)
                return r.json() if r.ok else []

            def insert(self, table, data):
                r = _req.post(
                    f"{self.url}/rest/v1/{table}",
                    headers=self.hdrs, json=data, timeout=10
                )
                return r.json() if r.ok else None

            def update(self, table, row_id, data):
                r = _req.patch(
                    f"{self.url}/rest/v1/{table}?id=eq.{row_id}",
                    headers=self.hdrs, json=data, timeout=10
                )
                return r.ok

            def delete(self, table, row_id):
                r = _req.delete(
                    f"{self.url}/rest/v1/{table}?id=eq.{row_id}",
                    headers=self.hdrs, timeout=10
                )
                return r.ok

            def delete_all(self, table, session_id):
                r = _req.delete(
                    f"{self.url}/rest/v1/{table}?session_id=eq.{session_id}",
                    headers=self.hdrs, timeout=10
                )
                return r.ok

        return _SupabaseClient(url, key)
    except Exception:
        return None


def get_cached_logs_from_supabase(player_id: int, season: str) -> Optional[pd.DataFrame]:
    """Check Supabase for today's already-fetched game logs. Returns df or None."""
    try:
        sb = get_supabase_client()
        if not sb:
            return None
        import requests as _req, json as _json
        hdrs = {
            "apikey":        sb.key,
            "Authorization": f"Bearer {sb.key}",
            "Content-Type":  "application/json",
        }
        url = (f"{sb.url}/rest/v1/game_logs_cache"
               f"?player_id=eq.{player_id}"
               f"&season=eq.{season}"
               f"&fetch_date=eq.{_cache_date()}"
               f"&select=logs_json"
               f"&limit=1")
        r = _req.get(url, headers=hdrs, timeout=5)
        if not r.ok:
            return None
        rows = r.json()
        if not rows:
            return None
        data = _json.loads(rows[0]["logs_json"])
        df = pd.DataFrame(data)
        df["GAME_DATE"] = pd.to_datetime(df["GAME_DATE"])
        return df
    except Exception:
        return None


def save_logs_to_supabase(player_id: int, season: str, df: pd.DataFrame) -> bool:
    """Save today's game logs to Supabase. Uses upsert to avoid duplicates."""
    try:
        sb = get_supabase_client()
        if not sb:
            return False
        import requests as _req
        hdrs = {
            "apikey":        sb.key,
            "Authorization": f"Bearer {sb.key}",
            "Content-Type":  "application/json",
            "Prefer":        "resolution=merge-duplicates,return=minimal",
        }
        logs_json = df.to_json(orient="records", date_format="iso")
        r = _req.post(
            f"{sb.url}/rest/v1/game_logs_cache",
            headers=hdrs,
            json={
                "player_id":  player_id,
                "season":     season,
                "fetch_date": _cache_date(),
                "logs_json":  logs_json,
            },
            timeout=6,
        )
        return r.ok
    except Exception:
        return False


def _tracker_metadata_value(entry: dict, field: str) -> str:
    """Read tracker context from a direct field or its durable venue marker."""
    direct = str(entry.get(field, "") or "").strip()
    if direct:
        return direct
    token = {
        "Sport": "sport", "Game Date": "date", "Event ID": "event",
        "Player ID": "player_id", "Team": "team",
    }.get(field)
    if not token:
        return ""
    match = re.search(
        rf"(?:^|[·|])\s*{re.escape(token)}\s*:\s*([^·|]+)",
        str(entry.get("Venue", entry.get("venue", "")) or ""),
        flags=re.IGNORECASE,
    )
    return match.group(1).strip() if match else ""


def _tracker_sport(entry: dict) -> str:
    """Recover a persisted tracker sport without guessing shared WNBA/NBA props."""
    sport = _tracker_metadata_value(entry, "Sport").upper()
    if sport in ("MLB", "WNBA", "NBA"):
        return sport
    matchup = str(entry.get("Matchup", entry.get("matchup", "")) or "")
    return "MLB" if matchup in ("Strikeouts", "Hitter Fantasy Score") else "NBA"


def _tracker_durable_venue(entry: dict) -> str:
    """Encode fields absent from the legacy prop_tracker schema into venue."""
    venue = str(entry.get("Venue", "") or "").strip()
    metadata = []
    for field, token in (
        ("Sport", "sport"), ("Game Date", "date"), ("Event ID", "event"),
        ("Player ID", "player_id"), ("Team", "team"),
    ):
        value = str(entry.get(field, "") or "").strip()
        if value and not re.search(
            rf"(?:^|[·|])\s*{re.escape(token)}\s*:", venue,
            flags=re.IGNORECASE,
        ):
            metadata.append(f"{token}:{value}")
    return " · ".join(metadata + ([venue] if venue else []))


def load_tracker_from_supabase(session_id: str) -> list:
    """Load tracker entries for this session from Supabase."""
    try:
        sb = get_supabase_client()
        if not sb:
            return []
        rows = sb.select("prop_tracker", {"session_id": session_id})
        if not rows or not isinstance(rows, list):
            return []
        entries = []
        for r in rows:
            matchup = r.get("matchup", "")
            persisted = {
                "id":          r.get("id"),
                "Player":      r.get("player", ""),
                "Line":        r.get("line", ""),
                "Opponent":    r.get("opponent", "—"),
                "Matchup":     matchup,
                "Venue":       r.get("venue", ""),
                "Avg PTS":     r.get("avg_pts", 0),
                "Hit Rate":    r.get("hit_rate", ""),
                "Adjusted":    r.get("adjusted", ""),
                "Consistency": r.get("consistency", ""),
                "Verdict":     r.get("verdict", ""),
                "Result":      r.get("result", "Pending"),
            }
            persisted["Sport"] = _tracker_sport(persisted)
            for field in ("Game Date", "Event ID", "Player ID", "Team"):
                value = _tracker_metadata_value(persisted, field)
                if value:
                    persisted[field] = value
            entries.append(persisted)
        return entries
    except Exception:
        return []


def save_to_supabase(session_id: str, entry: dict) -> str:
    """Save a tracker entry to Supabase. Returns the new row id."""
    try:
        sb = get_supabase_client()
        if not sb:
            return None
        row = {
            "session_id":  session_id,
            "player":      entry.get("Player", ""),
            "line":        entry.get("Line", ""),
            "opponent":    entry.get("Opponent", "—"),
            "matchup":     entry.get("Matchup", ""),
            "venue":       _tracker_durable_venue(entry),
            "avg_pts":     float(entry.get("Avg PTS", 0)),
            "hit_rate":    entry.get("Hit Rate", ""),
            "adjusted":    entry.get("Adjusted", ""),
            "consistency": entry.get("Consistency", ""),
            "verdict":     entry.get("Verdict", ""),
            "result":      entry.get("Result", "Pending"),
        }
        result = sb.insert("prop_tracker", row)
        if result and isinstance(result, list) and len(result) > 0:
            return result[0].get("id")
        return None
    except Exception:
        return None


def update_result_in_supabase(row_id: str, result: str) -> bool:
    """Update the result (Hit/Miss/Pending) of a tracker entry."""
    try:
        sb = get_supabase_client()
        if not sb:
            return False
        return sb.update("prop_tracker", row_id, {"result": result})
    except Exception:
        return False


def delete_from_supabase(row_id: str) -> bool:
    """Delete a tracker entry from Supabase."""
    try:
        sb = get_supabase_client()
        if not sb:
            return False
        return sb.delete("prop_tracker", row_id)
    except Exception:
        return False


# ── PrizePicks slate cache ───────────────────────────────────

PP_FRESH_SLATE_MINUTES = 5
PP_VERIFY_LINE_AFTER_MINUTES = 15
PP_LINE_SELECTION_VERSION = 4
PP_CACHE_MIN_LINE_SELECTION_VERSION = 4


def pp_event_key(row: dict) -> str:
    """Stable event identity for slate dedupe and line-history isolation."""
    row = row or {}
    game_id = str(row.get("game_id", "") or "").strip()
    if game_id:
        return f"game:{game_id}"
    start = pd.to_datetime(row.get("start_time"), utc=True, errors="coerce")
    if pd.notna(start):
        return f"start:{start.isoformat()}"
    return ""


def entry_event_key(row: dict) -> str:
    """Best available event identity for entry-correlation checks."""
    row = row or {}
    for field in ("game_id", "game_pk", "event_id"):
        value = str(row.get(field, "") or "").strip()
        if value:
            return f"{field}:{value}"

    start = pd.to_datetime(
        row.get("game_datetime") or row.get("start_time"),
        utc=True,
        errors="coerce",
    )
    if pd.notna(start):
        return f"start:{start.isoformat()}"

    game_date = str(row.get("game_date") or row.get("pp_game_date") or "")[:10]
    team = str(
        row.get("pp_team") or row.get("pitcher_team")
        or row.get("player_team") or row.get("team") or ""
    ).strip().upper()
    opponent = str(row.get("opp") or row.get("opponent") or "").strip().upper()
    teams = sorted(value for value in (team, opponent) if value and value not in ("TBD", "—"))
    if game_date and len(teams) == 2:
        return f"date:{game_date}|{'-'.join(teams)}"
    return ""


def conservative_entry_leg_probability(row: dict) -> dict:
    """Shrink a leg's calibrated probability according to evidence quality."""
    row = row or {}
    probability = _parse_numeric_value(row.get("adj"), None)
    if probability is None:
        probability = _parse_numeric_value(row.get("probability"), 50.0)
    probability = float(probability or 50.0)
    if probability <= 1.0:
        probability *= 100.0
    raw = max(0.01, min(0.99, probability / 100.0))

    confidence = _parse_numeric_value(row.get("confidence"), 60.0)
    reliability = _parse_numeric_value(row.get("reliability"), confidence)
    confidence = max(0.0, min(100.0, float(confidence or 0.0)))
    reliability = max(0.0, min(100.0, float(reliability or confidence)))
    evidence = min(confidence, reliability) / 100.0

    # The underlying prop probability is already calibrated. This is a small,
    # explicit entry-level haircut for incomplete evidence, not a second model.
    evidence_factor = 0.88 + (0.12 * evidence)
    reasons = []
    action = str(row.get("entry_action") or row.get("action") or "").upper()
    verdict = str(row.get("verdict") or row.get("tier") or "")
    if action == "WATCH" or "Lean" in verdict:
        evidence_factor *= 0.975
        reasons.append("watch-level leg")
    if row.get("line_verification_required"):
        evidence_factor *= 0.94
        reasons.append("line needs verification")
    if is_reduced_payout_line(row):
        evidence_factor *= 0.96
        reasons.append("reduced-payout line")

    conservative = 0.50 + ((raw - 0.50) * evidence_factor)
    conservative = max(0.01, min(0.99, conservative))
    return {
        "raw": raw,
        "conservative": conservative,
        "confidence": confidence,
        "reliability": reliability,
        "evidence_factor": evidence_factor,
        "reasons": reasons,
    }


def entry_correlation_guardrail(legs: list) -> dict:
    """Apply an uncertainty haircut only to legs that share an actual game."""
    same_event_pairs = 0
    same_team_pairs = 0
    same_player_pairs = 0
    unknown_events = 0
    event_keys = [entry_event_key(leg) for leg in (legs or [])]
    unknown_events = sum(1 for key in event_keys if not key)

    for left in range(len(legs or [])):
        for right in range(left + 1, len(legs or [])):
            a = legs[left] or {}
            b = legs[right] or {}
            same_event = bool(event_keys[left] and event_keys[left] == event_keys[right])
            if not same_event:
                continue
            same_event_pairs += 1
            team_a = str(
                a.get("pp_team") or a.get("pitcher_team")
                or a.get("player_team") or a.get("team") or ""
            ).strip().upper()
            team_b = str(
                b.get("pp_team") or b.get("pitcher_team")
                or b.get("player_team") or b.get("team") or ""
            ).strip().upper()
            if team_a and team_a == team_b:
                same_team_pairs += 1
            if normalize_name(a.get("player", "")) == normalize_name(b.get("player", "")):
                same_player_pairs += 1

    factor = 0.92 ** same_event_pairs
    factor *= 0.96 ** same_team_pairs
    factor *= 0.85 ** same_player_pairs
    factor = max(0.72, min(1.0, factor))
    if same_player_pairs:
        label = "Same-player overlap"
    elif same_event_pairs:
        label = "Same-game guardrail"
    elif unknown_events:
        label = "Independent · some games unverified"
    else:
        label = "Different games"
    return {
        "factor": factor,
        "label": label,
        "same_event_pairs": same_event_pairs,
        "same_team_pairs": same_team_pairs,
        "same_player_pairs": same_player_pairs,
        "unknown_events": unknown_events,
    }


def entry_exact_hit_distribution(probabilities: list) -> list:
    """Poisson-binomial distribution for exact hit counts."""
    distribution = [1.0]
    for probability in probabilities or []:
        p = max(0.0, min(1.0, float(probability)))
        updated = [0.0] * (len(distribution) + 1)
        for hits, mass in enumerate(distribution):
            updated[hits] += mass * (1.0 - p)
            updated[hits + 1] += mass * p
        distribution = updated
    return distribution


def evaluate_entry_payout(legs: list, payout_tiers: Optional[dict] = None) -> dict:
    """Evaluate joint chance, break-even payout, and optional expected return."""
    legs = list(legs or [])
    leg_models = [conservative_entry_leg_probability(leg) for leg in legs]
    raw_joint = 1.0
    independent_joint = 1.0
    for model in leg_models:
        raw_joint *= model["raw"]
        independent_joint *= model["conservative"]

    correlation = entry_correlation_guardrail(legs)
    conservative_joint = independent_joint * correlation["factor"]
    conservative_joint = max(0.0001, min(0.9999, conservative_joint)) if legs else 0.0
    break_even = (1.0 / conservative_joint) if conservative_joint else None
    distribution = entry_exact_hit_distribution(
        [model["conservative"] for model in leg_models]
    )

    clean_tiers = {}
    for hits, multiplier in (payout_tiers or {}).items():
        try:
            hit_count = int(hits)
            payout = max(0.0, float(multiplier))
        except (TypeError, ValueError):
            continue
        if 0 <= hit_count < len(distribution) and payout > 0:
            clean_tiers[hit_count] = payout

    payout_entered = bool(clean_tiers)
    expected_return = None
    expected_profit = None
    value_label = "ENTER PAYOUT"
    if payout_entered:
        expected_return = sum(
            distribution[hits] * multiplier
            for hits, multiplier in clean_tiers.items()
        )
        # Unknown same-game dependence should never make an entry look better.
        expected_return *= correlation["factor"]
        expected_profit = expected_return - 1.0
        if expected_profit >= 0.08:
            value_label = "VALUE"
        elif expected_profit >= 0.0:
            value_label = "THIN"
        else:
            value_label = "NEGATIVE"

    avg_confidence = (
        sum(model["confidence"] for model in leg_models) / len(leg_models)
        if leg_models else 0.0
    )
    return {
        "legs": legs,
        "leg_models": leg_models,
        "raw_joint": raw_joint,
        "independent_joint": independent_joint,
        "conservative_joint": conservative_joint,
        "break_even_multiplier": break_even,
        "correlation": correlation,
        "distribution": distribution,
        "payout_tiers": clean_tiers,
        "payout_entered": payout_entered,
        "expected_return": expected_return,
        "expected_profit": expected_profit,
        "value_label": value_label,
        "avg_confidence": avg_confidence,
        "min_confidence": min((model["confidence"] for model in leg_models), default=0.0),
    }


def _entry_ledger_key(scan_id: str, legs: list, payout_tiers: dict) -> str:
    """Stable identity for one exact entered slip and its displayed payout."""
    import hashlib
    import json

    leg_keys = sorted(
        _learning_prediction_key(scan_id, leg)
        for leg in (legs or [])
    )
    tiers = {
        str(int(hits)): round(float(multiplier), 4)
        for hits, multiplier in (payout_tiers or {}).items()
        if float(multiplier or 0) > 0
    }
    payload = {
        "model_version": MODEL_LEARNING_VERSION,
        "scan_id": str(scan_id or ""),
        "legs": leg_keys,
        "payout_tiers": tiers,
    }
    raw = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def build_entry_ledger_row(
    legs: list,
    payout_evaluation: dict,
    payout_format: str,
    scan_id: str,
    session_id: str = "",
) -> Optional[dict]:
    """Freeze an exact payout-aware entry for later ROI settlement."""
    legs = list(legs or [])
    payout_evaluation = payout_evaluation or {}
    clean_tiers = payout_evaluation.get("payout_tiers", {}) or {}
    if not legs or not clean_tiers:
        return None

    now_iso = datetime.utcnow().isoformat() + "Z"
    leg_snapshots = []
    for leg in legs:
        player_id = leg.get("pitcher_id") or leg.get("player_id")
        team = (
            leg.get("pp_team") or leg.get("pitcher_team")
            or leg.get("player_team") or leg.get("team") or ""
        )
        market = str(leg.get("stat") or leg.get("market") or "")
        leg_snapshots.append({
            "prediction_key": _learning_prediction_key(scan_id, leg),
            "sport": str(leg.get("sport", "")).upper(),
            "player": str(leg.get("player", "")),
            "player_id": str(player_id) if player_id else None,
            "team": str(team),
            "opponent": str(leg.get("opp") or leg.get("opponent") or ""),
            "market": market,
            "line": float(leg.get("line", 0) or 0),
            "side": str(leg.get("side", "Over")),
            "odds_type": str(leg.get("odds_type", "standard")),
            "event_id": str(
                leg.get("game_pk") or leg.get("event_id")
                or leg.get("game_id") or ""
            ),
            "event_key": entry_event_key(leg),
            "game_date": str(leg.get("game_date") or leg.get("pp_game_date") or "")[:10],
            "game_datetime": leg.get("game_datetime") or leg.get("start_time"),
            "probability": round(float(leg.get("adj", 0) or 0), 2),
            "evidence_quality": _parse_numeric_value(leg.get("confidence"), None),
            "reliability": _parse_numeric_value(leg.get("reliability"), None),
            "entry_score": _parse_numeric_value(
                leg.get("_entry_score", leg.get("entry_score")), None
            ),
            "action": str(leg.get("_entry_action") or leg.get("entry_action") or ""),
            "result": "Pending",
            "actual_value": None,
        })

    sport_values = sorted({leg.get("sport", "") for leg in leg_snapshots if leg.get("sport")})
    sport = sport_values[0] if len(sport_values) == 1 else "MIXED"
    tiers_json = {str(int(hits)): float(value) for hits, value in clean_tiers.items()}
    correlation = payout_evaluation.get("correlation", {}) or {}
    full_payout = float(tiers_json.get(str(len(legs)), 0) or 0)
    return {
        "entry_key": _entry_ledger_key(scan_id, legs, clean_tiers),
        "scan_id": str(scan_id or ""),
        "session_id": str(session_id or ""),
        "source": "edge_entry_builder",
        "model_version": MODEL_LEARNING_VERSION,
        "sport": sport,
        "entry_size": len(legs),
        "payout_format": str(payout_format or "all_hit"),
        "payout_tiers": tiers_json,
        "displayed_full_payout": full_payout,
        "stake": 1.0,
        "raw_probability": round(float(payout_evaluation.get("raw_joint", 0) or 0) * 100, 3),
        "conservative_probability": round(
            float(payout_evaluation.get("conservative_joint", 0) or 0) * 100, 3
        ),
        "break_even_multiplier": _parse_numeric_value(
            payout_evaluation.get("break_even_multiplier"), None
        ),
        "expected_return": _parse_numeric_value(
            payout_evaluation.get("expected_return"), None
        ),
        "expected_profit": _parse_numeric_value(
            payout_evaluation.get("expected_profit"), None
        ),
        "value_label": str(payout_evaluation.get("value_label", "")),
        "correlation_factor": _parse_numeric_value(correlation.get("factor"), 1.0),
        "correlation_label": str(correlation.get("label", "")),
        "legs": leg_snapshots,
        "status": "Pending",
        "result": "Pending",
        "hits": 0,
        "misses": 0,
        "pushes": 0,
        "realized_multiplier": None,
        "realized_return": None,
        "realized_profit": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }


def save_entry_ledger_row(row: Optional[dict]) -> dict:
    """Save one entered slip to Supabase with a session fallback."""
    if not row or not row.get("entry_key"):
        return {"saved": False, "durable": False, "duplicate": False}

    local = st.session_state.setdefault("entry_ledger", [])
    existing = next(
        (item for item in local if item.get("entry_key") == row.get("entry_key")),
        None,
    )
    if existing:
        return {"saved": True, "durable": bool(existing.get("id")), "duplicate": True}
    local.insert(0, row)

    try:
        sb = get_supabase_client()
        if not sb:
            set_runtime_metric(
                "entry_ledger", "warn",
                "Entry saved for this session · Supabase unavailable",
            )
            return {"saved": True, "durable": False, "duplicate": False}
        import requests as _req
        response = _req.post(
            f"{sb.url}/rest/v1/entry_ledger?on_conflict=entry_key",
            headers={
                **sb.hdrs,
                "Prefer": "resolution=ignore-duplicates,return=representation",
            },
            json=row,
            timeout=12,
        )
        if response.ok:
            saved_rows = response.json() if response.content else []
            if isinstance(saved_rows, list) and saved_rows:
                row.update(saved_rows[0])
            set_runtime_metric(
                "entry_ledger", "ok", "Exact entry and payout saved for ROI tracking",
                fetched_at=datetime.utcnow().isoformat() + "Z",
            )
            return {"saved": True, "durable": True, "duplicate": False}
        record_debug_error(
            "entry_ledger.save",
            f"HTTP {response.status_code}: {response.text[:180]}",
        )
        set_runtime_metric(
            "entry_ledger", "warn",
            "Session-only entry · run supabase_entry_ledger.sql",
        )
    except Exception as err:
        record_debug_error("entry_ledger.save", err)
    return {"saved": True, "durable": False, "duplicate": False}


def load_entry_ledger(limit: int = 1000, force: bool = False) -> list:
    """Load entered slips and merge them with any session-only entries."""
    if not force and st.session_state.get("entry_ledger_loaded"):
        return st.session_state.get("entry_ledger", []) or []
    server_rows = []
    try:
        sb = get_supabase_client()
        if sb:
            import requests as _req
            response = _req.get(
                f"{sb.url}/rest/v1/entry_ledger"
                f"?select=*&order=created_at.desc&limit={max(1, min(int(limit), 2500))}",
                headers=sb.hdrs,
                timeout=12,
            )
            if response.ok and isinstance(response.json(), list):
                server_rows = response.json()
            elif response.status_code not in (400, 404):
                record_debug_error(
                    "entry_ledger.load",
                    f"HTTP {response.status_code}: {response.text[:180]}",
                )
    except Exception as err:
        record_debug_error("entry_ledger.load", err)

    merged = {}
    for row in (st.session_state.get("entry_ledger", []) or []) + server_rows:
        key = row.get("entry_key")
        if not key:
            continue
        current = merged.get(key)
        if not current or str(row.get("updated_at", "")) >= str(current.get("updated_at", "")):
            merged[key] = {**(current or {}), **row}
    rows = sorted(
        merged.values(), key=lambda item: str(item.get("created_at", "")), reverse=True
    )
    st.session_state.entry_ledger = rows
    st.session_state.entry_ledger_loaded = True
    return rows


def update_entry_ledger_row(row: dict, updates: dict) -> bool:
    """Update a local entered slip and its durable copy."""
    row.update(updates)
    row["updated_at"] = datetime.utcnow().isoformat() + "Z"
    try:
        sb = get_supabase_client()
        if not sb:
            return False
        import requests as _req
        from urllib.parse import quote as _quote
        selector = (
            f"id=eq.{_quote(str(row['id']), safe='')}"
            if row.get("id") else
            f"entry_key=eq.{_quote(str(row.get('entry_key', '')), safe='')}"
        )
        response = _req.patch(
            f"{sb.url}/rest/v1/entry_ledger?{selector}",
            headers={**sb.hdrs, "Prefer": "return=minimal"},
            json={**updates, "updated_at": row["updated_at"]},
            timeout=10,
        )
        return response.ok
    except Exception as err:
        record_debug_error("entry_ledger.update", err)
        return False


def _entry_leg_identity(row: dict) -> tuple:
    """Fallback identity when an older entry lacks a direct prediction key."""
    row = row or {}
    event = str(row.get("event_id") or row.get("event_key") or row.get("game_date") or "")
    return (
        str(row.get("sport", "")).upper(),
        str(row.get("player_id") or normalize_name(row.get("player", ""))),
        event,
        str(row.get("market") or row.get("stat") or ""),
        round(float(row.get("line", 0) or 0), 3),
        str(row.get("side", "Over")),
        str(row.get("odds_type", "standard")),
    )


def settle_entry_ledger(entries: list, predictions: list) -> dict:
    """Settle entered slips from their frozen pregame prediction rows."""
    by_key = {
        row.get("prediction_key"): row
        for row in (predictions or []) if row.get("prediction_key")
    }
    by_identity = {}
    for prediction in predictions or []:
        by_identity.setdefault(_entry_leg_identity(prediction), prediction)

    settled_count = 0
    review_count = 0
    pending_count = 0
    for entry in entries or []:
        if str(entry.get("status", "Pending")) != "Pending":
            continue
        resolved_legs = []
        all_resolved = True
        for leg in entry.get("legs", []) or []:
            prediction = by_key.get(leg.get("prediction_key"))
            if not prediction:
                prediction = by_identity.get(_entry_leg_identity(leg))
            if not prediction or str(prediction.get("status", "Pending")) != "Settled":
                all_resolved = False
                resolved_legs.append(leg)
                continue
            resolved_legs.append({
                **leg,
                "result": str(prediction.get("result", "Pending")),
                "actual_value": prediction.get("actual_value"),
                "settled_at": prediction.get("settled_at"),
            })

        if not all_resolved or not resolved_legs:
            pending_count += 1
            continue

        hits = sum(1 for leg in resolved_legs if leg.get("result") == "Hit")
        misses = sum(1 for leg in resolved_legs if leg.get("result") == "Miss")
        pushes = sum(1 for leg in resolved_legs if leg.get("result") == "Push")
        common = {
            "legs": resolved_legs,
            "hits": hits,
            "misses": misses,
            "pushes": pushes,
            "settled_at": datetime.utcnow().isoformat() + "Z",
        }
        if pushes:
            update_entry_ledger_row(entry, {
                **common,
                "status": "Needs review",
                "result": "Push payout review",
            })
            review_count += 1
            continue

        tiers = entry.get("payout_tiers", {}) or {}
        multiplier = float(tiers.get(str(hits), tiers.get(hits, 0)) or 0)
        stake = float(entry.get("stake", 1.0) or 1.0)
        realized_return = stake * multiplier
        realized_profit = realized_return - stake
        if realized_profit > 1e-9:
            result = "Won" if hits == len(resolved_legs) else "Partial payout"
        elif abs(realized_profit) <= 1e-9:
            result = "Break-even"
        else:
            result = "Lost"
        update_entry_ledger_row(entry, {
            **common,
            "status": "Settled",
            "result": result,
            "realized_multiplier": round(multiplier, 4),
            "realized_return": round(realized_return, 4),
            "realized_profit": round(realized_profit, 4),
        })
        settled_count += 1

    return {
        "settled": settled_count,
        "needs_review": review_count,
        "pending": pending_count,
    }


def get_pp_displayed_line(attributes: dict) -> dict:
    """Return the line PrizePicks displays, including active promo overrides."""
    attrs = attributes or {}
    try:
        base_line = float(attrs.get("line_score"))
    except (TypeError, ValueError):
        return {
            "line": None,
            "base_line": None,
            "is_promo": False,
            "line_source": "missing",
        }

    # PrizePicks can keep the regular line in line_score while the app shows a
    # discounted flash-sale line. Ignoring that override makes the scanner
    # analyze a harder line than the user can actually select.
    promo_fields = (
        "flash_sale_line_score",
        "discounted_line_score",
        "promo_line_score",
    )
    for field in promo_fields:
        try:
            promo_line = float(attrs.get(field))
        except (TypeError, ValueError):
            continue
        if promo_line >= 0 and abs(promo_line - base_line) >= 0.01:
            return {
                "line": promo_line,
                "base_line": base_line,
                "is_promo": True,
                "line_source": field,
            }

    return {
        "line": base_line,
        "base_line": base_line,
        "is_promo": False,
        "line_source": "line_score",
    }


def pp_projection_recency_key(row: dict) -> tuple:
    """Rank duplicate projection rows without relying on lexical ID order."""
    updated = pd.to_datetime(row.get("updated_at"), utc=True, errors="coerce")
    board = pd.to_datetime(row.get("board_time"), utc=True, errors="coerce")
    updated_ns = int(updated.value) if pd.notna(updated) else 0
    board_ns = int(board.value) if pd.notna(board) else 0
    projection_id = str(row.get("projection_id", "") or "")
    try:
        numeric_id = int(projection_id)
    except (TypeError, ValueError):
        numeric_id = 0
    # At equal timestamps, prefer the displayed promo and then its easier line.
    return (
        updated_ns,
        board_ns,
        1 if row.get("is_promo") else 0,
        -float(row.get("line", 0) or 0),
        numeric_id,
        projection_id,
    )


def select_lowest_pp_goblin_row(goblins: list, standard: Optional[dict] = None) -> Optional[dict]:
    """Return the freshest row at the lowest valid goblin line."""
    rows = [row for row in (goblins or []) if row.get("line") is not None]
    if not rows:
        return None
    if standard and standard.get("line") is not None:
        below_standard = [
            row for row in rows
            if float(row["line"]) < float(standard["line"])
        ]
        if below_standard:
            rows = below_standard
    lowest_line = min(float(row["line"]) for row in rows)
    lowest_rows = [
        row for row in rows
        if abs(float(row["line"]) - lowest_line) < 0.01
    ]
    return max(lowest_rows, key=pp_projection_recency_key)


def stamp_pp_slate_metadata(props: list, source: str, age_minutes: float = 0.0) -> list:
    """Attach freshness metadata used by ranking and line-verification gates."""
    stamped = []
    for prop in props or []:
        if not isinstance(prop, dict):
            continue
        row = dict(prop)
        legacy_line = "line_source" not in row
        legacy_selection = (
            int(row.get("line_selection_version", 0) or 0)
            < PP_LINE_SELECTION_VERSION
        )
        row["slate_source"] = source
        row["slate_age_minutes"] = max(0.0, float(age_minutes or 0.0))
        row["line_verification_required"] = (
            legacy_line
            or legacy_selection
            or not pp_event_key(row)
            or (
                source != "live"
                and row["slate_age_minutes"] > PP_VERIFY_LINE_AFTER_MINUTES
            )
        )
        row.setdefault("line_source", "legacy_cache" if legacy_line else "line_score")
        stamped.append(row)
    return stamped

def normalize_mlb_pitcher_prop_stat(stat: str) -> str:
    """Normalize MLB prop names used by PropIQ's MLB models."""
    s = re.sub(r"[^a-z0-9]+", " ", str(stat or "").lower()).strip()
    # Do not let the hitter strikeout market leak into the pitcher model.
    if ("hitter" in s or "batter" in s) and ("strikeout" in s or "strike out" in s):
        return "Hitter Strikeouts"
    if any(token in s for token in (
        "hitter fantasy score", "batter fantasy score", "fantasy score",
        "fantasy points", "fantasy pts", "hitter fantasy", "batter fantasy"
    )):
        return "Hitter Fantasy Score"
    if any(token in s for token in (
        "pitcher strikeout", "pitcher strikeouts", "strikeout", "strikeouts",
        "strike out", "strike outs", "pitcher k", "pitcher ks"
    )):
        return "Strikeouts"
    if any(token in s for token in (
        "pitcher out", "pitcher outs", "outs recorded", "out recorded", "recorded outs"
    )):
        return "Outs Recorded"
    # Some feeds label outs as innings pitched. Do this only after strikeout checks.
    if "inning" in s and "strike" not in s:
        return "Outs Recorded"
    return str(stat or "")


def mlb_pitcher_prop_verdict(adj: float, edge: float, side: str,
                             pc_ceiling: Optional[float] = None,
                             line: Optional[float] = None) -> str:
    """Shared MLB pitcher verdict used by both Analyze and Edge."""
    ceiling_capped = (
        pc_ceiling is not None
        and line is not None
        and float(pc_ceiling) <= float(line)
    )
    if side == "Over":
        if not ceiling_capped:
            if adj >= 0.72 and edge >= 0.75:
                return "Strong Over"
            if adj >= 0.64 and edge >= 1.75:
                return "Strong Over"
        if adj >= 0.63 and edge > 0:
            return "Lean Over"
        if adj >= 0.56 and edge >= 0.5:
            return "Lean Over"
    else:
        if not ceiling_capped:
            if adj >= 0.72 and edge <= -0.75:
                return "Strong Under"
            if adj >= 0.64 and edge <= -1.75:
                return "Strong Under"
        if adj >= 0.63 and edge < 0:
            return "Lean Under"
        if adj >= 0.56 and edge <= -0.5:
            return "Lean Under"
    return "Pass"


def mlb_count_side_prob(
    expected: Optional[float],
    line: float,
    side: str,
    observed_mean: Optional[float] = None,
    observed_variance: Optional[float] = None,
) -> Optional[float]:
    """Push-aware Poisson/negative-binomial probability for MLB count props."""
    if expected is None or expected <= 0:
        return None
    try:
        import math
        mu = max(0.05, float(expected))
        over_cutoff = int(math.floor(float(line)))
        under_cutoff = int(math.ceil(float(line)) - 1)
        cutoff = under_cutoff if str(side).lower() == "under" else over_cutoff
        if cutoff < 0:
            return 0.0 if str(side).lower() == "under" else 1.0

        use_nb = False
        variance = None
        if observed_variance is not None:
            variance = max(0.0, float(observed_variance))
            reference_mean = max(0.05, float(observed_mean or mu))
            variance = mu * max(1.0, variance / reference_mean)
            use_nb = variance > mu + 0.20

        cdf = 0.0
        if use_nb:
            r = max(0.25, (mu * mu) / max(variance - mu, 1e-6))
            p = r / (r + mu)
            for k in range(cutoff + 1):
                log_pmf = (
                    math.lgamma(k + r) - math.lgamma(r) - math.lgamma(k + 1)
                    + (r * math.log(p)) + (k * math.log(1.0 - p))
                )
                cdf += math.exp(log_pmf)
        else:
            for k in range(cutoff + 1):
                cdf += math.exp(-mu) * (mu ** k) / math.factorial(k)
        if side == "Over":
            return max(0.01, min(0.99, 1.0 - cdf))
        return max(0.01, min(0.99, cdf))
    except Exception:
        return None


def is_mlb_strikeout_prop(stat: str) -> bool:
    return normalize_mlb_pitcher_prop_stat(stat) == "Strikeouts"


def select_safest_pp_over_rows(props: list) -> list:
    """Keep the lowest selectable Over line for each player and market."""
    safest = {}
    for prop in props or []:
        if prop.get("is_demon"):
            continue
        try:
            candidate_line = float(prop.get("line"))
        except (TypeError, ValueError):
            continue
        event_key = prop.get("game_id") or prop.get("start_time") or "upcoming"
        key = (
            str(prop.get("sport", "")),
            normalize_name(prop.get("player", "")),
            str(prop.get("stat", "")),
            str(event_key),
        )
        current = safest.get(key)
        if current is None:
            safest[key] = prop
            continue
        current_line = float(current.get("line", 999) or 999)
        if (
            candidate_line < current_line
            or (
                abs(candidate_line - current_line) < 0.01
                and pp_projection_recency_key(prop) > pp_projection_recency_key(current)
            )
        ):
            safest[key] = prop
    return list(safest.values())


def select_safest_mlb_strikeout_rows(props: list) -> list:
    """Backward-compatible strikeout selector used by older cached flows."""
    strikeouts = [p for p in props or [] if is_mlb_strikeout_prop(p.get("stat", ""))]
    other_rows = [p for p in props or [] if not is_mlb_strikeout_prop(p.get("stat", ""))]
    return other_rows + select_safest_pp_over_rows(strikeouts)


def is_mlb_pitcher_outs_prop(stat: str) -> bool:
    return normalize_mlb_pitcher_prop_stat(stat) == "Outs Recorded"


def is_mlb_hitter_fantasy_prop(stat: str) -> bool:
    return normalize_mlb_pitcher_prop_stat(stat) == "Hitter Fantasy Score"


def normalize_wnba_prop_stat(stat: str) -> str:
    """Map PrizePicks WNBA market labels to the analyzer's canonical names."""
    s = re.sub(r"[^a-z0-9]+", " ", str(stat or "").lower()).strip()
    compact = s.replace(" ", "")
    aliases = {
        "points": "Points", "pts": "Points",
        "rebounds": "Rebounds", "rebound": "Rebounds", "rebs": "Rebounds", "reb": "Rebounds",
        "assists": "Assists", "assist": "Assists", "asts": "Assists", "ast": "Assists",
        "3ptmade": "3-Pointers Made", "3ptsmade": "3-Pointers Made", "3pm": "3-Pointers Made",
        "3pointersmade": "3-Pointers Made", "threepointersmade": "3-Pointers Made",
        "ptsrebsasts": "Pts + Reb + Ast", "pointsreboundsassists": "Pts + Reb + Ast", "pra": "Pts + Reb + Ast",
        "ptsrebs": "Points + Rebounds", "pointsrebounds": "Points + Rebounds", "pr": "Points + Rebounds",
        "ptsasts": "Points + Assists", "pointsassists": "Points + Assists", "pa": "Points + Assists",
        "rebsasts": "Rebounds + Assists", "reboundsassists": "Rebounds + Assists", "ra": "Rebounds + Assists",
    }
    return aliases.get(compact, str(stat or ""))


def is_wnba_supported_prop(stat: str) -> bool:
    return normalize_wnba_prop_stat(stat) in WNBA_STAT_COLUMNS


def is_wnba_points_prop(stat: str) -> bool:
    return normalize_wnba_prop_stat(stat) == "Points"


def is_sane_wnba_prop_line(stat: str, line) -> bool:
    """Reject cross-mapped or malformed WNBA lines before model execution."""
    try:
        market = normalize_wnba_prop_stat(stat)
        value = float(line)
    except Exception:
        return False
    ranges = {
        "Points": (0.5, 40.5), "Rebounds": (0.5, 20.5),
        "Assists": (0.5, 15.5), "3-Pointers Made": (0.5, 8.5),
        "Pts + Reb + Ast": (4.5, 65.5), "Points + Rebounds": (2.5, 55.5),
        "Points + Assists": (2.5, 52.5), "Rebounds + Assists": (1.5, 32.5),
    }
    low, high = ranges.get(market, (1.0, 0.0))
    return low <= value <= high


def is_sane_mlb_pitcher_prop_line(stat: str, line) -> bool:
    """
    Guard against stale/mis-mapped PrizePicks rows where a strikeout line is
    attached to Pitcher Outs, or vice versa.
    """
    try:
        stat_label = normalize_mlb_pitcher_prop_stat(stat)
        line_val = float(line)
    except Exception:
        return False
    if stat_label == "Strikeouts":
        return 0.5 <= line_val <= 12.5
    if stat_label == "Hitter Fantasy Score":
        return 1.5 <= line_val <= 18.5
    if stat_label == "Outs Recorded":
        return 9.0 <= line_val <= 24.5
    return False


def filter_usable_pp_cached_props(props: list, sport_filter: str) -> list:
    """Keep the requested sport and discard cached projections that already started."""
    if not isinstance(props, list):
        return []
    requested = str(sport_filter or "").upper()
    sport_rows = [
        row for row in props
        if not requested or requested == "BOTH" or str(row.get("sport", "")).upper() == requested
    ]
    now_utc = pd.Timestamp.now(tz="UTC")
    parsed_starts = []
    for row in sport_rows:
        start = pd.to_datetime(row.get("start_time"), utc=True, errors="coerce")
        parsed_starts.append(start)
    # Old cache versions did not retain event time. They remain eligible only
    # through the caller's conservative age limit.
    if not any(pd.notna(start) for start in parsed_starts):
        return sport_rows
    return [
        row for row, start in zip(sport_rows, parsed_starts)
        if (
            pd.notna(start)
            and start >= now_utc - pd.Timedelta(minutes=2)
            and str(row.get("status", "pre_game") or "pre_game").lower()
            not in ("live", "in_progress", "final", "completed", "closed")
        )
    ]


def pp_cache_has_upcoming_event(props: list) -> bool:
    """True when a cached slate contains a timestamped game that has not started."""
    now_utc = pd.Timestamp.now(tz="UTC")
    for row in props or []:
        start = pd.to_datetime(row.get("start_time"), utc=True, errors="coerce")
        if pd.notna(start) and start >= now_utc - pd.Timedelta(minutes=2):
            return True
    return False


def get_cached_pp_props_from_supabase(sport_filter: str, max_age_minutes: int = 720) -> Optional[list]:
    """
    Load the last successful PrizePicks slate from Supabase.
    Optional table: pp_slate_cache(cache_key text unique, props_json text, fetched_at timestamptz).
    Fails quietly if the table does not exist.
    """
    try:
        sb = get_supabase_client()
        if not sb:
            return None
        import requests as _req, json as _json
        cache_key = f"edge_slate_{sport_filter.lower()}"
        hdrs = {
            "apikey": sb.key,
            "Authorization": f"Bearer {sb.key}",
            "Content-Type": "application/json",
        }
        url = (
            f"{sb.url}/rest/v1/pp_slate_cache"
            f"?cache_key=eq.{cache_key}"
            f"&select=props_json,fetched_at"
            f"&order=fetched_at.desc"
            f"&limit=1"
        )
        r = _req.get(url, headers=hdrs, timeout=5)
        if not r.ok:
            record_debug_error("pp_cache.load", f"HTTP {r.status_code}: {r.text[:200]}")
            return None
        rows = r.json()
        if not rows:
            return None
        fetched_at = pd.to_datetime(rows[0].get("fetched_at"), utc=True, errors="coerce")
        if pd.isna(fetched_at):
            return None
        age_minutes = (pd.Timestamp.utcnow() - fetched_at).total_seconds() / 60
        if age_minutes > max_age_minutes:
            set_runtime_metric(
                "pp_slate", "stale",
                f"Supabase slate too old ({age_minutes:.0f} min)",
                source="supabase", fetched_at=str(fetched_at),
            )
            return None
        raw_props = rows[0].get("props_json", "[]")
        props = _json.loads(raw_props) if isinstance(raw_props, str) else raw_props
        props = filter_usable_pp_cached_props(props, sport_filter)
        props = stamp_pp_slate_metadata(props, "supabase", age_minutes)
        if isinstance(props, list) and props:
            st.session_state["edge_fetch_debug"] = [
                f"Using Supabase cached PrizePicks slate ({age_minutes:.0f} min old)"
            ]
            set_runtime_metric(
                "pp_slate", "ok",
                f"Supabase cache · {len(props)} props · {age_minutes:.0f} min old",
                source="supabase", fetched_at=fetched_at.isoformat(),
            )
            return props
    except Exception as e:
        record_debug_error("pp_cache.load", e)
    return None


def save_pp_props_to_supabase(sport_filter: str, props: list) -> bool:
    """Save last successful PrizePicks slate for rate-limit fallback."""
    if not props:
        st.session_state["edge_cache_save_status"] = "Supabase cache skipped: no props to save."
        return False
    try:
        sb = get_supabase_client()
        if not sb:
            record_debug_error("pp_cache.save", "No Supabase client")
            st.session_state["edge_cache_save_status"] = "Supabase cache save failed: no Supabase client/config."
            return False
        import requests as _req, json as _json
        hdrs = {
            "apikey": sb.key,
            "Authorization": f"Bearer {sb.key}",
            "Content-Type": "application/json",
            "Prefer": "resolution=merge-duplicates,return=minimal",
        }
        payload = {
            "cache_key": f"edge_slate_{sport_filter.lower()}",
            "props_json": _json.dumps(props),
            "fetched_at": datetime.utcnow().isoformat() + "Z",
        }
        r = _req.post(
            f"{sb.url}/rest/v1/pp_slate_cache?on_conflict=cache_key",
            headers=hdrs,
            json=payload,
            timeout=6,
        )
        if r.ok:
            st.session_state["edge_cache_save_status"] = (
                f"Supabase cache saved: edge_slate_{sport_filter.lower()} ({len(props)} props)."
            )
            set_runtime_metric(
                "supabase", "ok",
                f"Saved pp_slate_cache ({len(props)} props)",
                table="pp_slate_cache",
            )
            return True

        # Some users accidentally create props_json as json/jsonb instead of text.
        # Retry with a native JSON payload so the cache still works.
        payload_json = dict(payload)
        payload_json["props_json"] = props
        r2 = _req.post(
            f"{sb.url}/rest/v1/pp_slate_cache?on_conflict=cache_key",
            headers=hdrs,
            json=payload_json,
            timeout=6,
        )
        if r2.ok:
            st.session_state["edge_cache_save_status"] = (
                f"Supabase cache saved: edge_slate_{sport_filter.lower()} ({len(props)} props)."
            )
            set_runtime_metric(
                "supabase", "ok",
                f"Saved pp_slate_cache ({len(props)} props)",
                table="pp_slate_cache",
            )
            return True

        if not r.ok:
            detail = f"HTTP {r.status_code}: {r.text[:200]} | retry HTTP {r2.status_code}: {r2.text[:200]}"
            record_debug_error("pp_cache.save", detail)
            st.session_state["edge_cache_save_status"] = f"Supabase cache save failed: {detail}"
        return False
    except Exception as e:
        record_debug_error("pp_cache.save", e)
        st.session_state["edge_cache_save_status"] = f"Supabase cache save failed: {e}"
        return False


def save_pp_line_history_to_supabase(props: list, source: str = "live") -> bool:
    """
    Save compact PrizePicks line snapshots for market-history comparison.
    Optional table: pp_line_history(sport, player, team, stat, line, odds_type,
    is_goblin, is_demon, source, snapshot_at).
    """
    if not props:
        return False
    try:
        sb = get_supabase_client()
        if not sb:
            return False
        import requests as _req
        snapshot_at = datetime.utcnow().isoformat() + "Z"
        rows = []
        for p in props:
            sport = str(p.get("sport", "")).upper()
            stat = str(p.get("stat", ""))
            if sport == "MLB":
                stat_norm = normalize_mlb_pitcher_prop_stat(stat)
                if stat_norm not in ("Strikeouts", "Hitter Fantasy Score"):
                    continue
            elif sport == "WNBA":
                stat_norm = normalize_wnba_prop_stat(stat)
                if not is_wnba_supported_prop(stat_norm):
                    continue
            else:
                continue
            event_key = pp_event_key(p)
            event_source = f"{source}|{event_key}" if event_key else source
            rows.append({
                "sport":       sport,
                "player":      p.get("player", ""),
                "team":        p.get("team", ""),
                "stat":        stat_norm,
                "line":        float(p.get("line", 0)),
                "odds_type":   p.get("odds_type", "standard"),
                "is_goblin":   bool(p.get("is_goblin", False)),
                "is_demon":    bool(p.get("is_demon", False)),
                "source":      event_source,
                "snapshot_at": snapshot_at,
            })
        if not rows:
            return False
        hdrs = {
            "apikey": sb.key,
            "Authorization": f"Bearer {sb.key}",
            "Content-Type": "application/json",
            "Prefer": "return=minimal",
        }
        saved = 0
        for offset in range(0, len(rows), 400):
            chunk = rows[offset:offset + 400]
            r = _req.post(
                f"{sb.url}/rest/v1/pp_line_history",
                headers=hdrs,
                json=chunk,
                timeout=10,
            )
            if not r.ok:
                record_debug_error(
                    "pp_line_history.save",
                    f"HTTP {r.status_code}: {r.text[:200]}",
                )
                return False
            saved += len(chunk)
        set_runtime_metric(
            "pp_line_history", "ok",
            f"Saved {saved} event-scoped line snapshots",
            table="pp_line_history", source=source,
        )
        return True
    except Exception as e:
        record_debug_error("pp_line_history.save", e)
        return False


@st.cache_data(ttl=300, show_spinner=False)
def get_pp_line_history_from_supabase(player: str, stat: str, limit: int = 25,
                                      sport: str = "MLB") -> list:
    """Return recent historical PrizePicks lines for one player/stat."""
    try:
        sb = get_supabase_client()
        if not sb or not player or not stat:
            return []
        import requests as _req
        from urllib.parse import quote as _quote
        hdrs = {
            "apikey": sb.key,
            "Authorization": f"Bearer {sb.key}",
            "Content-Type": "application/json",
        }
        url = (
            f"{sb.url}/rest/v1/pp_line_history"
            f"?sport=eq.{_quote(str(sport or 'MLB').upper(), safe='')}"
            f"&player=eq.{_quote(str(player), safe='')}"
            f"&stat=eq.{_quote(str(stat), safe='')}"
            f"&select=line,team,odds_type,is_goblin,is_demon,source,snapshot_at"
            f"&order=snapshot_at.desc"
            f"&limit={int(limit)}"
        )
        r = _req.get(url, headers=hdrs, timeout=6)
        if not r.ok:
            record_debug_error("pp_line_history.load", f"HTTP {r.status_code}: {r.text[:200]}")
            return []
        rows = r.json()
        return rows if isinstance(rows, list) else []
    except Exception as e:
        record_debug_error("pp_line_history.load", e)
        return []


def summarize_pp_line_history(current_line: float, rows: list,
                              current_odds_type: str = "standard",
                              current_team: str = "",
                              current_event_key: str = "") -> dict:
    """Summarize current line vs recent stored PrizePicks snapshots."""
    summary = {
        "prev_line": None,
        "open_line": None,
        "move": 0.0,
        "open_move": 0.0,
        "snapshots": 0,
        "last_seen": None,
        "market_note": "",
        "market_signal": "Neutral",
    }
    try:
        if not rows:
            return summary
        target_odds = str(current_odds_type or "standard").lower()
        target_odds = "goblin" if target_odds == "goblin" else "standard"
        team_aliases = {
            "AZ": "ARI", "ARZ": "ARI", "CWS": "CHW", "WSH": "WSN",
            "WAS": "WSN", "SF": "SFG", "SD": "SDP", "TB": "TBR",
            "KC": "KCR", "OAK": "ATH",
        }
        target_team = team_aliases.get(
            str(current_team or "").upper().strip(),
            str(current_team or "").upper().strip(),
        )
        parsed = []
        for r in rows:
            if current_event_key:
                row_source = str(r.get("source") or "")
                if row_source != f"live|{current_event_key}" and not row_source.endswith(
                    f"|{current_event_key}"
                ):
                    continue
            row_odds = str(r.get("odds_type") or "standard").lower()
            row_odds = "goblin" if row_odds == "goblin" or r.get("is_goblin") else "standard"
            if row_odds != target_odds or r.get("is_demon"):
                continue
            row_team_raw = str(r.get("team") or "").upper().strip()
            row_team = team_aliases.get(row_team_raw, row_team_raw)
            if target_team and row_team and row_team != target_team:
                continue
            try:
                line = float(r.get("line"))
            except Exception:
                continue
            ts = pd.to_datetime(r.get("snapshot_at"), utc=True, errors="coerce")
            parsed.append({"line": line, "snapshot_at": ts})
        if not parsed:
            return summary
        # Do not interpret a previous start's market as movement on today's
        # line. Starting-pitcher markets normally belong to a new event every
        # four to six days, while the current slate is posted within this window.
        now_utc = pd.Timestamp.now(tz="UTC")
        current_slate = [
            item for item in parsed
            if pd.notna(item["snapshot_at"])
            and item["snapshot_at"] >= now_utc - pd.Timedelta(hours=72)
        ]
        if current_slate:
            parsed = current_slate
        else:
            return summary
        parsed = sorted(parsed, key=lambda x: x["snapshot_at"] or pd.Timestamp.min.tz_localize("UTC"), reverse=True)
        current = float(current_line)
        # Previous snapshot with a different line is the most useful movement signal.
        prev_diff = next((p for p in parsed if abs(p["line"] - current) >= 0.01), None)
        oldest = parsed[-1]
        prev_line = prev_diff["line"] if prev_diff else parsed[0]["line"]
        open_line = oldest["line"]
        move = round(current - prev_line, 2)
        open_move = round(current - open_line, 2)
        summary.update({
            "prev_line": prev_line,
            "open_line": open_line,
            "move": move,
            "open_move": open_move,
            "snapshots": len(parsed),
            "last_seen": parsed[0]["snapshot_at"].isoformat() if pd.notna(parsed[0]["snapshot_at"]) else None,
        })
        if abs(open_move) >= 1.0:
            summary["market_signal"] = "Moved Up" if open_move > 0 else "Moved Down"
            summary["market_note"] = f"PP line moved {open_move:+.1f} from first seen"
        elif abs(move) >= 0.5:
            summary["market_signal"] = "Moved Up" if move > 0 else "Moved Down"
            summary["market_note"] = f"PP line moved {move:+.1f} from prior snapshot"
        elif len(parsed) >= 3:
            summary["market_note"] = "Line stable across recent snapshots"
        return summary
    except Exception:
        return summary


def _pp_local_cache_path(sport_filter: str) -> str:
    safe = re.sub(r"[^a-z0-9_-]+", "_", str(sport_filter).strip().lower())
    return os.path.join("/tmp", "propiq_cache", f"pp_slate_{safe}.json")


def get_cached_pp_props_from_local(sport_filter: str, max_age_minutes: int = 720) -> Optional[list]:
    """Load the last successful PrizePicks slate from local disk (/tmp)."""
    try:
        import json as _json
        path = _pp_local_cache_path(sport_filter)
        if not os.path.exists(path):
            return None
        age_minutes = (time.time() - os.path.getmtime(path)) / 60
        if age_minutes > max_age_minutes:
            set_runtime_metric(
                "pp_slate", "stale",
                f"Local slate too old ({age_minutes:.0f} min)",
                source="local",
            )
            return None
        with open(path, "r", encoding="utf-8") as f:
            payload = _json.load(f)
        props = payload if isinstance(payload, list) else payload.get("props", [])
        props = filter_usable_pp_cached_props(props, sport_filter)
        props = stamp_pp_slate_metadata(props, "local", age_minutes)
        if isinstance(props, list) and props:
            st.session_state["edge_fetch_debug"] = [
                f"Using local cached PrizePicks slate ({age_minutes:.0f} min old)"
            ]
            set_runtime_metric(
                "pp_slate", "ok",
                f"Local cache · {len(props)} props · {age_minutes:.0f} min old",
                source="local",
                fetched_at=datetime.utcfromtimestamp(os.path.getmtime(path)).isoformat() + "Z",
            )
            return props
    except Exception as e:
        record_debug_error("pp_cache.local_load", e)
    return None


def save_pp_props_to_local(sport_filter: str, props: list) -> bool:
    """Save last successful PrizePicks slate to /tmp for same-instance fallback."""
    if not props:
        return False
    try:
        import json as _json
        path = _pp_local_cache_path(sport_filter)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        payload = {
            "fetched_at": datetime.utcnow().isoformat() + "Z",
            "props": props,
        }
        with open(path, "w", encoding="utf-8") as f:
            _json.dump(payload, f)
        return True
    except Exception as e:
        record_debug_error("pp_cache.local_save", e)
        return False


def clear_pp_slate_cache(sport_filter: str) -> None:
    """Clear Streamlit, local, durable, and cooldown state for one PP slate."""
    safe_sport = str(sport_filter or "").strip().lower()
    try:
        path = _pp_local_cache_path(sport_filter)
        if os.path.exists(path):
            os.remove(path)
    except Exception as e:
        record_debug_error("pp_cache.local_clear", e)

    try:
        sb = get_supabase_client()
        if sb:
            import requests as _req
            cache_key = f"edge_slate_{safe_sport}"
            hdrs = {
                "apikey": sb.key,
                "Authorization": f"Bearer {sb.key}",
                "Content-Type": "application/json",
            }
            r = _req.delete(
                f"{sb.url}/rest/v1/pp_slate_cache?cache_key=eq.{cache_key}",
                headers=hdrs,
                timeout=6,
            )
            if not r.ok:
                record_debug_error(
                    "pp_cache.supabase_clear",
                    f"HTTP {r.status_code}: {r.text[:200]}",
                )
    except Exception as e:
        record_debug_error("pp_cache.supabase_clear", e)

    st.session_state.pop(f"pp_rate_limit_until_{safe_sport}", None)
    st.session_state[f"pp_force_live_{safe_sport}"] = True
    st.session_state.pop("edge_fetch_debug", None)
    st.session_state.pop("edge_cache_save_status", None)


# ── Auto prop result detection ───────────────────────────────

def auto_detect_result(entry: dict) -> Optional[str]:
    """
    Check if a tracked prop has a result by looking at the player's
    exact tracked game. Returns 'Hit', 'Miss', 'Push', or None if the game
    hasn't been played yet.
    """
    try:
        from datetime import datetime as _auto_datetime
        player_name = entry.get("Player", "")
        line_str    = entry.get("Line", "")  # e.g. "24.5 Over" or "17.0 Under"

        if not player_name or not line_str:
            return None

        # Parse line and side
        parts = line_str.strip().split()
        if len(parts) < 2:
            return None
        try:
            line_val = float(parts[0])
        except ValueError:
            return None
        side = parts[1] if len(parts) > 1 else "Over"

        sport = _tracker_sport(entry)
        prop = str(entry.get("Matchup", ""))
        is_mlb = sport == "MLB" or prop in ("Strikeouts", "Hitter Fantasy Score")
        expected_date_text = _tracker_metadata_value(entry, "Game Date")[:10]
        expected_date = pd.to_datetime(expected_date_text, errors="coerce")
        event_id = _tracker_metadata_value(entry, "Event ID")
        player_id = _tracker_metadata_value(entry, "Player ID")

        if is_mlb:
            # Results renders before the analyzer-local MLB helpers are defined.
            # Use the always-available exact-event settlement path instead.
            actual = _learning_mlb_actual(
                player_id, player_name, prop, expected_date_text, event_id,
            )
            if actual is None:
                return None
            return _learning_pick_result(actual, line_val, side)

        if sport == "WNBA":
            # Keep this normalization local because the full WNBA analyzer is
            # intentionally not loaded on the standalone Results destination.
            market_aliases = {
                "3PT Made": "3-Pointers Made", "3-PT Made": "3-Pointers Made",
                "Fantasy Score": "Pts + Reb + Ast", "PRA": "Pts + Reb + Ast",
                "Points + Rebs": "Points + Rebounds",
                "Points + Asts": "Points + Assists",
                "Rebs + Asts": "Rebounds + Assists",
            }
            market = market_aliases.get(prop, prop)
            actual = _learning_wnba_actual(
                player_id, market, expected_date_text, event_id,
                entry.get("Opponent", ""),
            )
            if actual is None:
                return None
            return _learning_pick_result(actual, line_val, side)

        # Find NBA player ID
        nba_id, _ = nba_find_player(player_name)
        if not nba_id:
            return None

        # Get game logs (uses cache), then select the exact tracked game when
        # durable metadata is available.
        from datetime import datetime, timedelta
        import pytz
        et  = pytz.timezone("America/New_York")
        now = datetime.now(et)

        # Reuse the n=15 cache — just take head(1)
        _det_logs = nba_get_game_logs(nba_id, "2025-26", n=15, _date=_cache_date())
        logs = _det_logs.copy() if _det_logs is not None else _det_logs
        if logs is None or logs.empty:
            return None

        logs["GAME_DATE"] = pd.to_datetime(logs["GAME_DATE"], errors="coerce")
        logs = logs.dropna(subset=["GAME_DATE"])
        if pd.notna(expected_date):
            logs = logs[logs["GAME_DATE"].dt.date == expected_date.date()]
        else:
            logs = logs.head(1)
        if logs.empty:
            return None

        # Check if the most recent game was today or yesterday
        last_game_date = pd.to_datetime(logs.iloc[0]["GAME_DATE"])
        days_ago = (now.date() - last_game_date.date()).days

        # Only auto-detect if game was within last 2 days
        if days_ago > 2:
            return None

        # Get actual points
        actual_pts = pd.to_numeric(logs.iloc[0]["PTS"], errors="coerce")
        if pd.isna(actual_pts):
            return None

        # Determine result
        return _learning_pick_result(actual_pts, line_val, side)

    except Exception as err:
        record_debug_error("results.tracker_settle", err)
        return None


# ── Injury status ─────────────────────────────────────────────

@st.cache_data(ttl=300, show_spinner=False)  # refresh every 5 mins — injury status can change fast
def get_player_injury_status(player_name: str) -> Tuple[str, str]:
    """
    Fetch current NBA injury status for a player.
    Returns (status, reason) where status is one of:
      'Out', 'Doubtful', 'Questionable', 'Probable', 'Active', 'Unknown'

    Sources tried in order:
    1. NBA official injury report via nbainjuries package
    2. ESPN injuries endpoint as fallback
    """
    norm = normalize_name(player_name)

    # ── Source 1: nbainjuries package (NBA official data) ──
    try:
        from nbainjuries import injury
        from datetime import datetime
        import pytz
        et = pytz.timezone("America/New_York")
        now = datetime.now(et)
        report = injury.get_reportdata(now)
        if report:
            for entry in report:
                entry_name = normalize_name(entry.get("Player Name", ""))
                # NBA report uses "Last, First" format
                parts = entry_name.split(", ")
                if len(parts) == 2:
                    entry_name = f"{parts[1]} {parts[0]}"
                if norm in entry_name or entry_name in norm:
                    status = entry.get("Current Status", "Unknown")
                    reason = entry.get("Reason", "")
                    return status, reason
    except Exception:
        pass

    # ── Source 2: ESPN injuries endpoint ──
    try:
        data = espn_get(f"{ESPN_SITE}/injuries")
        for team in data.get("injuries", []):
            for item in team.get("injuries", []):
                ath  = item.get("athlete", {})
                name = normalize_name(ath.get("displayName", ""))
                if norm in name or name in norm:
                    status = item.get("status", "Unknown")
                    detail = item.get("shortComment", item.get("longComment", ""))
                    return status, detail
    except Exception:
        pass

    # ── Source 3: ESPN team-specific injuries ──
    # More reliable — fetches per team roster injury data
    try:
        # Find the player's ESPN team first
        all_players = espn_get_all_players(_date=_cache_date())
        ep = next((p for p in all_players if normalize_name(p["full_name"]) == norm), None)
        if ep:
            team_id = None
            # Get team ID from team abbr
            teams_data = espn_get(f"{ESPN_SITE}/teams")
            teams_list = (
                teams_data.get("sports", [{}])[0].get("leagues", [{}])[0].get("teams", [])
                or teams_data.get("teams", [])
            )
            for t in teams_list:
                team = t.get("team", t)
                if team.get("abbreviation", "") == ep["team_abbr"]:
                    team_id = team.get("id")
                    break
            if team_id:
                roster = espn_get(f"{ESPN_SITE}/teams/{team_id}/roster")
                for athlete in roster.get("athletes", []):
                    for item in (athlete.get("items") or [athlete]):
                        aname = normalize_name(item.get("displayName", ""))
                        if norm in aname or aname in norm:
                            injuries = item.get("injuries", [])
                            if injuries:
                                inj = injuries[0]
                                status = inj.get("status", "Unknown")
                                detail = inj.get("shortComment", inj.get("longComment", ""))
                                if status and status != "Active":
                                    return status, detail
    except Exception:
        pass

    return "Active", ""


# ── Usage spike detector ─────────────────────────────────

# ESPN uses non-standard abbreviations for some teams — normalize them
_ESPN_ABBR_MAP = {
    "GS":  "GSW", "SA":  "SAS", "NY":  "NYK", "NO":  "NOP",
    "OKC": "OKC", "UTA": "UTA", "PHX": "PHX", "LAC": "LAC",
    "LAL": "LAL", "BKN": "BKN", "CHA": "CHA", "WSH": "WAS",
    "MEM": "MEM", "MIN": "MIN",
}

def _norm_team_abbr(abbr: str) -> str:
    """Normalize ESPN team abbreviation to standard 3-letter NBA abbr."""
    return _ESPN_ABBR_MAP.get(abbr, abbr)


@st.cache_data(ttl=300, show_spinner=False)
def get_team_injury_report(team_abbr: str) -> list:
    """
    Fetch all injured players for a given team from NBA official report.
    Returns list of dicts: {name, status, reason}
    """
    # Normalize incoming abbr
    team_abbr = _norm_team_abbr(team_abbr)
    results = []

    # Source 0: ESPN injuries endpoint — try multiple URL patterns
    for _inj_url in [
        f"https://site.api.espn.com/apis/site/v2/sports/basketball/nba/injuries",
        f"https://sports.core.api.espn.com/v2/sports/basketball/leagues/nba/injuries?limit=300",
    ]:
        try:
            inj_data = espn_get(_inj_url)
            # Pattern 1: {injuries: [{team: {abbreviation}, injuries: [...]}]}
            for team_entry in inj_data.get("injuries", []):
                raw_abbr  = team_entry.get("team", {}).get("abbreviation", "")
                norm_abbr = _norm_team_abbr(raw_abbr)
                if norm_abbr != team_abbr and raw_abbr != team_abbr:
                    continue
                for item in team_entry.get("injuries", []):
                    ath    = item.get("athlete", {})
                    name   = ath.get("displayName", "")
                    status = item.get("status", item.get("type", {}).get("description", ""))
                    detail = item.get("shortComment", item.get("longComment", ""))
                    if name and status:
                        results.append({
                            "name":   name,
                            "status": status,
                            "reason": detail,
                        })
            # Pattern 2: flat items list
            for item in inj_data.get("items", []):
                ath      = item.get("athlete", {})
                name     = ath.get("displayName", "")
                team_ref = item.get("team", {})
                raw_abbr = team_ref.get("abbreviation", "")
                if _norm_team_abbr(raw_abbr) != team_abbr and raw_abbr != team_abbr:
                    continue
                status = item.get("status", item.get("type", {}).get("description", ""))
                detail = item.get("shortComment", item.get("longComment", ""))
                if name and status:
                    results.append({
                        "name":   name,
                        "status": status,
                        "reason": detail,
                    })
            if results:
                return results
        except Exception:
            continue

    # Source 1: nbainjuries package
    try:
        from nbainjuries import injury
        from datetime import datetime
        import pytz
        et = pytz.timezone("America/New_York")
        now = datetime.now(et)
        report = injury.get_reportdata(now)
        if report:
            # Build team name → abbr mapping
            _team_map = {
                "Atlanta Hawks": "ATL", "Boston Celtics": "BOS",
                "Brooklyn Nets": "BKN", "Charlotte Hornets": "CHA",
                "Chicago Bulls": "CHI", "Cleveland Cavaliers": "CLE",
                "Dallas Mavericks": "DAL", "Denver Nuggets": "DEN",
                "Detroit Pistons": "DET", "Golden State Warriors": "GSW",
                "Houston Rockets": "HOU", "Indiana Pacers": "IND",
                "LA Clippers": "LAC", "Los Angeles Clippers": "LAC",
                "Los Angeles Lakers": "LAL", "Memphis Grizzlies": "MEM",
                "Miami Heat": "MIA", "Milwaukee Bucks": "MIL",
                "Minnesota Timberwolves": "MIN", "New Orleans Pelicans": "NOP",
                "New York Knicks": "NYK", "Oklahoma City Thunder": "OKC",
                "Orlando Magic": "ORL", "Philadelphia 76ers": "PHI",
                "Phoenix Suns": "PHX", "Portland Trail Blazers": "POR",
                "Sacramento Kings": "SAC", "San Antonio Spurs": "SAS",
                "Toronto Raptors": "TOR", "Utah Jazz": "UTA",
                "Washington Wizards": "WAS",
            }
            for entry in report:
                entry_team = entry.get("Team", "")
                entry_abbr = _team_map.get(entry_team, "")
                if entry_abbr != team_abbr:
                    continue
                raw_name = entry.get("Player Name", "")
                parts = raw_name.split(", ")
                name = f"{parts[1]} {parts[0]}" if len(parts) == 2 else raw_name
                results.append({
                    "name":   name,
                    "status": entry.get("Current Status", "Unknown"),
                    "reason": entry.get("Reason", ""),
                })
        if results:
            return results
    except Exception:
        pass

    # Source 2: ESPN team roster injuries
    try:
        teams_data = espn_get(f"{ESPN_SITE}/teams")
        teams_list = (
            teams_data.get("sports", [{}])[0].get("leagues", [{}])[0].get("teams", [])
            or teams_data.get("teams", [])
        )
        team_id = None
        for t in teams_list:
            team = t.get("team", t)
            if team.get("abbreviation", "") == team_abbr:
                team_id = team.get("id")
                break
        if team_id:
            roster = espn_get(f"{ESPN_SITE}/teams/{team_id}/roster")
            for athlete in roster.get("athletes", []):
                for item in (athlete.get("items") or [athlete]):
                    injuries = item.get("injuries", [])
                    if injuries:
                        inj    = injuries[0]
                        status = inj.get("status", "Unknown")
                        if status and status not in ("Active", ""):
                            results.append({
                                "name":   item.get("displayName", ""),
                                "status": status,
                                "reason": inj.get("shortComment", ""),
                            })
    except Exception:
        pass

    return results


@st.cache_data(ttl=21600, show_spinner=False)
def get_teammate_minutes(team_abbr: str, season: str = "2025-26", _date: str = None) -> dict:
    """
    Returns dict of {normalized_player_name: avg_minutes} for all players on a team.
    Uses ESPN athlete stats endpoint which returns per-game averages.
    """
    team_abbr = _norm_team_abbr(team_abbr)
    result = {}

    try:
        # Get team ID using normalized abbr
        teams_data = espn_get(f"{ESPN_SITE}/teams")
        teams_list = (
            teams_data.get("sports", [{}])[0].get("leagues", [{}])[0].get("teams", [])
            or teams_data.get("teams", [])
        )
        team_id = None
        for t in teams_list:
            team = t.get("team", t)
            # Match against both ESPN abbr and normalized abbr
            t_abbr = team.get("abbreviation", "")
            if t_abbr == team_abbr or _norm_team_abbr(t_abbr) == team_abbr:
                team_id = team.get("id")
                break

        if team_id:
            # ESPN athlete stats — includes season averages per player
            url = (
                f"https://site.api.espn.com/apis/site/v2/sports/basketball/nba"
                f"/teams/{team_id}/athletes?season=2026"
            )
            athletes_data = espn_get(url)
            for item in athletes_data.get("athletes", []):
                name  = item.get("displayName", "")
                stats = item.get("stats", [])
                # Stats array: index 9 is usually MIN in ESPN's athlete endpoint
                # Try to find by label first
                labels = athletes_data.get("labels", [])
                if labels and "MIN" in labels:
                    idx = labels.index("MIN")
                    if idx < len(stats):
                        val = float(stats[idx] or 0)
                        if val > 0 and name:
                            result[normalize_name(name)] = round(val, 1)
                elif len(stats) > 9:
                    # Fallback: index 9 is typically MIN
                    try:
                        val = float(stats[9] or 0)
                        if 5 < val < 48 and name:  # sanity check range
                            result[normalize_name(name)] = round(val, 1)
                    except Exception:
                        pass
    except Exception:
        pass

    # Fallback: use nba_api player game logs for each player on the team
    if not result:
        try:
            from nba_api.stats.static import players as nba_static
            from nba_api.stats.endpoints import commonteamroster
            # Find team ID in nba_api
            from nba_api.stats.static import teams as nba_teams
            nba_team = next(
                (t for t in nba_teams.get_teams()
                 if t.get("abbreviation") == team_abbr),
                None
            )
            if nba_team:
                roster_df = commonteamroster.CommonTeamRoster(
                    team_id=nba_team["id"], season=season, timeout=30,
                ).get_data_frames()[0]
                for _, row in roster_df.iterrows():
                    pid  = row.get("PLAYER_ID")
                    name = str(row.get("PLAYER", ""))
                    if pid and name:
                        try:
                            logs = playergamelog.PlayerGameLog(
                                player_id=pid, season=season, timeout=15,
                            ).get_data_frames()[0]
                            mins = pd.to_numeric(logs["MIN"], errors="coerce").dropna().mean()
                            if mins > 0:
                                result[normalize_name(name)] = round(float(mins), 1)
                        except Exception:
                            pass
        except Exception:
            pass

    return result


def detect_usage_spike(
    player_name: str,
    player_team: str,
    side: str,
    teammate_mins: dict,
) -> Tuple[str, list, str]:
    """
    Checks if key teammates are out tonight using get_player_injury_status
    (already proven working) on each high-minute teammate individually.

    teammate_mins: pre-fetched dict of {normalized_name: avg_minutes}
    """
    if not player_team or not teammate_mins:
        return "Neutral", [], ""

    player_norm = normalize_name(player_name)

    # Top 5 key teammates by minutes (>22 mpg), excluding the player
    key_teammates = sorted(
        [(name, mins) for name, mins in teammate_mins.items()
         if mins >= 22 and name != player_norm],
        key=lambda x: -x[1]
    )[:5]

    if not key_teammates:
        return "Neutral", [], ""

    # Pre-fetch all ESPN players once
    all_players = espn_get_all_players(_date=_cache_date())

    def _check_teammate(norm_name_mins):
        norm_name, mins = norm_name_mins
        display_name = next(
            (p["full_name"] for p in all_players
             if normalize_name(p["full_name"]) == norm_name
             and _norm_team_abbr(p.get("team_abbr", "")) == player_team),
            norm_name.title()
        )
        status, reason = get_player_injury_status(display_name)
        return display_name, status, reason, mins

    # Check all key teammates in parallel
    import concurrent.futures
    key_absent = []
    total_redistributed = 0.0

    with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
        futures = {executor.submit(_check_teammate, t): t for t in key_teammates}
        for future in concurrent.futures.as_completed(futures, timeout=6):
            try:
                display_name, status, reason, mins = future.result()
                if status.upper() in ("OUT", "DOUBTFUL"):
                    key_absent.append({
                        "name":    display_name,
                        "status":  status,
                        "minutes": mins,
                        "reason":  reason.replace("Injury/Illness - ", "").strip(),
                    })
                    total_redistributed += mins * 0.4
            except Exception:
                pass

    if not key_absent:
        return "Neutral", [], ""

    _names = ", ".join(f"{p['name']} ({p['minutes']:.0f} mpg)" for p in key_absent)
    _total = f"+{total_redistributed:.0f} min available"

    alert_html = (
        f"<div style='background:#0c1a0c;border:1px solid #166534;border-radius:10px;"
        f"padding:0.65rem 1rem;margin-bottom:0.5rem;display:flex;align-items:center;gap:10px;'>"
        f"<span style='font-size:1.1rem;'>📈</span>"
        f"<div style='font-family:DM Mono;font-size:0.7rem;'>"
        f"<span style='color:#22c55e;font-weight:800;text-transform:uppercase;"
        f"letter-spacing:0.08em;'>Usage spike detected</span>"
        f"<span style='color:#6b7f96;'> · {_names} out — {_total} to redistribute</span>"
        f"</div>"
        f"</div>"
    )
    return "Boost", key_absent, alert_html


def injury_alert_html(status: str, reason: str) -> str:
    """
    Returns an HTML alert string for the injury status.
    Returns empty string if player is Active/Unknown (no issue).
    """
    status_upper = status.upper()

    if "OUT" in status_upper:
        bg, border, color, icon = "#1c0505", "#991b1b", "#ef4444", "🚫"
        label = "OUT"
        block_verdict = True
    elif "DOUBTFUL" in status_upper:
        bg, border, color, icon = "#1c0505", "#991b1b", "#ef4444", "⛔"
        label = "DOUBTFUL"
        block_verdict = True
    elif "QUESTIONABLE" in status_upper:
        bg, border, color, icon = "#1c1005", "#854d0e", "#f97316", "⚠️"
        label = "QUESTIONABLE"
        block_verdict = False
    elif "PROBABLE" in status_upper:
        bg, border, color, icon = "#0c1a0c", "#166534", "#86efac", "🟡"
        label = "PROBABLE"
        block_verdict = False
    else:
        return "", False

    reason_short = reason.replace("Injury/Illness - ", "").replace("Injury/Illness -", "").strip()
    reason_html  = f"<span style='color:#7d93ab;'> · {reason_short}</span>" if reason_short else ""

    html = (
        f"<div style='background:{bg};border:1px solid {border};border-radius:10px;"
        f"padding:0.7rem 1rem;margin-bottom:0.75rem;display:flex;align-items:center;gap:10px;'>"
        f"<span style='font-size:1.2rem;'>{icon}</span>"
        f"<div>"
        f"<span style='font-family:DM Mono;font-size:0.7rem;font-weight:800;color:{color};"
        f"letter-spacing:0.08em;text-transform:uppercase;'>{label}</span>"
        f"{reason_html}"
        f"</div>"
        f"</div>"
    )
    return html, block_verdict


@st.cache_data(ttl=21600, show_spinner=False)
def classify_matchup_espn(opp_abbr: Optional[str], _date: str = None) -> Tuple[str, Optional[float], str]:
    """Classify opponent defense quality using ESPN team stats."""
    league_avg = 114.5
    if not opp_abbr:
        return "Neutral", None, str(league_avg)

    opp_pts = espn_get_opp_pts_allowed(opp_abbr, _date=_cache_date())

    if opp_pts is None:
        return "Neutral", None, str(league_avg)

    diff = opp_pts - league_avg
    if diff >= 1.5:
        return "Good", opp_pts, str(league_avg)
    if diff <= -1.5:
        return "Bad", opp_pts, str(league_avg)
    return "Neutral", opp_pts, str(league_avg)

