if st.session_state.active_sport == "mlb":

    # ── MLB Data Functions ─────────────────────────────

    @st.cache_data(ttl=3600, show_spinner=False)
    def mlb_get_pitcher_logs(player_name: str, n: int = 10) -> pd.DataFrame:
        """
        Fetch pitcher game logs — bulletproof multi-fallback version.
        Tries multiple player lookup strategies and multiple game type params.
        Never returns empty if the player exists in MLB.
        """
        _COLS = ["DATE","OPP","HOME","IP","OUTS","K","BB","ER","RESULT","SEASON"]
        empty = pd.DataFrame(columns=_COLS)
        if not player_name or not player_name.strip():
            return empty

        try:
            import requests as _req
            import datetime as _dtx

            _norm = lambda s: s.lower().strip().replace(".", "").replace("-", " ")
            _target = _norm(player_name)
            _parts  = [p for p in _target.split() if len(p) > 2]
            _last   = _target.split()[-1]
            _first  = _target.split()[0] if len(_target.split()) > 1 else ""
            season  = _dtx.datetime.now().year

            # ── Step 1: Find player ID via multiple strategies ──
            pid = None
            people = []

            # Strategy A: Full active roster (most reliable)
            for _gt in ["R", "S", "E"]:  # Regular, Spring, Exhibition
                try:
                    _r = _req.get(
                        "https://statsapi.mlb.com/api/v1/sports/1/players",
                        params={"season": season, "gameType": _gt},
                        timeout=10
                    )
                    if _r.ok:
                        _all = _r.json().get("people", [])
                        if _all:
                            people = _all
                            break
                except Exception:
                    continue

            if people:
                # Match priority: exact > last+first > last only > partial
                _candidates = (
                    [p for p in people if _norm(p.get("fullName","")) == _target] or
                    [p for p in people if (
                        _norm(p.get("fullName","")).split()[-1] == _last and
                        (_first in _norm(p.get("fullName","")) or not _first)
                    )] or
                    [p for p in people if all(
                        pt in _norm(p.get("fullName","")) for pt in _parts
                    )] or
                    [p for p in people if _last in _norm(p.get("fullName",""))]
                )
                # Prefer pitchers (position code 1)
                _pitchers = [p for p in _candidates
                             if p.get("primaryPosition", {}).get("code") in ("1", "P")]
                _best = (_pitchers or _candidates)
                if _best:
                    pid = _best[0]["id"]

            # Strategy B: People search endpoint
            if not pid:
                for _query in [player_name, _last, f"{_first} {_last}"]:
                    try:
                        _sr = _req.get(
                            "https://statsapi.mlb.com/api/v1/people/search",
                            params={"names": _query, "sportIds": 1},
                            timeout=8
                        )
                        if _sr.ok:
                            _res = _sr.json().get("people", [])
                            # Exact match first
                            _match = next(
                                (p for p in _res
                                 if _last in _norm(p.get("fullName","")) and
                                 (_first in _norm(p.get("fullName","")) or not _first)),
                                None
                            )
                            # Fuzzy fallback — handles 1-char typos (Emmet→Emmett)
                            if not _match and _res:
                                def _close(a, b):
                                    a, b = a.lower(), b.lower()
                                    if len(a) >= 4 and len(b) >= 4:
                                        return a[:4] == b[:4] or a in b or b in a
                                    return a == b
                                _match = next(
                                    (p for p in _res
                                     if _close(p.get("fullName","").split()[-1], _last)),
                                    _res[0] if len(_res) == 1 else None
                                )
                            if _match:
                                pid = _match["id"]
                                break
                    except Exception:
                        continue

            if not pid:
                return empty

            # ── Step 2: Fetch game logs — try multiple gameType combos ──
            splits = []
            # Regular-season starts are the only valid sample for a regular-
            # season prop. Mixing relief work or spring games can badly skew a
            # converted starter's hit rate and workload baseline.
            _game_type_tries = ["R"]
            for _gt_str in _game_type_tries:
                try:
                    _lr = _req.get(
                        f"https://statsapi.mlb.com/api/v1/people/{pid}/stats",
                        params={
                            "stats":     "gameLog",
                            "group":     "pitching",
                            "season":    season,
                            "gameType":  _gt_str,
                            "limit":     n + 15,
                        },
                        timeout=12
                    )
                    if _lr.ok:
                        _data = _lr.json().get("stats", [])
                        for _stat_block in _data:
                            _sp = _stat_block.get("splits", [])
                            if _sp:
                                splits.extend(_sp)
                        if splits:
                            break
                except Exception:
                    continue

            # Strategy C: Try prior season if current season empty
            if not splits:
                try:
                    _lr2 = _req.get(
                        f"https://statsapi.mlb.com/api/v1/people/{pid}/stats",
                        params={
                            "stats":    "gameLog",
                            "group":    "pitching",
                            "season":   season - 1,
                            "gameType": "R",
                            "limit":    n + 10,
                        },
                        timeout=10
                    )
                    if _lr2.ok:
                        _data2 = _lr2.json().get("stats", [])
                        for _sb in _data2:
                            splits.extend(_sb.get("splits", []))
                except Exception:
                    pass

            if not splits:
                return empty

            # ── Step 3: Parse splits into DataFrame ──
            _TEAM_ID_TO_ABBR = {
                108:"LAA", 109:"ARI", 110:"BAL", 111:"BOS", 112:"CHC",
                113:"CIN", 114:"CLE", 115:"COL", 116:"DET", 117:"HOU",
                118:"KCR", 119:"LAD", 120:"WSN", 121:"NYM", 133:"ATH",
                134:"PIT", 135:"SDP", 136:"SEA", 137:"SFG", 138:"STL",
                139:"TBR", 140:"TEX", 141:"TOR", 142:"MIN", 143:"PHI",
                144:"ATL", 145:"CHW", 146:"MIA", 147:"NYY", 158:"MIL",
            }
            _TEAM_NAME_TO_ABBR = {
                "ANGELS":"LAA", "DIAMONDBACKS":"ARI", "DBACKS":"ARI",
                "ORIOLES":"BAL", "REDSOX":"BOS", "CUBS":"CHC",
                "WHITESOX":"CHW", "REDS":"CIN", "GUARDIANS":"CLE",
                "ROCKIES":"COL", "TIGERS":"DET", "ASTROS":"HOU",
                "ROYALS":"KCR", "DODGERS":"LAD", "NATIONALS":"WSN",
                "METS":"NYM", "ATHLETICS":"ATH", "PIRATES":"PIT",
                "PADRES":"SDP", "MARINERS":"SEA", "GIANTS":"SFG",
                "CARDINALS":"STL", "RAYS":"TBR", "RANGERS":"TEX",
                "BLUEJAYS":"TOR", "TWINS":"MIN", "PHILLIES":"PHI",
                "BRAVES":"ATL", "MARLINS":"MIA", "YANKEES":"NYY",
                "BREWERS":"MIL",
            }
            def _opp_abbr_from_split(split_obj: dict) -> str:
                opp = split_obj.get("opponent") or {}
                for key in ("abbreviation", "fileCode", "teamCode", "triCode"):
                    val = opp.get(key)
                    if val:
                        return str(val).upper()
                oid = opp.get("id")
                try:
                    if oid is not None and int(oid) in _TEAM_ID_TO_ABBR:
                        return _TEAM_ID_TO_ABBR[int(oid)]
                except Exception:
                    pass
                for key in ("name", "teamName", "clubName", "locationName", "shortName"):
                    val = opp.get(key)
                    if val:
                        cleaned = re.sub(r"[^A-Z]", "", str(val).upper())
                        if cleaned in _TEAM_NAME_TO_ABBR:
                            return _TEAM_NAME_TO_ABBR[cleaned]
                        for name_key, abbr in _TEAM_NAME_TO_ABBR.items():
                            if name_key in cleaned:
                                return abbr
                        if 2 <= len(cleaned) <= 4:
                            return cleaned
                return "—"

            rows = []
            seen_dates = set()
            for s in splits:
                stat = s.get("stat", {})
                if int(stat.get("gamesStarted", 0) or 0) < 1:
                    continue
                date = s.get("date", "")[:10]
                if not date or date in seen_dates:
                    continue
                seen_dates.add(date)

                ip_str = str(stat.get("inningsPitched", "0.0") or "0.0")
                try:
                    _ip_parts = ip_str.split(".")
                    _full = int(_ip_parts[0])
                    _part = int(_ip_parts[1]) if len(_ip_parts) > 1 and _ip_parts[1] else 0
                    outs  = _full * 3 + _part
                except Exception:
                    outs = 0

                rows.append({
                    "DATE":   date,
                    "OPP":    _opp_abbr_from_split(s),
                    "HOME":   bool(s.get("isHome", False)),
                    "IP":     ip_str,
                    "OUTS":   outs,
                    "K":      int(stat.get("strikeOuts", 0) or 0),
                    "BB":     int(stat.get("baseOnBalls", 0) or 0),
                    "ER":     int(stat.get("earnedRuns", 0) or 0),
                    "RESULT": stat.get("note", "") or "",
                    "SEASON": int(date[:4]),
                })

            if not rows:
                return empty

            df = pd.DataFrame(rows)
            df["DATE"] = pd.to_datetime(df["DATE"], errors="coerce")
            df = df.dropna(subset=["DATE"])
            df = df.sort_values("DATE", ascending=False).reset_index(drop=True)
            return df.head(n)

        except Exception:
            return empty

    # ── MLB Park factors ──────────────────────────────────────
    _MLB_PARK_FACTORS = {
        "COL": 1.30, "CIN": 1.10, "BOS": 1.08, "PHI": 1.06,
        "TEX": 1.05, "NYY": 1.04, "CHC": 1.03, "HOU": 1.02,
        "ATL": 1.01, "MIL": 1.01, "STL": 1.00, "LAD": 0.99,
        "NYM": 0.99, "TOR": 0.98, "DET": 0.98, "MIN": 0.97,
        "CLE": 0.97, "ARI": 0.97, "BAL": 0.97, "KCR": 0.96,
        "PIT": 0.96, "TBR": 0.96, "CHW": 0.95, "SEA": 0.95,
        "SFG": 0.94, "MIA": 0.94, "LAA": 0.94, "WSN": 0.93, "WSH": 0.93,
        "OAK": 0.93, "SDP": 0.92,
    }

    def mlb_norm_abbr(abbr: str) -> str:
        """Normalize common MLB abbreviation variants across APIs."""
        a = str(abbr or "").upper().strip()
        a = re.sub(r"[^A-Z]", "", a)
        _name_map = {
            "ARIZONADIAMONDBACKS": "ARI", "DIAMONDBACKS": "ARI", "DBACKS": "ARI",
            "ATLANTABRAVES": "ATL", "BRAVES": "ATL",
            "BALTIMOREORIOLES": "BAL", "ORIOLES": "BAL",
            "BOSTONREDSOX": "BOS", "REDSOX": "BOS",
            "CHICAGOCUBS": "CHC", "CUBS": "CHC",
            "CHICAGOWHITESOX": "CHW", "WHITESOX": "CHW",
            "CINCINNATIREDS": "CIN", "REDS": "CIN",
            "CLEVELANDGUARDIANS": "CLE", "GUARDIANS": "CLE",
            "COLORADOROCKIES": "COL", "ROCKIES": "COL",
            "DETROITTIGERS": "DET", "TIGERS": "DET",
            "HOUSTONASTROS": "HOU", "ASTROS": "HOU",
            "KANSASCITYROYALS": "KCR", "ROYALS": "KCR",
            "LOSANGELESANGELS": "LAA", "ANGELS": "LAA",
            "LOSANGELESDODGERS": "LAD", "DODGERS": "LAD",
            "MIAMIMARLINS": "MIA", "MARLINS": "MIA",
            "MILWAUKEEBREWERS": "MIL", "BREWERS": "MIL",
            "MINNESOTATWINS": "MIN", "TWINS": "MIN",
            "NEWYORKMETS": "NYM", "METS": "NYM",
            "NEWYORKYANKEES": "NYY", "YANKEES": "NYY",
            "ATHLETICS": "ATH", "OAKLANDATHLETICS": "ATH",
            "PHILADELPHIAPHILLIES": "PHI", "PHILLIES": "PHI",
            "PITTSBURGHPIRATES": "PIT", "PIRATES": "PIT",
            "SANDIEGOPADRES": "SDP", "PADRES": "SDP",
            "SANFRANCISCOGIANTS": "SFG", "GIANTS": "SFG",
            "SEATTLEMARINERS": "SEA", "MARINERS": "SEA",
            "STLOUISCARDINALS": "STL", "CARDINALS": "STL",
            "TAMPABAYRAYS": "TBR", "RAYS": "TBR",
            "TEXASRANGERS": "TEX", "RANGERS": "TEX",
            "TORONTOBLUEJAYS": "TOR", "BLUEJAYS": "TOR",
            "WASHINGTONNATIONALS": "WSN", "NATIONALS": "WSN",
        }
        if a in _name_map:
            return _name_map[a]
        _prefix_aliases = {
            "ARI": "ARI", "ATL": "ATL", "BAL": "BAL", "BOS": "BOS",
            "CHC": "CHC", "CHW": "CHW", "CWS": "CHW", "CIN": "CIN",
            "CLE": "CLE", "COL": "COL", "DET": "DET", "HOU": "HOU",
            "KCR": "KCR", "KCA": "KCR", "KC": "KCR", "LAA": "LAA",
            "LAD": "LAD", "MIA": "MIA", "MIL": "MIL", "MIN": "MIN",
            "NYM": "NYM", "NYY": "NYY", "OAK": "ATH", "ATH": "ATH",
            "PHI": "PHI", "PIT": "PIT", "SDP": "SDP", "SD": "SDP",
            "SFG": "SFG", "SF": "SFG", "SEA": "SEA", "STL": "STL",
            "TBR": "TBR", "TB": "TBR", "TEX": "TEX", "TOR": "TOR",
            "WSN": "WSN", "WSH": "WSN", "WAS": "WSN",
        }
        for _prefix, _canon in sorted(_prefix_aliases.items(), key=lambda x: len(x[0]), reverse=True):
            if len(a) > len(_prefix) and a.startswith(_prefix):
                return _canon
        return {
            "AZ": "ARI", "ARZ": "ARI",
            "CWS": "CHW", "CHW": "CHW",
            "WSH": "WSN", "WAS": "WSN",
            "SF": "SFG", "SFG": "SFG",
            "SD": "SDP", "SDP": "SDP",
            "TB": "TBR", "TBR": "TBR",
            "KC": "KCR", "KCR": "KCR", "KCA": "KCR",
            "OAK": "ATH", "ATH": "ATH",
            "LA": "LAD", "LAD": "LAD",
        }.get(a, a)

    @st.cache_data(ttl=3600, show_spinner=False)
    def mlb_get_opp_k_rate(opp_abbr: str) -> Optional[float]:
        try:
            import requests as _req, datetime
            season = datetime.datetime.now().year
            target = mlb_norm_abbr(opp_abbr)
            teams_r = _req.get("https://statsapi.mlb.com/api/v1/teams",
                params={"sportId":1,"season":season}, timeout=8)
            if not teams_r.ok: return None
            teams = teams_r.json().get("teams",[])
            team  = next((t for t in teams if mlb_norm_abbr(t.get("abbreviation",""))==target),None)
            if not team: return None
            stats_r = _req.get(f"https://statsapi.mlb.com/api/v1/teams/{team['id']}/stats",
                params={"stats":"season","group":"hitting","season":season}, timeout=8)
            if not stats_r.ok: return None
            stat = stats_r.json().get("stats",[{}])[0].get("splits",[{}])[0].get("stat",{})
            pa = int(stat.get("plateAppearances", 0) or 0)
            ab = int(stat.get("atBats", 0) or 0)
            denom = pa if pa > 0 else ab
            k = int(stat.get("strikeOuts", 0) or 0)
            return round(k / denom, 3) if denom > 0 else None
        except Exception: return None

    @st.cache_data(ttl=900, show_spinner=False)
    def mlb_get_tonight_game(pitcher_name: str, team_abbr: str = "") -> dict:
        """
        Find tonight's game for a pitcher.
        Primary: match by team abbreviation (from PrizePicks).
        Fallback: match by pitcher name in probable pitchers.
        """
        import requests as _req, datetime, pytz
        try:
            et    = pytz.timezone("America/New_York")
            today = datetime.datetime.now(et).strftime("%Y-%m-%d")
            sched = _req.get(
                "https://statsapi.mlb.com/api/v1/schedule",
                params={"sportId":1,"date":today,"hydrate":"probablePitcher,team,venue"},
                timeout=10
            )
            if not sched.ok: return {}
            games = []
            for d in sched.json().get("dates",[]): games.extend(d.get("games",[]))

            def _build(game, side):
                home  = mlb_norm_abbr(game["teams"]["home"]["team"]["abbreviation"])
                away  = mlb_norm_abbr(game["teams"]["away"]["team"]["abbreviation"])
                opp   = away if side=="home" else home
                venue = game.get("venue",{}).get("name","")
                prob  = game.get("teams",{}).get(side,{}).get("probablePitcher",{})
                return {"opp":opp,"home_team":home,"away_team":away,
                        "pitcher_side":side,"venue":venue,"game_date":today,
                        "pitcher_team":home if side=="home" else away,
                        "probable_name": prob.get("fullName", "") or prob.get("lastName", ""),
                        "probable_id": prob.get("id"),
                        "game_pk": game.get("gamePk"),
                        "game_datetime": game.get("gameDate")}

            # Pass 1: match by team abbreviation (most reliable)
            if team_abbr:
                for game in games:
                    for side in ["home","away"]:
                        abbr = game["teams"][side]["team"].get("abbreviation","")
                        if abbr.upper() == team_abbr.upper():
                            return _build(game, side)

            # Pass 2: match by probable pitcher name (last name or full)
            _norm  = lambda s: s.lower().replace("-"," ").replace(".","").strip()
            _last  = _norm(pitcher_name).split()[-1] if pitcher_name else ""
            _first = _norm(pitcher_name).split()[0]  if pitcher_name else ""
            _parts = [p for p in _norm(pitcher_name).split() if len(p) > 3]
            for game in games:
                for side in ["home","away"]:
                    prob  = game.get("teams",{}).get(side,{}).get("probablePitcher",{})
                    pname = _norm(prob.get("fullName","") or prob.get("lastName","") or "")
                    if not pname: continue
                    # Match on last name + first initial for safety
                    if _last and _last in pname and (not _first or _first[0] in pname):
                        return _build(game, side)
                    if _parts and all(p in pname for p in _parts):
                        return _build(game, side)

            # Pass 3: check tomorrow's schedule if not found today
            try:
                import datetime as _dtx, pytz as _pyx
                _tomorrow = (datetime.datetime.now(_pyx.timezone("America/New_York"))
                             + datetime.timedelta(days=1)).strftime("%Y-%m-%d")
                sched2 = _req.get(
                    "https://statsapi.mlb.com/api/v1/schedule",
                    params={"sportId":1,"date":_tomorrow,"hydrate":"probablePitcher,team,venue"},
                    timeout=8
                )
                if sched2.ok:
                    games2 = []
                    for d in sched2.json().get("dates",[]): games2.extend(d.get("games",[]))
                    for game in games2:
                        for side in ["home","away"]:
                            prob  = game.get("teams",{}).get(side,{}).get("probablePitcher",{})
                            pname = _norm(prob.get("fullName","") or "")
                            if _last and _last in pname:
                                result = _build(game, side)
                                result["game_date"] = _tomorrow
                                return result
            except Exception:
                pass

        except Exception:
            pass
        return {}

    @st.cache_data(ttl=1800, show_spinner=False)
    def _mlb_get_opp_from_team(team_abbr: str) -> str:
        """Get tonight's opponent for a team by abbreviation."""
        try:
            import requests as _req, datetime, pytz
            et    = pytz.timezone("America/New_York")
            today = datetime.datetime.now(et).strftime("%Y-%m-%d")
            r = _req.get(
                "https://statsapi.mlb.com/api/v1/schedule",
                params={"sportId": 1, "date": today, "hydrate": "team"},
                timeout=8
            )
            if not r.ok: return ""
            for d in r.json().get("dates", []):
                for game in d.get("games", []):
                    home = game["teams"]["home"]["team"].get("abbreviation","")
                    away = game["teams"]["away"]["team"].get("abbreviation","")
                    if home.upper() == team_abbr.upper():
                        return away
                    if away.upper() == team_abbr.upper():
                        return home
        except Exception:
            pass
        return ""

    @st.cache_data(ttl=7200, show_spinner=False)
    def mlb_get_pitcher_season_stats(player_name: str) -> dict:
        """
        Fetch pitcher's season-level stats: K/9, K/BF proxy, BB/9, ERA, avg IP/start.
        Returns dict with keys: k9, swstr, bb9, era, avg_ip, whip
        """
        empty = {}
        try:
            import requests as _req
            _norm = lambda s: s.lower().strip()
            _target = _norm(player_name)
            _last   = _target.split()[-1]
            _parts  = [p for p in _target.split() if len(p) > 2]

            # Find player ID
            r = _req.get("https://statsapi.mlb.com/api/v1/sports/1/players",
                         params={"season": datetime.now().year, "gameType": "R"},
                         timeout=8)
            if not r.ok: return empty
            people = r.json().get("people", [])
            # Match by name
            pitcher = next((p for p in people
                           if _norm(p.get("fullName","")) == _target), None)
            if not pitcher:
                pitcher = next((p for p in people
                               if all(pt in _norm(p.get("fullName","")) for pt in _parts)), None)
            if not pitcher:
                pitcher = next((p for p in people
                               if _last in _norm(p.get("fullName","")) and
                               p.get("primaryPosition",{}).get("code") == "1"), None)
            if not pitcher:
                return empty
            pid = pitcher["id"]

            current_year = datetime.now().year
            for season in [current_year, current_year - 1]:
                sr = _req.get(
                    f"https://statsapi.mlb.com/api/v1/people/{pid}/stats",
                    params={"stats": "season", "group": "pitching",
                            "season": season, "gameType": "R"},
                    timeout=8
                )
                if not sr.ok:
                    continue
                splits = sr.json().get("stats", [{}])[0].get("splits", [])
                stat = splits[0].get("stat", {}) if splits else {}
                if not stat:
                    continue

                ip_str = str(stat.get("inningsPitched", "0") or "0")
                try:
                    whole, _, partial = ip_str.partition(".")
                    ip_f = int(whole or 0) + (int(partial or 0) / 3.0)
                except Exception:
                    ip_f = 0.0
                starts = int(stat.get("gamesStarted", 0) or 0)
                if season == current_year and starts < 2 and ip_f < 8:
                    continue

                strikeouts = float(stat.get("strikeOuts", 0) or 0)
                walks = float(stat.get("baseOnBalls", 0) or 0)
                bf = int(stat.get("battersFaced", 0) or 0)
                total_pitches = int(stat.get("numberOfPitches", 0) or 0)
                k9 = round(strikeouts / max(ip_f, 1) * 9, 2)
                bb9 = round(walks / max(ip_f, 1) * 9, 2)
                era = float(stat.get("era", "0") or 0)
                whip = float(stat.get("whip", "0") or 0)
                avg_ip = round(ip_f / max(starts, 1), 1)
                k_rate = round(strikeouts / bf, 3) if bf > 0 else None
                pitches_per_bf = (
                    round(total_pitches / bf, 3)
                    if total_pitches > 0 and bf >= 20 else None
                )
                return {
                    "k9": k9, "swstr": k_rate, "bb9": bb9, "era": era,
                    "avg_ip": avg_ip, "whip": whip, "ip_total": ip_f,
                    "starts": starts, "season": season,
                    "batters_faced": bf, "total_pitches": total_pitches,
                    "pitches_per_bf": pitches_per_bf,
                }
        except Exception:
            return empty


    @st.cache_data(ttl=7200, show_spinner=False)
    def mlb_get_opp_k_rate_splits(opp_abbr: str, pitcher_hand: str = "R") -> dict:
        """
        Fetch opponent K% split by pitcher handedness (vs L or vs R).
        Returns {"vs_r": float, "vs_l": float, "overall": float}
        """
        empty = {"vs_r": None, "vs_l": None, "overall": None}
        try:
            import requests as _req
            season = datetime.now().year
            # Get team ID
            tr = _req.get("https://statsapi.mlb.com/api/v1/teams",
                          params={"sportId":1,"season":season}, timeout=7)
            if not tr.ok: return empty
            team = next((t for t in tr.json().get("teams",[])
                        if mlb_norm_abbr(t.get("abbreviation","")) == mlb_norm_abbr(opp_abbr)), None)
            if not team: return empty
            tid = team["id"]

            # Fetch hitting splits vs L and vs R
            result = {"vs_r": None, "vs_l": None, "overall": None}
            for split_type, key in [("vr", "vs_r"), ("vl", "vs_l")]:
                try:
                    sr = _req.get(
                        f"https://statsapi.mlb.com/api/v1/teams/{tid}/stats",
                        params={"stats": "statSplits", "group": "hitting",
                                "season": season, "sitCodes": split_type},
                        timeout=7
                    )
                    if sr.ok:
                        st_data = sr.json().get("stats",[{}])[0].get("splits",[{}])
                        for sp in st_data:
                            s = sp.get("stat",{})
                            pa = int(s.get("plateAppearances", 0) or 0)
                            ab = int(s.get("atBats", 0) or 0)
                            denom = pa if pa > 0 else ab
                            k = int(s.get("strikeOuts", 0) or 0)
                            if denom > 0:
                                result[key] = round(k / denom, 3)
                except Exception:
                    pass

            # Overall K%
            try:
                overall_r = _req.get(
                    f"https://statsapi.mlb.com/api/v1/teams/{tid}/stats",
                    params={"stats":"season","group":"hitting","season":season}, timeout=7
                )
                if overall_r.ok:
                    s = overall_r.json().get("stats",[{}])[0].get("splits",[{}])[0].get("stat",{})
                    pa = int(s.get("plateAppearances", 0) or 0)
                    ab = int(s.get("atBats", 0) or 0)
                    denom = pa if pa > 0 else ab
                    k = int(s.get("strikeOuts", 0) or 0)
                    result["overall"] = round(k / denom, 3) if denom > 0 else None
            except Exception:
                pass

            return result
        except Exception:
            return empty


    @st.cache_data(ttl=3600, show_spinner=False)
    def mlb_get_opp_plate_profile(opp_abbr: str) -> dict:
        """
        Opponent plate-discipline profile for pitcher outs.
        BB% is a major outs killer because long innings shorten leash.
        """
        empty = {"k_rate": None, "bb_rate": None, "pa": None,
                 "pitches_per_pa": None, "profile": "Neutral"}
        if not opp_abbr:
            return empty
        try:
            import requests as _req
            season = datetime.now().year
            tr = _req.get(
                "https://statsapi.mlb.com/api/v1/teams",
                params={"sportId": 1, "season": season},
                timeout=7,
            )
            if not tr.ok:
                return empty
            target = mlb_norm_abbr(opp_abbr)
            team = next((t for t in tr.json().get("teams", [])
                         if mlb_norm_abbr(t.get("abbreviation", "")) == target), None)
            if not team:
                return empty
            sr = _req.get(
                f"https://statsapi.mlb.com/api/v1/teams/{team['id']}/stats",
                params={"stats": "season", "group": "hitting", "season": season},
                timeout=7,
            )
            if not sr.ok:
                return empty
            stat = sr.json().get("stats", [{}])[0].get("splits", [{}])[0].get("stat", {})
            pa = int(stat.get("plateAppearances", 0) or 0)
            ab = int(stat.get("atBats", 0) or 0)
            denom = pa if pa > 0 else ab
            if denom <= 0:
                return empty
            k_rate = int(stat.get("strikeOuts", 0) or 0) / denom
            bb_rate = int(stat.get("baseOnBalls", 0) or 0) / denom
            pitches_seen = int(stat.get("numberOfPitches", 0) or 0)
            pitches_per_pa = (
                pitches_seen / pa if pitches_seen > 0 and pa > 0 else None
            )
            if k_rate >= 0.255 and bb_rate <= 0.085:
                profile = "Aggressive K"
            elif k_rate <= 0.195 and bb_rate >= 0.095:
                profile = "Grinder"
            elif k_rate <= 0.205:
                profile = "Contact"
            elif bb_rate >= 0.100:
                profile = "Patient"
            else:
                profile = "Neutral"
            return {
                "k_rate": round(k_rate, 3), "bb_rate": round(bb_rate, 3),
                "pa": denom,
                "pitches_per_pa": round(pitches_per_pa, 3) if pitches_per_pa else None,
                "profile": profile,
            }
        except Exception:
            return empty


    @st.cache_data(ttl=3600, show_spinner=False)
    def mlb_l10_opponent_difficulty(
        opps: tuple,
        pitcher_hand: str,
        tonight_opp: str,
        tonight_k_rate: Optional[float],
        side: str,
    ) -> dict:
        """
        Compare tonight's opponent K profile to the pitcher's recent opponent mix.
        Team record is intentionally ignored; K/contact profile is the useful input.
        """
        empty = {
            "adj": 0.0, "avg_recent_k": None, "tonight_k": tonight_k_rate,
            "delta": None, "games": 0, "label": "Neutral",
            "note": "No recent opponent context",
        }
        hand = str(pitcher_hand or "").upper()[:1]
        if not opps or tonight_k_rate is None or hand not in ("R", "L"):
            return empty
        try:
            hand_key = "vs_r" if hand == "R" else "vs_l"
            rates = []
            for raw_opp in list(opps)[:10]:
                opp_raw = str(raw_opp or "").upper()
                opp_raw = opp_raw.replace("VS.", "").replace("VS", "").replace("@", "")
                opp = mlb_norm_abbr(opp_raw)
                if not opp or opp in ("—", "-", "N/A"):
                    continue
                splits = mlb_get_opp_k_rate_splits(opp, pitcher_hand)
                rate = splits.get(hand_key) or splits.get("overall") or mlb_get_opp_k_rate(opp)
                if rate is not None and 0.10 <= float(rate) <= 0.40:
                    rates.append(float(rate))
            if len(rates) < 2:
                return {**empty, "note": "Not enough recent opponent K profiles"}

            recent_avg = sum(rates) / len(rates)
            delta = float(tonight_k_rate) - recent_avg
            adj = 0.0
            if delta >= 0.035:
                adj, label = 0.035, "Easier than L10"
            elif delta >= 0.020:
                adj, label = 0.020, "Slightly easier"
            elif delta <= -0.035:
                adj, label = -0.035, "Harder than L10"
            elif delta <= -0.020:
                adj, label = -0.020, "Slightly harder"
            else:
                label = "Similar to L10"

            if side == "Under":
                adj = -adj
            note = (
                f"Tonight {mlb_norm_abbr(tonight_opp) or 'opp'} K% {float(tonight_k_rate):.1%} "
                f"vs L10 opponent avg {recent_avg:.1%} ({len(rates)} profiles)"
            )
            return {
                "adj": adj,
                "avg_recent_k": round(recent_avg, 3),
                "tonight_k": round(float(tonight_k_rate), 3),
                "delta": round(delta, 3),
                "games": len(rates),
                "label": label,
                "note": note,
            }
        except Exception:
            return empty


    def mlb_ip_to_outs(ip_raw) -> int:
        try:
            s = str(ip_raw or "0")
            if "." in s:
                whole, frac = s.split(".", 1)
                return int(whole or 0) * 3 + int((frac or "0")[0])
            return int(float(s) * 3)
        except Exception:
            return 0


    @st.cache_data(ttl=1800, show_spinner=False)
    def mlb_get_bullpen_fatigue(team_abbr: str) -> dict:
        """
        Bullpen context for pitcher outs.
        Taxed pens can buy the starter extra leash; fresh pens shorten leash.
        """
        empty = {"signal": "Neutral", "relief_outs_l2": None, "games": 0}
        if not team_abbr:
            return empty
        try:
            import requests as _req, datetime as _dtx, pytz as _ptz
            et = _ptz.timezone("America/New_York")
            today = _dtx.datetime.now(et).date()
            target = mlb_norm_abbr(team_abbr)
            relief_outs = []
            for offset in range(1, 5):
                if len(relief_outs) >= 2:
                    break
                date_str = (today - _dtx.timedelta(days=offset)).strftime("%Y-%m-%d")
                r = _req.get(
                    "https://statsapi.mlb.com/api/v1/schedule",
                    params={"sportId": 1, "date": date_str, "hydrate": "team"},
                    timeout=7,
                )
                if not r.ok:
                    continue
                for day in r.json().get("dates", []):
                    for game in day.get("games", []):
                        status = str(game.get("status", {}).get("abstractGameState", "")).lower()
                        if status != "final":
                            continue
                        teams = game.get("teams", {})
                        home = teams.get("home", {}).get("team", {}).get("abbreviation", "")
                        away = teams.get("away", {}).get("team", {}).get("abbreviation", "")
                        side = None
                        if mlb_norm_abbr(home) == target:
                            side = "home"
                        elif mlb_norm_abbr(away) == target:
                            side = "away"
                        if not side or not game.get("gamePk"):
                            continue
                        br = _req.get(f"https://statsapi.mlb.com/api/v1/game/{game['gamePk']}/boxscore", timeout=7)
                        if not br.ok:
                            continue
                        box_team = br.json().get("teams", {}).get(side, {})
                        pitchers = box_team.get("pitchers", [])
                        players = box_team.get("players", {})
                        total_outs = starter_outs = 0
                        for idx, pid in enumerate(pitchers):
                            pdata = players.get(f"ID{pid}", {})
                            outs = mlb_ip_to_outs(pdata.get("stats", {}).get("pitching", {}).get("inningsPitched", "0"))
                            total_outs += outs
                            if idx == 0:
                                starter_outs = outs
                        if total_outs:
                            relief_outs.append(max(0, total_outs - starter_outs))
            if not relief_outs:
                return empty
            total_relief = sum(relief_outs[:2])
            if total_relief >= 24:
                signal = "Taxed"
            elif total_relief <= 9 and len(relief_outs) >= 2:
                signal = "Fresh"
            else:
                signal = "Neutral"
            return {"signal": signal, "relief_outs_l2": total_relief, "games": len(relief_outs)}
        except Exception:
            return empty


    @st.cache_data(ttl=3600, show_spinner=False)
    def mlb_get_umpire_k_tendency(home_team: str) -> dict:
        """
        Get today's home plate umpire assignment.
        The assignment is displayed, but remains model-neutral until a
        current-season called-strike data source is available.
        """
        try:
            import requests as _req, datetime, pytz
            et    = pytz.timezone("America/New_York")
            today = datetime.datetime.now(et).strftime("%Y-%m-%d")
            # Find game and umpire
            r = _req.get(
                "https://statsapi.mlb.com/api/v1/schedule",
                params={"sportId":1,"date":today,
                        "hydrate":"officials,team","fields":"dates,games,teams,officials,name,officialType"},
                timeout=8
            )
            if not r.ok: return {"name": None, "k_per_game": 15.5, "tendency": "Avg"}
            for d in r.json().get("dates",[]):
                for game in d.get("games",[]):
                    home = game.get("teams",{}).get("home",{}).get("team",{}).get("abbreviation","")
                    if home.upper() != home_team.upper(): continue
                    officials = game.get("officials",[])
                    hp_ump = next((o.get("official",{}).get("fullName","")
                                   for o in officials
                                   if o.get("officialType","").lower() in ("home plate","hp")), None)
                    if hp_ump:
                        # The assignment is authoritative, but the static
                        # historical tendency list is not a current-season
                        # tracking source. Keep it informational until a live
                        # called-strike sample is available.
                        return {"name": hp_ump, "k_per_game": 15.5,
                                "tendency": "Avg", "source": "assignment_only"}
        except Exception:
            pass
        return {"name": None, "k_per_game": 15.5, "tendency": "Avg"}


    @st.cache_data(ttl=7200, show_spinner=False)
    def mlb_get_pitcher_hand(player_name: str) -> str:
        """Get pitcher throwing hand. Unknown stays unknown; it is never guessed."""
        try:
            import requests as _req
            _norm   = lambda s: s.lower().strip()
            _target = _norm(player_name)
            _parts  = [p for p in _target.split() if len(p) > 2]
            r = _req.get("https://statsapi.mlb.com/api/v1/sports/1/players",
                         params={"season": datetime.now().year,"gameType":"R"},
                         timeout=7)
            if not r.ok: return ""
            people = r.json().get("people",[])
            p = next((x for x in people
                      if all(pt in _norm(x.get("fullName","")) for pt in _parts)), None)
            if p:
                hand = str(p.get("pitchHand", {}).get("code", "") or "").upper()
                return hand if hand in ("R", "L") else ""
        except Exception:
            pass
        return ""


